#[cfg(test)]
mod locale_files {
    use std::collections::BTreeSet;

    fn keys(text: &str) -> BTreeSet<String> {
        text.lines()
            .filter(|line| !line.starts_with([' ', '\t', '#']))
            .filter_map(|line| line.split_once(':'))
            .map(|(key, _)| key.trim().trim_matches('"').to_owned())
            .filter(|key| !key.is_empty())
            .collect()
    }

    #[test]
    fn all_languages_have_identical_key_sets() {
        let files = [
            ("en", include_str!("../locales/en.yml")),
            ("ja", include_str!("../locales/ja.yml")),
            ("ko", include_str!("../locales/ko.yml")),
            ("zh-CN", include_str!("../locales/zh-CN.yml")),
            ("zh-TW", include_str!("../locales/zh-TW.yml")),
        ];
        let base = keys(files[0].1);
        assert!(!base.is_empty());
        for (name, text) in &files[1..] {
            let other = keys(text);
            let missing: Vec<_> = base.difference(&other).collect();
            let extra: Vec<_> = other.difference(&base).collect();
            assert!(
                missing.is_empty() && extra.is_empty(),
                "{name}: missing {missing:?}, extra {extra:?}"
            );
        }
    }
}

use std::fs::{self, File};
use std::io;
use std::path::{Path, PathBuf};
use std::sync::Mutex;

use tracing::{error, warn};
use tracing_subscriber::layer::SubscriberExt;
use tracing_subscriber::util::SubscriberInitExt;
use tracing_subscriber::{EnvFilter, fmt};

const FILTER_ENV: &str = "Madoka_LOG";
const DEFAULT_DIRECTIVES: &str =
    "warn,launcher_core=debug,launcher_providers=debug,reqwest=debug,hyper_util=debug";
const LOG_FILE: &str = "launcher.log";
const PREVIOUS_LOG_FILE: &str = "launcher.previous.log";

/// Writes records to stderr and to `launcher.log` in `launcher_core::log_dir(root)`.
/// The previous log is kept as `launcher.previous.log`. `Madoka_LOG` overrides the filter.
/// Panics are recorded as `error` records.
pub fn init(root: &Path) -> PathBuf {
    let path = launcher_core::log_dir(root).join(LOG_FILE);
    let file = open_log_file(&path);
    let file_error = file.as_ref().err().map(ToString::to_string);

    let filter = EnvFilter::try_from_env(FILTER_ENV).unwrap_or_else(|_| default_filter());
    let file_layer = file
        .ok()
        .map(|file| fmt::layer().with_ansi(false).with_writer(Mutex::new(file)));
    tracing_subscriber::registry()
        .with(filter)
        .with(fmt::layer().with_writer(io::stderr))
        .with(file_layer)
        .init();

    if let Some(reason) = file_error {
        warn!(path = %path.display(), %reason, "log file is unavailable");
    }
    let previous = std::panic::take_hook();
    std::panic::set_hook(Box::new(move |info| {
        error!(%info, "panic");
        previous(info);
    }));
    path
}

/// The target of this crate is the binary name (`Madoka_Launcher`), not the package name.
fn default_filter() -> EnvFilter {
    let target = module_path!().split("::").next().unwrap_or_default();
    EnvFilter::new(format!("{DEFAULT_DIRECTIVES},{target}=debug"))
}

fn open_log_file(path: &Path) -> io::Result<File> {
    if let Some(dir) = path.parent() {
        fs::create_dir_all(dir)?;
        if path.exists() {
            fs::rename(path, dir.join(PREVIOUS_LOG_FILE))?;
        }
    }
    File::create(path)
}

