const DELETE_STEPS: u16 = 1;
const LAUNCH_STEPS: u16 = 2;
const WRITE_STEPS: u16 = 1;
const UPDATE_STEPS: u16 = 1;
const RESOLVE_STEPS: u16 = 1;
const BROWSER_EXE: &str = if cfg!(windows) {
    "Madoka-Browser.exe"
} else {
    "Madoka-Browser"
};
const BROWSER_SAVED_PREFIX: &str = "saved ";
const BROWSED_DIR: &str = "downloads";
const BROWSER_PROFILE_DIR: &str = "browser-profile";
const PART_SUFFIX: &str = ".part";
const DEFAULT_FILE_NAME: &str = "download";
const UNKNOWN_VERSION: &str = "-";
const LOCAL_VERSION: &str = "local";
/// Largest screenshot that `Services::fetch_image` returns.
const IMAGE_LIMIT_BYTES: usize = 8 * 1024 * 1024;
const PLUGIN_ARCHIVE_EXTENSION: &str = "ymme";
const ZIP_EXTENSION: &str = "zip";
const FORBIDDEN_FILE_CHARS: [char; 9] = ['<', '>', ':', '"', '/', '\\', '|', '?', '*'];

#[derive(Debug, thiserror::Error)]
pub enum OpError {
    #[error("{0}")]
    Core(Box<Error>),
    #[error("{0}")]
    Provider(Box<ProviderError>),
    #[error("worker failed: {0}")]
    Worker(String),
    #[error("no install procedure for {0}")]
    Unsupported(String),
    /// A message that is already translated.
    #[error("{0}")]
    Localized(String),
}

impl From<Error> for OpError {
    fn from(error: Error) -> Self {
        match error {
            Error::MinOsUnsupported { required } => {
                Self::Localized(t!("min_os_unsupported", required = required).into_owned())
            }
            Error::LaunchFailed { .. } if Host::current() == Host::MacOs => {
                Self::Localized(format!("{error}\n{}", t!("gatekeeper_hint")))
            }
            error => Self::Core(Box::new(error)),
        }
    }
}

impl From<ProviderError> for OpError {
    fn from(error: ProviderError) -> Self {
        Self::Provider(Box::new(error))
    }
}

#[derive(Debug, Clone, Default)]
