    pub unavailable: Vec<String>,
}

/// A download that the browser window completed.
#[derive(Debug, Clone)]
pub struct Browsed {
    pub url: Url,
    pub name: Option<String>,
    /// File that the browser window saved with the session of the page.
    /// `None` when the file still has to be fetched from `url`.
    pub saved: Option<PathBuf>,
}

impl Browsed {
    /// File name that the browser reported, else the last segment of the URL path, else `download`.
    fn file_name(&self) -> String {
        let from_url = || {
            let segment = self.url.path_segments()?.next_back()?;
            Some(
                percent_encoding::percent_decode_str(segment)
                    .decode_utf8_lossy()
                    .into_owned(),
            )
        };
        let raw = self.name.clone().or_else(from_url).unwrap_or_default();
        let name: String = Path::new(&raw)
            .file_name()
            .map_or_default(|name| name.to_string_lossy().replace(FORBIDDEN_FILE_CHARS, "_"));
        if name.is_empty() || name == ".." {
            DEFAULT_FILE_NAME.to_owned()
        } else {
            name
        }
    }

    pub fn label(&self) -> String {
        self.file_name()
    }
}

/// Returns the locale of `config.toml`.
/// A missing or unsupported value is replaced by the OS locale and written back.
fn stored_locale(config: &mut Config, root: &Path) -> Locale {
    if let Some(locale) = config.locale.as_deref().and_then(Locale::from_str) {
        return locale;
    }
    let locale = Locale::detect();
    config.locale = Some(locale.as_str().to_owned());
    if let Err(error) = config.save(root) {
        warn!(%error, "locale write failed");
    }
    locale
}

/// Everything a task needs. Clones share the task board, the locks and the installer.
#[derive(Clone)]
pub struct Services {
    pub host: Host,
    pub board: TaskBoard,
    root: PathBuf,
    theme: Option<String>,
    font: Option<String>,
    locale: Locale,
    dns_servers: Vec<IpAddr>,
    hide_deprecated_notice: bool,
    dns: Dns,
    browsed: Arc<ReqwestFetcher>,
    token: Option<String>,
    user_agent: Arc<str>,
    store: InstanceStore,
    installer: Arc<Installer<ReqwestFetcher>>,
    http: Arc<RwLock<ReqwestHttp>>,
    locks: InstanceLocks,
}

impl Services {
    pub fn new(root: PathBuf) -> Result<Self, OpError> {
        let mut config = Config::load(&root)?;
        let locale = stored_locale(&mut config, &root);
        let user_agent = format!("Madoka-Launcher/{}", env!("CARGO_PKG_VERSION"));
        let token = config.github_token.filter(|token| !token.trim().is_empty());
        let config_has_token = token.is_some();
        let theme = config.theme;
        let font = config.font;
        let dns_servers = config.dns;
        let hide_deprecated_notice = config.hide_deprecated_notice;
        let dns = Dns::new(&dns_servers);
        let http = ReqwestHttp::with_dns(&user_agent, token.clone(), dns.clone())
            .map_err(ProviderError::from)?;
        let fetcher = ReqwestFetcher::with_dns(&user_agent, dns.clone())?;
        let browsed = Arc::new(ReqwestFetcher::unrestricted(&user_agent, dns.clone())?);
        info!(
            root = %root.display(),
            host = ?Host::current(),
            github_token = config_has_token,
            "services ready"
        );
        Ok(Self {
            host: Host::current(),
            board: TaskBoard::default(),
            theme,
            font,
            locale,
            dns_servers,
            hide_deprecated_notice,
            dns,
            browsed,
            token,
            user_agent: user_agent.into(),
            store: InstanceStore::new(&root),
            root: root.clone(),
            installer: Arc::new(Installer::new(root, fetcher)),
            http: Arc::new(RwLock::new(http)),
            locks: InstanceLocks::default(),
        })
    }

    pub fn root(&self) -> &std::path::Path {
        &self.root
    }

    /// `true` while the data directory is `<executable directory>/data`.
    pub fn is_portable(&self) -> bool {
        let same = |dir: &Path| {
            dir == self.root
                || matches!(
                    (dir.canonicalize(), self.root.canonicalize()),
                    (Ok(a), Ok(b)) if a == b
                )
        };
        portable_root().is_some_and(|dir| same(&dir))
    }

    /// Copies the data to the directory of the other mode. The next start uses that directory.
    pub async fn switch_portable(self, handle: TaskHandle, enabled: bool) -> Result<(), OpError> {
        handle.running(0, WRITE_STEPS);
        let result = blocking(move || set_portable(enabled)).await;
        handle.finish(&result);
        result
    }

    /// GitHub token that `config.toml` held at start.
    pub fn token(&self) -> Option<&str> {
        self.token.as_deref()
    }

    fn http(&self) -> ReqwestHttp {
        self.http
            .read()
            .unwrap_or_else(PoisonError::into_inner)
            .clone()
    }

    /// Name of the theme stored in `config.toml`.
    pub fn theme_name(&self) -> Option<&str> {
        self.theme.as_deref()
    }

    /// DNS servers stored in `config.toml`. Empty selects the built-in default.
    pub fn dns_servers(&self) -> &[IpAddr] {
        &self.dns_servers
    }

    /// Writes the DNS servers to `config.toml`. They apply at the next start.
    pub async fn save_dns(self, servers: Vec<IpAddr>) -> Result<(), OpError> {
        let root = self.root.clone();
        blocking(move || {
            let mut config = Config::load(&root)?;
            config.dns = servers;
            config.save(&root)
        })
        .await
    }

    /// `true` when `config.toml` kept the dialog of installed deprecated packages closed at start.
    pub const fn hides_deprecated_notice(&self) -> bool {
        self.hide_deprecated_notice
    }

    /// Writes the choice to keep the dialog of installed deprecated packages closed to `config.toml`.
    pub async fn save_hide_deprecated_notice(self) -> Result<(), OpError> {
        let root = self.root.clone();
        blocking(move || {
            let mut config = Config::load(&root)?;
            config.hide_deprecated_notice = true;
            config.save(&root)
        })
        .await
    }

    /// Family name of the font stored in `config.toml`.
    pub fn font_name(&self) -> Option<&str> {
        self.font.as_deref()
    }

    /// Writes the font family to `config.toml`. It applies at the next start.
    pub async fn save_font(self, name: Option<String>) -> Result<(), OpError> {
        let root = self.root.clone();
        blocking(move || {
            let mut config = Config::load(&root)?;
            config.font = name;
            config.save(&root)
        })
        .await
    }

    pub async fn save_theme(self, name: String) -> Result<(), OpError> {
        let root = self.root.clone();
        blocking(move || {
            let mut config = Config::load(&root)?;
            config.theme = Some(name);
            config.save(&root)
        })
        .await
    }

    /// Locale selected at startup.
    pub const fn locale(&self) -> Locale {
        self.locale
    }

    /// Writes the locale code to `config.toml`.
    pub async fn save_locale(self, locale: Locale) -> Result<(), OpError> {
        let root = self.root.clone();
        blocking(move || {
            let mut config = Config::load(&root)?;
            config.locale = Some(locale.as_str().to_owned());
            config.save(&root)
        })
        .await
    }

    /// Writes the token to `config.toml` and applies it to the following requests.
    pub async fn save_token(self, token: String) -> Result<(), OpError> {
        let token = Some(token.trim().to_owned()).filter(|token| !token.is_empty());
        let root = self.root.clone();
        let stored = token.clone();
        blocking(move || {
            let mut config = Config::load(&root)?;
            config.github_token = stored;
            config.save(&root)
        })
        .await?;
        let http = ReqwestHttp::with_dns(&self.user_agent, token, self.dns.clone())
            .map_err(ProviderError::from)?;
        *self.http.write().unwrap_or_else(PoisonError::into_inner) = http;
        Ok(())
    }

    pub async fn list(self) -> Result<Loaded, OpError> {
        let store = self.store.clone();
        let listing = blocking(move || store.list()).await?;
        Ok(Loaded {
            instances: listing.instances,
            failures: listing
                .failures
                .into_iter()
                .map(|failure| format!("{}: {}", failure.dir.display(), failure.error))
                .collect(),
        })
    }

    fn self_updater(&self) -> SelfUpdater {
        SelfUpdater::new(
            &self.user_agent,
            self.dns.clone(),
            self.token.clone(),
            env!("CARGO_PKG_VERSION"),
        )
    }

    /// Version of the latest launcher release when it is newer than the running version.
    pub async fn check_update(self) -> Result<Option<String>, OpError> {
        let updater = self.self_updater();
        let result = run_blocking(move || updater.check()).await;
        match &result {
            Ok(version) => info!(?version, "update check done"),
            Err(error) => warn!(%error, "update check failed"),
        }
        result
    }

    /// Replaces the launcher executables with release `version`. The new version runs after a restart.
    pub async fn self_update(self, handle: TaskHandle, version: String) -> Result<(), OpError> {
        handle.running(0, UPDATE_STEPS);
        let updater = self.self_updater();
        let sink: Arc<dyn ProgressSink> = Arc::new(handle.sink());
        let result = run_blocking(move || updater.update(&version, &sink)).await;
        log_outcome("self update", &result);
        handle.finish(&result);
        result
    }

    pub async fn app_versions(self, kind: Kind) -> Result<Versions, OpError> {
        let provider = MadokaProvider::for_kind(kind, self.http())?;
        let result = provider.versions().await;
        match &result {
            Ok(versions) => info!(
                ?kind,
                app = versions.app.len(),
                addon = versions.addon.len(),
                "app versions loaded"
            ),
            Err(error) => warn!(?kind, %error, "app versions failed"),
        }
        Ok(result?)
    }

    /// Reads the app and addon versions that `update_all` would install.
    pub async fn app_updates(self, id: InstanceId) -> Result<AppUpdates, OpError> {
        let store = self.store.clone();
        let instance = blocking(move || store.load(id)).await?;
        let config = &instance.config;
        let provider = MadokaProvider::for_kind(config.kind, self.http())?;
        let selection = AppSelection {
            host: self.host,
            arch: Arch::current(),
            edition: config.edition,
            bundle: config.bundle,
        };
        let versions = provider.versions().await?;
        let (app, addon) = newer_app_versions(&provider, config, selection, &versions);
        Ok(AppUpdates {
            app: app.map(|latest| (config.app_version.clone(), latest.version)),
            addon: addon.map(|latest| {
                (
                    config.addon_version.clone().unwrap_or_default(),
                    latest.version,
                )
            }),
        })
    }

    /// Packages of the catalog. A cache file younger than 24 hours is used unless `refresh` is set.
    /// A failed request falls back to the cache file of any age.
    pub async fn catalog(self, kind: Kind, refresh: bool) -> Result<Vec<Package>, OpError> {
        let root = self.root.clone();
        if !refresh {
            let cached = tokio::task::spawn_blocking({
                let root = root.clone();
                move || load_fresh(&root, kind)
            })
            .await
            .map_err(|error| OpError::Worker(error.to_string()))?;
            if let Some(packages) = cached {
                info!(?kind, count = packages.len(), "catalog cache hit");
                return Ok(packages);
            }
        }
        let provider = MadokaProvider::for_kind(kind, self.http())?;
        match provider.catalog().await {
            Ok(packages) => {
                info!(?kind, count = packages.len(), "catalog loaded");
                let stored = packages.clone();
                let written =
                    tokio::task::spawn_blocking(move || store_catalog(&root, kind, &stored)).await;
                if let Ok(Err(error)) = written {
                    warn!(?kind, %error, "catalog cache write failed");
                }
                Ok(packages)
            }
            Err(error) => {
                warn!(?kind, %error, "catalog failed");
                let stale = tokio::task::spawn_blocking(move || load_any(&root, kind))
                    .await
                    .ok()
                    .flatten();
                stale.ok_or_else(|| error.into())
            }
        }
    }

    /// Resolves how `package` is installed. Requests the release list when the plan needs it.
    pub async fn plan(
        self,
        kind: Kind,
        package: Package,
    ) -> Result<(Package, InstallPlan), OpError> {
        let provider = MadokaProvider::for_kind(kind, self.http())?;
        let plan = provider.plan_install_package(&package).await?;
        Ok((package, plan))
    }

    /// Keeps the versions that have an artifact for `selection`.
    pub fn installable(
        &self,
        kind: Kind,
        selection: AppSelection,
        versions: &[AppVersion],
    ) -> Vec<AppVersion> {
        let Ok(provider) = MadokaProvider::for_kind(kind, self.http()) else {
            return Vec::new();
        };
        versions
            .iter()
            .filter(|version| provider.plan_install_app(version, selection).is_ok())
            .cloned()
            .collect()
    }

    /// Shows `url` in the browser window and waits until the window closes.
    /// The window keeps its cookies in `<root>/browser-profile/`, so a login lasts across launches.
    /// A download that starts in the page is saved by the window into `<root>/downloads/`
    /// with the session of the page. The window closes when the file is complete,
    /// and the result names that file.
    pub async fn browse(self, url: Url) -> Result<Option<Browsed>, OpError> {
        ensure_web(&url)?;
        let exe = std::env::current_exe()
            .map_err(|error| OpError::Worker(error.to_string()))?
            .with_file_name(BROWSER_EXE);
        let worker = |error: std::io::Error| OpError::Worker(format!("{}: {error}", exe.display()));
        let profile = std::path::absolute(self.root.join(BROWSER_PROFILE_DIR)).map_err(worker)?;
        let saves = std::path::absolute(self.root.join(BROWSED_DIR)).map_err(worker)?;
        let mut child = Command::new(&exe)
            .arg(url.as_str())
            .arg("--profile")
            .arg(&profile)
            .arg("--save-dir")
            .arg(&saves)
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .kill_on_drop(true)
            .spawn()
            .map_err(worker)?;
        let stdout = child
            .stdout
            .take()
            .ok_or_else(|| OpError::Worker("browser stdout is unavailable".to_owned()))?;
        let mut stderr = child
            .stderr
            .take()
            .ok_or_else(|| OpError::Worker("browser stderr is unavailable".to_owned()))?;
        let mut lines = BufReader::new(stdout).lines();
        let mut found = None;
        while let Some(line) = lines.next_line().await.map_err(worker)? {
            let Some((path, source)) = line
                .strip_prefix(BROWSER_SAVED_PREFIX)
                .and_then(|rest| rest.split_once('\t'))
            else {
                continue;
            };
            let path = PathBuf::from(path);
            if let Ok(source) = Url::parse(source) {
                found = Some(Browsed {
                    url: source,
                    name: path
                        .file_name()
                        .map(|name| name.to_string_lossy().into_owned()),
                    saved: Some(path),
                });
                break;
            }
        }
        if found.is_some() {
            child.wait().await.map_err(worker)?;
        } else {
            let status = child.wait().await.map_err(worker)?;
            if !status.success() {
                let mut message = String::new();
                stderr.read_to_string(&mut message).await.map_err(worker)?;
                let message = message.trim();
                warn!(%url, %status, message, "browser failed");
                return Err(OpError::Worker(format!("{status}: {message}")));
            }
        }
        info!(%url, downloaded = found.is_some(), "browser closed");
        Ok(found)
    }

    /// Saves the browsed download to `<root>/downloads/`.
    /// A `.zip` file of a package with a recipe or a `.ymme` file is then installed into instance `id`.
    /// Any other file fails with `OpError::Unsupported`; the saved file stays.
    pub async fn download_browsed(
        self,
        handle: TaskHandle,
        id: InstanceId,
        package: Package,
        browsed: Browsed,
    ) {
        info!(%id, package = %package.id, url = %browsed.url, "browsed download task start");
        let result = self
            .download_browsed_inner(&handle, id, &package, &browsed)
            .await;
        log_outcome("browsed download", &result);
        handle.finish(&result);
    }

    /// Fetches `browsed.url` into `<root>/downloads/` without the session of the browser window.
    async fn fetch_browsed(
        &self,
        handle: &TaskHandle,
        browsed: &Browsed,
    ) -> Result<PathBuf, OpError> {
        let dir = self.root.join(BROWSED_DIR);
        let name = browsed.file_name();
        let dest = blocking(move || {
            std::fs::create_dir_all(&dir).map_err(|source| Error::Io {
                path: dir.clone(),
                source,
            })?;
            Ok(unique_path(&dir, &name))
        })
        .await?;
        let mut part = dest.clone().into_os_string();
        part.push(PART_SUFFIX);
        let part = PathBuf::from(part);
        if let Err(error) = self.browsed.fetch(&browsed.url, &part, handle).await {
            let _ = std::fs::remove_file(&part);
            return Err(error.into());
        }
        std::fs::rename(&part, &dest).map_err(|source| Error::Io {
            path: dest.clone(),
            source,
        })?;
        Ok(dest)
    }

    async fn download_browsed_inner(
        &self,
        handle: &TaskHandle,
        id: InstanceId,
        package: &Package,
        browsed: &Browsed,
    ) -> Result<PathBuf, OpError> {
        ensure_web(&browsed.url)?;
        handle.running(0, WRITE_STEPS);
        let dest = match &browsed.saved {
            Some(path) => path.clone(),
            None => self.fetch_browsed(handle, browsed).await?,
        };
        let recipe = match &package.source {
            PackageSource::Recipe(recipe) if is_zip(&dest) => Some(recipe.clone()),
            _ => None,
        };
        if recipe.is_none() && !is_plugin_archive(&dest) {
            return Err(OpError::Unsupported(dest.display().to_string()));
        }
        let _guard = self.locks.lock(id).await;
        let installer = Arc::clone(&self.installer);
        let package = package.clone();
        let version = package
            .latest_version()
            .unwrap_or(UNKNOWN_VERSION)
            .to_owned();
        let archive = dest.clone();
        blocking(move || {
            let record = recipe.map_or_else(
                || installer.install_package_file(id, &package, &version, &archive),
                |recipe| installer.install_recipe_file(id, &package, &recipe, &archive),
            );
            record.map(drop)
        })
        .await?;
        Ok(dest)
    }

    pub async fn open_folder(self, dir: PathBuf) -> Result<(), OpError> {
        let host = self.host;
        blocking(move || open_directory(&dir, host)).await
    }

    /// Creates the instance directory, then installs the app into it.
    /// Deletes the instance directory when the installation fails.
    pub async fn create(self, handle: TaskHandle, request: CreateRequest) -> Option<InstanceId> {
        info!(name = %request.name, kind = ?request.kind, version = %request.version.version, addon = ?request.addon.as_ref().map(|addon| &addon.version), "create task start");
        let result = self.create_instance(&handle, request).await;
        log_outcome("create", &result);
        handle.finish(&result);
        result.ok()
    }

    /// Copies the install at `request.source` into a new instance, reads its version
    /// from the file hashes, and registers the plugins that the catalog recognizes.
    pub async fn import(self, handle: TaskHandle, request: ImportRequest) -> Option<InstanceId> {
        info!(name = %request.name, kind = ?request.kind, source = %request.source.display(), "import task start");
        let result = self.import_instance(&handle, request).await;
        log_outcome("import", &result);
        handle.finish(&result);
        result.ok()
    }

    pub async fn delete(self, handle: TaskHandle, id: InstanceId) {
        info!(%id, "delete task start");
        let result = self.delete_instance(&handle, id).await;
        log_outcome("delete", &result);
        handle.finish(&result);
    }

