    async fn create_instance(
        &self,
        handle: &TaskHandle,
        request: CreateRequest,
    ) -> Result<InstanceId, OpError> {
        let CreateRequest {
            name,
            kind,
            edition,
            bundle,
            group,
            version,
            addon,
        } = request;
        handle.running(0, CREATE_STEPS);
        let provider = MadokaProvider::for_kind(kind, self.http())?;
        let selection = AppSelection {
            host: self.host,
            arch: Arch::current(),
            edition,
            bundle,
        };
        let mut artifacts = provider.plan_install_app(&version, selection)?;
        let mut checks = version.checks.clone();
        if let Some(addon) = &addon {
            artifacts.extend(provider.plan_install_app(addon, selection)?);
            checks.extend(addon.checks.iter().cloned());
        }
        debug!(
            version = %version.version,
            artifacts = ?artifacts.iter().map(|a| a.url.as_str()).collect::<Vec<_>>(),
            "install plan"
        );
        let instance = self.store.create(
            NewInstance {
                name,
                kind,
                edition,
                bundle,
                app_version: version.version.clone(),
                group,
            },
            self.host,
        )?;
        let id = instance.config.id;
        let _guard = self.locks.lock(id).await;
        handle.running(1, CREATE_STEPS);
        if let Err(error) = self
            .installer
            .install_app_checked(id, &artifacts, &checks, handle)
            .await
        {
            warn!(%id, %error, "install failed, deleting the instance");
            if let Err(cleanup) = self.store.delete(id) {
                error!(%id, error = %cleanup, "instance cleanup failed");
            }
            return Err(error.into());
        }
        if let Some(addon) = addon {
            let app_version = version.version;
            let store = self.store.clone();
            blocking(move || {
                store
                    .set_versions(id, app_version, Some(addon.version))
                    .map(drop)
            })
            .await?;
        }
        Ok(id)
    }

    async fn import_instance(
        &self,
        handle: &TaskHandle,
        request: ImportRequest,
    ) -> Result<InstanceId, OpError> {
        let ImportRequest {
            name,
            kind,
            edition,
            group,
            source,
            versions,
        } = request;
        handle.running(0, IMPORT_STEPS);
        let store = self.store.clone();
        let host = self.host;
        let instance = blocking(move || {
            let app_version = detect_version(&source, kind, host, &versions)
                .map_or_else(|| UNKNOWN_VERSION.to_owned(), |found| found.version.clone());
            store.import(
                NewInstance {
                    name,
                    kind,
                    edition,
                    bundle: Bundle::Archive,
                    app_version,
                    group,
                },
                &source,
                host,
            )
        })
        .await?;
        let id = instance.config.id;
        handle.running(1, IMPORT_STEPS);
        self.register_present_plugins(id, kind).await;
        Ok(id)
    }

    /// Records the catalog packages whose files the instance holds.
    /// A failure leaves the instance without records, so the import still succeeds.
    async fn register_present_plugins(&self, id: InstanceId, kind: Kind) {
        if !has_catalog(kind) {
            return;
        }
        let packages = match self.clone().catalog(kind, false).await {
            Ok(packages) => packages,
            Err(error) => {
                warn!(%id, %error, "catalog unavailable, plugin scan skipped");
                return;
            }
        };
        match self
            .clone()
            .scan_and_register_manual_plugins(id, packages)
            .await
        {
            Ok(found) => info!(%id, count = found.len(), "plugins registered after import"),
            Err(error) => warn!(%id, %error, "plugin scan failed"),
        }
    }

