fn log_outcome<T>(task: &str, result: &Result<T, OpError>) {
    match result {
        Ok(_) => info!(task, "task succeeded"),
        Err(error) => error!(task, %error, "task failed"),
    }
}

/// The newest stable version of `list` that `accepts`, unless `installed` is that version or newer.
/// `list` holds the newest version first.
fn newer_than(
    list: &[AppVersion],
    installed: Option<&str>,
    accepts: impl Fn(&AppVersion) -> bool,
) -> Option<AppVersion> {
    let (candidate, newest) = list
        .iter()
        .enumerate()
        .find(|(_, version)| !version.prerelease && accepts(version))?;
    let current = installed
        .and_then(|installed| list.iter().position(|version| version.version == installed));
    current
        .is_none_or(|current| current > candidate)
        .then(|| newest.clone())
}

/// Latest app and addon versions that have an artifact for `selection` and differ from `config`.
fn newer_app_versions<P: Provider>(
    provider: &P,
    config: &InstanceConfig,
    selection: AppSelection,
    versions: &Versions,
) -> (Option<AppVersion>, Option<AppVersion>) {
    let accepts = |version: &AppVersion| provider.plan_install_app(version, selection).is_ok();
    (
        newer_than(&versions.app, Some(&config.app_version), accepts),
        newer_than(&versions.addon, config.addon_version.as_deref(), accepts),
    )
}

/// Installed plugins whose catalog entry names another version than the record.
fn outdated_packages(plugins: &[PluginRecord], packages: &[Package]) -> Vec<Package> {
    plugins
        .iter()
        .filter(|record| !record.paused)
        .filter_map(|record| {
            let package = packages.iter().find(|package| package.id == record.id)?;
            let latest = package.latest_version()?;
            (latest != record.version).then(|| package.clone())
        })
        .collect()
}

/// The browser window supplies the archive when the plan has no verified download.
fn needs_browser(plan: &InstallPlan) -> bool {
    matches!(plan, InstallPlan::OpenInBrowser(_)) || !plan.is_verified()
}

fn is_zip(path: &Path) -> bool {
    path.extension()
        .is_some_and(|extension| extension.eq_ignore_ascii_case(ZIP_EXTENSION))
}

fn is_plugin_archive(path: &Path) -> bool {
    path.extension()
        .is_some_and(|extension| extension.eq_ignore_ascii_case(PLUGIN_ARCHIVE_EXTENSION))
}

fn ensure_web(url: &Url) -> Result<(), OpError> {
    if matches!(url.scheme(), "http" | "https") {
        Ok(())
    } else {
        Err(Error::UnsafePath(url.to_string()).into())
    }
}

/// `dir/name`, or the first free `dir/stem (n).ext`.
fn unique_path(dir: &Path, name: &str) -> PathBuf {
    let first = dir.join(name);
    if !first.exists() {
        return first;
    }
    let path = Path::new(name);
    let stem = path.file_stem().map_or_else(
        || name.to_owned(),
        |stem| stem.to_string_lossy().into_owned(),
    );
    let extension = path
        .extension()
        .map(|extension| extension.to_string_lossy().into_owned());
    let numbered = |n: u32| {
        let name = extension.as_ref().map_or_else(
            || format!("{stem} ({n})"),
            |extension| format!("{stem} ({n}).{extension}"),
        );
        dir.join(name)
    };
    (1..=u32::MAX)
        .map(numbered)
        .find(|candidate| !candidate.exists())
        .unwrap_or(first)
}

/// Sorted family names of the fonts installed on the OS.
pub async fn installed_fonts() -> Result<Vec<String>, OpError> {
    tokio::task::spawn_blocking(|| {
        let mut database = fontdb::Database::new();
        database.load_system_fonts();
        let mut families: Vec<String> = database
            .faces()
            .filter_map(|face| face.families.first().map(|(name, _)| name.clone()))
            .collect();
        families.sort();
        families.dedup();
        families
    })
    .await
    .map_err(|error| OpError::Worker(error.to_string()))
}

async fn run_blocking<T, F>(work: F) -> Result<T, OpError>
where
    T: Send + 'static,
    F: FnOnce() -> Result<T, ProviderError> + Send + 'static,
{
    let joined = tokio::task::spawn_blocking(work)
        .await
        .map_err(|error| OpError::Worker(error.to_string()))?;
    Ok(joined?)
}

async fn blocking<T, F>(work: F) -> Result<T, OpError>
where
    T: Send + 'static,
    F: FnOnce() -> Result<T, Error> + Send + 'static,
{
    let joined = tokio::task::spawn_blocking(work)
        .await
        .map_err(|error| OpError::Worker(error.to_string()))?;
    Ok(joined?)
}

#[cfg(test)]
mod tests {
    use super::*;
    use launcher_core::{
        Edition, FileCheck, Hash, HashAlgo, Location, NewInstance, Origin, Recipe, Root,
    };

    fn runtime() -> tokio::runtime::Runtime {
        tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .unwrap()
    }

    fn services(root: &Path) -> Services {
        Services::new(root.to_path_buf()).unwrap()
    }

    fn make_instance(services: &Services, kind: Kind) -> launcher_core::Instance {
        services
            .store
            .create(
                NewInstance {
                    name: "t".to_owned(),
                    kind,
                    edition: Edition::Normal,
                    bundle: launcher_core::Bundle::Archive,
                    app_version: "1".to_owned(),
                    group: None,
                },
                Host::Windows,
            )
            .unwrap()
    }

    fn record(id: &str, version: &str) -> PluginRecord {
        PluginRecord {
            id: id.to_owned(),
            version: version.to_owned(),
            source: "test".to_owned(),
            files: Vec::new(),
            paused: false,
            uninstall_steps: Vec::new(),
        }
    }

    #[test]
    fn scan_registers_manual_plugin_on_aviutl2_layout() {
        let root = tempfile::tempdir().unwrap();
        let services = services(root.path());
        let instance = make_instance(&services, Kind::Aviutl2);
        let app_dir = instance.app_dir();
        std::fs::write(app_dir.join("aviutl2.exe"), b"exe").unwrap();
        let plugin_dir = app_dir.join("data").join("Plugin");
        std::fs::create_dir_all(&plugin_dir).unwrap();
        let file = plugin_dir.join("foo.auf2");
        std::fs::write(&file, b"plugin body").unwrap();
        let hash = Hash::of_file(HashAlgo::Xxh3_128, &file).unwrap();

        let make = |id: &str, hash: Hash| {
            let url = Url::parse("https://example.com/").unwrap();
            let mut package = Package::simple(id, id, url.clone(), PackageSource::Web(url.clone()));
            package.source = PackageSource::Recipe(Recipe {
                version: "1.2".to_owned(),
                origin: Origin::Direct(url),
                hash: None,
                steps: Vec::new(),
                uninstall_steps: Vec::new(),
                checks: vec![FileCheck {
                    location: Location {
                        root: Root::Data,
                        rel: "Plugin/foo.auf2".to_owned(),
                    },
                    hash,
                }],
            });
            package
        };
        let wrong = Hash {
            algo: HashAlgo::Xxh3_128,
            hex: "0".repeat(32),
        };
        let packages = vec![make("match.id", hash), make("other.id", wrong)];

        let found = runtime()
            .block_on(
                services
                    .clone()
                    .scan_and_register_manual_plugins(instance.config.id, packages),
            )
            .unwrap();
        assert_eq!(found, vec!["match.id".to_owned()]);

        let loaded = services.store.load(instance.config.id).unwrap();
        assert_eq!(loaded.config.plugins.len(), 1);
        let plugin = &loaded.config.plugins[0];
        assert_eq!(plugin.id, "match.id");
        assert_eq!(plugin.version, "1.2");
        assert_eq!(plugin.files, vec!["data/Plugin/foo.auf2".to_owned()]);
    }

    #[test]
    fn restore_config_pauses_and_reports_version_difference() {
        let root = tempfile::tempdir().unwrap();
        let services = services(root.path());
        let instance = make_instance(&services, Kind::Aviutl2);
        let id = instance.config.id;
        services
            .store
            .add_or_update_plugin(id, record("a.plugin", "1.0"))
            .unwrap();
        let entries = vec![
            ConfigEntry {
                id: "a.plugin".to_owned(),
                version: Some("2.0".to_owned()),
                paused: true,
            },
            ConfigEntry {
                id: "definitely.not.in.catalog".to_owned(),
                version: None,
                paused: false,
            },
        ];
        let report = runtime().block_on(services.restore_config(
            Kind::Aviutl2,
            id,
            "install".to_owned(),
            entries,
        ));
        assert_eq!(report.installed, 0);
        assert_eq!(report.paused, 1);
        assert_eq!(
            report.version_differs,
            vec!["a.plugin (2.0 -> 1.0)".to_owned()]
        );
        assert_eq!(
            report.unavailable,
            vec!["definitely.not.in.catalog".to_owned()]
        );
    }
}

//! Splits a Markdown changelog into versions and extracts the range that an update brings.

/// One version section: the version in its heading and the Markdown of the whole section.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Section<'a> {
    pub version: Option<String>,
    pub text: &'a str,
}

/// Version found in a heading line, e.g. `## [1.2.3] - 2024-01-01` or `### v1.2`.
fn heading_version(line: &str) -> Option<String> {
    let rest = line.trim_start();
    let hashes = rest.chars().take_while(|c| *c == '#').count();
    if !(1..=4).contains(&hashes) {
        return None;
    }
    let title = rest.trim_start_matches('#').trim();
    if title.is_empty() {
        return None;
    }
    title
        .split(|c: char| c.is_whitespace() || matches!(c, '[' | ']' | '(' | ')' | ':' | ','))
        .map(|word| word.trim_start_matches(['v', 'V']))
        .find(|word| {
            word.chars().next().is_some_and(|c| c.is_ascii_digit())
                && word
                    .chars()
                    .all(|c| c.is_ascii_alphanumeric() || matches!(c, '.' | '-' | '_'))
                && !word.chars().all(|c| c.is_ascii_digit() && word.len() == 4)
        })
        .map(str::to_owned)
}

/// Sections that start at a heading with a version. Text before the first one is dropped.
pub fn split(changelog: &str) -> Vec<Section<'_>> {
    let mut starts: Vec<(usize, String)> = Vec::new();
    let mut offset = 0;
    let mut fenced = false;
    for line in changelog.split_inclusive('\n') {
        if line.trim_start().starts_with("```") {
            fenced = !fenced;
        } else if !fenced && let Some(version) = heading_version(line) {
            starts.push((offset, version));
        }
        offset += line.len();
    }
    let mut sections = Vec::with_capacity(starts.len());
    for (index, (start, version)) in starts.iter().enumerate() {
        let end = starts.get(index + 1).map_or(changelog.len(), |next| next.0);
        if let Some(text) = changelog.get(*start..end) {
            sections.push(Section {
                version: Some(version.clone()),
                text,
            });
        }
    }
    sections
}

fn normalize(version: &str) -> &str {
    version.trim().trim_start_matches(['v', 'V'])
}

/// Compares dotted versions numerically where parts are numbers.
fn compare(a: &str, b: &str) -> std::cmp::Ordering {
    let parts = |v: &str| -> Vec<u64> {
        normalize(v)
            .split(|c: char| !c.is_ascii_digit())
            .filter(|p| !p.is_empty())
            .map(|p| p.parse().unwrap_or(0))
            .collect()
    };
    parts(a).cmp(&parts(b))
}

/// Sections whose version is newer than `installed`.
/// `None` when the changelog has no version sections.
pub fn since<'a>(changelog: &'a str, installed: &str) -> Option<Vec<Section<'a>>> {
    let sections = split(changelog);
    if sections.is_empty() {
        return None;
    }
    Some(
        sections
            .into_iter()
            .filter(|section| {
                section.version.as_deref().is_some_and(|version| {
                    compare(version, installed) == std::cmp::Ordering::Greater
                })
            })
            .collect(),
    )
}

/// The changelog text of the versions newer than `installed`.
/// The whole `changelog` when it has no version sections.
pub fn range_text(changelog: &str, installed: &str) -> String {
    since(changelog, installed).map_or_else(
        || changelog.to_owned(),
        |sections| sections.iter().map(|section| section.text).collect(),
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    const LOG: &str =
        "# Changelog\n\n## [1.3.0] - 2024-03-01\n- c\n\n## v1.2.0\n- b\n\n## 1.0.0 (2023)\n- a\n";

    #[test]
    fn splits_per_version() {
        let sections = split(LOG);
        let versions: Vec<_> = sections.iter().map(|s| s.version.as_deref()).collect();
        assert_eq!(versions, [Some("1.3.0"), Some("1.2.0"), Some("1.0.0")]);
        assert!(sections[1].text.contains("- b"));
        assert!(!sections[1].text.contains("- c"));
    }

    #[test]
    fn extracts_range_after_installed() {
        let text = range_text(LOG, "1.2.0");
        assert!(text.contains("- c"));
        assert!(!text.contains("- b"));
        assert!(range_text(LOG, "v1.0.0").contains("- b"));
    }

    #[test]
    fn plain_text_is_returned_whole() {
        assert_eq!(range_text("fixed bugs", "1.0"), "fixed bugs");
    }
}

