fn id_refs(list: &[String]) -> Vec<&str> {
    list.iter().map(String::as_str).collect()
}

/// Relation sets in display order, as the locale key of the heading and the ids.
fn relation_sets(package: &Package) -> [(&'static str, Vec<&str>); 5] {
    let relations = &package.relations;
    [
        ("relation_recommends", id_refs(&relations.recommends)),
        ("relation_conflicts", id_refs(&relations.conflicts)),
        ("relation_similar", id_refs(&relations.similar)),
        ("relation_replaces", id_refs(&relations.replaces)),
        (
            "relation_fork_of",
            relations.fork_of.iter().map(String::as_str).collect(),
        ),
    ]
}

/// One card per non-empty relation set of `package`.
fn relation_cards<'a>(
    theme: &'a Theme,
    state: &State,
    instance: &Instance,
    package: &Package,
) -> Vec<Element<'a, Message>> {
    relation_sets(package)
        .into_iter()
        .filter(|(_, ids)| !ids.is_empty())
        .map(|(key, ids)| {
            let conflicting = key == "relation_conflicts";
            let chips: Vec<Element<'a, Message>> = ids
                .into_iter()
                .map(|id| {
                    let installed = instance.config.plugins.iter().any(|record| record.id == id);
                    let known = state.package(id);
                    let name = known.map_or(id, |found| found.name.as_str());
                    let (glyph, accent, suffix) = match (installed, known.is_some()) {
                        (true, _) if conflicting => (
                            style::icons::WARNING,
                            Accent::Secondary,
                            Some(t!("dep_installed")),
                        ),
                        (true, _) => (
                            style::icons::CHECK_CIRCLE,
                            Accent::Tertiary,
                            Some(t!("dep_installed")),
                        ),
                        (false, true) => (style::icons::LINK, Accent::Tertiary, None),
                        (false, false) => (
                            style::icons::LINK,
                            Accent::Secondary,
                            Some(t!("dep_not_in_catalog")),
                        ),
                    };
                    let label = suffix
                        .map_or_else(|| name.to_owned(), |suffix| format!("{name} ({suffix})"));
                    m3::button(
                        button::Style::tonal(theme, accent),
                        style::btn_content(glyph, label),
                    )
                    .on_press_maybe(
                        known.map(|found| Message::ViewPackageDetails(Some(found.id.clone()))),
                    )
                    .into()
                })
                .collect();
            let body = column![
                row![
                    style::icon(style::icons::LAYERS)
                        .size(18)
                        .color(theme.primary()),
                    style::label(theme, t!(key).into_owned()).size(15),
                ]
                .spacing(8)
                .align_y(Vertical::Center),
                row(chips).spacing(8).wrap(),
            ]
            .spacing(8)
            .padding(Padding::from([10.0, 14.0]));
            m3::card(card::Style::filled(theme), body)
                .width(Length::Fill)
                .into()
        })
        .collect()
}

fn package_detail_view<'a>(
    theme: &'a Theme,
    state: &'a State,
    instance: &'a Instance,
    package: &'a Package,
) -> Element<'a, Message> {
    let back_btn = m3::button(
        button::Style::tonal(theme, Accent::Primary),
        style::btn_content(style::icons::BACK, t!("back_to_list")),
    )
    .on_press(Message::ViewPackageDetails(None));

    let status = status_of(instance, package);
    let (status_text, status_icon, status_tone) = match status {
        Status::NotInstalled => (t!("not_installed"), style::icons::DOWNLOAD, Tone::Secondary),
        Status::Installed => (t!("installed"), style::icons::CHECK_CIRCLE, Tone::Tertiary),
        Status::UpdateAvailable => (t!("update_available"), style::icons::UPDATE, Tone::Primary),
    };

    let action = match (&package.source, status) {
        (PackageSource::Web(_), _) => Some((
            style::icons::OPEN_IN_NEW,
            t!("open_in_browser"),
            Message::Open(package.id.clone()),
        )),
        (_, Status::NotInstalled) => Some((
            style::icons::DOWNLOAD,
            t!("install"),
            Message::Install(package.id.clone()),
        )),
        (_, Status::UpdateAvailable) => Some((
            style::icons::UPDATE,
            t!("update"),
            Message::Install(package.id.clone()),
        )),
        (_, Status::Installed) => None,
    };
    let act = match action {
        Some((glyph, label, message)) => m3::button(
            button::Style::filled(theme, Accent::Primary),
            style::btn_content(glyph, label),
        )
        .on_press(message),
        None => m3::button(
            button::Style::tonal(theme, Accent::Primary),
            style::btn_content(style::icons::CHECK, t!("installed")),
        ),
    };

    let mut header = row![
        back_btn,
        style::label(theme, package.name.clone()).size(22),
        style::icon_chip::<Message>(theme, status_icon, status_text, status_tone),
    ]
    .spacing(12)
    .align_y(Vertical::Center);

    if package.deprecated {
        header = header.push(style::icon_chip::<Message>(
            theme,
            style::icons::WARNING,
            t!("deprecated_warning"),
            Tone::Error,
        ));
    }

    if let Some(commons_id) = &package.niconi_commons_id {
        header = header
            .push(style::icon_chip::<Message>(
                theme,
                style::icons::SHARE,
                commons_id,
                Tone::Tertiary,
            ))
            .push(commons_buttons(theme, commons_id));
    }

    header = header.push(act);

    let author_btn = m3::button(
        button::Style::tonal(theme, Accent::Secondary),
        style::btn_content(style::icons::PERSON, &package.author),
    )
    .on_press(Message::AuthorSelected(package.author.clone()));

    let meta_bar = row![
        style::icon(style::icons::PERSON)
            .size(16)
            .color(theme.primary()),
        text(format!("{}:", t!("author")))
            .size(13)
            .color(theme.outline()),
        author_btn,
        style::icon(style::icons::LINK)
            .size(16)
            .color(theme.primary()),
        text(t!("id_label", id = package.id).into_owned())
            .size(13)
            .color(theme.outline()),
    ]
    .spacing(8)
    .align_y(Vertical::Center);

    let mut content = column![header, meta_bar].spacing(12);

    if package.deprecated {
        let message = package
            .deprecation_message
            .clone()
            .unwrap_or_else(|| t!("deprecated_warning").into_owned());
        content = content.push(
            m3::card(
                card::Style {
                    container_color: theme.error_container(),
                    ..card::Style::filled(theme)
                },
                row![
                    style::icon(style::icons::WARNING)
                        .size(20)
                        .color(theme.error()),
                    text(message)
                        .size(13)
                        .color(theme.on_surface())
                        .width(Length::Fill),
                ]
                .spacing(10)
                .padding(Padding::from([10.0, 14.0]))
                .align_y(Vertical::Center),
            )
            .width(Length::Fill),
        );
    }

    // 6-19: Screenshot carousel
    if !package.screenshots.is_empty() {
        let len = package.screenshots.len();
        let idx = state.active_screenshot_idx.min(len - 1);
        let current_url = package.screenshots.get(idx).map_or("", String::as_str);

        let prev_btn = m3::button(
            button::Style::tonal(theme, Accent::Primary),
            style::btn_content(style::icons::BACK, t!("prev")),
        )
        .on_press(Message::PrevScreenshot(len));

        let next_btn = m3::button(
            button::Style::tonal(theme, Accent::Primary),
            style::btn_content(style::icons::LAUNCH, t!("next")),
        )
        .on_press(Message::NextScreenshot(len));

        let picture: Element<'a, Message> = match state.images.get(current_url) {
            Some(ImageState::Ready(handle)) => {
                let height = if state.preview_open {
                    PREVIEW_HEIGHT
                } else {
                    THUMBNAIL_HEIGHT
                };
                mouse_area(
                    image(handle.clone())
                        .width(Length::Fill)
                        .height(Length::Fixed(height))
                        .content_fit(ContentFit::Contain),
                )
                .on_press(Message::TogglePreview)
                .into()
            }
            Some(ImageState::Failed(reason)) => text(format!("{current_url}\n{reason}"))
                .size(13)
                .color(theme.error())
                .into(),
            _ => text(t!("image_loading").into_owned())
                .size(13)
                .color(theme.on_surface_variant())
                .into(),
        };

        let carousel_card = m3::card(
            card::Style::filled(theme),
            column![
                row![
                    style::icon(style::icons::IMAGE)
                        .size(20)
                        .color(theme.primary()),
                    text(t!("screenshot_position", index = idx + 1, total = len).into_owned())
                        .size(14),
                    prev_btn,
                    next_btn,
                ]
                .spacing(12)
                .align_y(Vertical::Center),
                m3::card(
                    style::tile_card(theme, false),
                    container(picture)
                        .padding(Padding::from([8.0, 12.0]))
                        .width(Length::Fill),
                )
                .width(Length::Fill),
            ]
            .spacing(8)
            .padding(Padding::from([10.0, 14.0])),
        )
        .width(Length::Fill);

        content = content.push(carousel_card);
    }

    // 6-20: Markdown overview
    let summary_card = m3::card(
        card::Style::filled(theme),
        column![
            row![
                style::icon(style::icons::DESCRIPTION)
                    .size(18)
                    .color(theme.primary()),
                style::label(theme, t!("package_overview").into_owned()).size(16),
            ]
            .spacing(8)
            .align_y(Vertical::Center),
            crate::screen::markdown::view(theme, &package.summary, Message::OpenLink),
        ]
        .spacing(8)
        .padding(Padding::from([12.0, 16.0])),
    )
    .width(Length::Fill);
    content = content.push(summary_card);

    // 6-21: Dependencies
    if !package.dependencies.is_empty() {
        let mut missing: Vec<&str> = Vec::new();
        let dep_chips: Vec<Element<'a, Message>> = package
            .dependencies
            .iter()
            .map(|dep| {
                let installed = instance
                    .config
                    .plugins
                    .iter()
                    .any(|record| record.id == *dep);
                let known = state.package(dep).is_some();
                if !installed {
                    missing.push(dep.as_str());
                }
                let state_label = if installed {
                    t!("dep_installed")
                } else if known {
                    t!("dep_missing")
                } else {
                    t!("dep_not_in_catalog")
                };
                let (glyph, accent) = if installed {
                    (style::icons::CHECK_CIRCLE, Accent::Tertiary)
                } else {
                    (style::icons::WARNING, Accent::Secondary)
                };
                m3::button(
                    button::Style::tonal(theme, accent),
                    style::btn_content(glyph, format!("{dep} ({state_label})")),
                )
                .on_press_maybe(known.then(|| Message::ViewPackageDetails(Some(dep.clone()))))
                .into()
            })
            .collect();

        let mut dep_column = column![
            row![
                style::icon(style::icons::LAYERS)
                    .size(18)
                    .color(theme.primary()),
                style::label(theme, t!("dependencies").into_owned()).size(15),
            ]
            .spacing(8)
            .align_y(Vertical::Center),
            row(dep_chips).spacing(8).wrap(),
        ]
        .spacing(8)
        .padding(Padding::from([10.0, 14.0]));
        if !missing.is_empty() {
            dep_column = dep_column.push(
                row![
                    style::icon(style::icons::WARNING)
                        .size(16)
                        .color(theme.error()),
                    text(t!("dep_missing_warning", ids = missing.join(", ")).into_owned())
                        .size(13)
                        .color(theme.error()),
                ]
                .spacing(6)
                .align_y(Vertical::Center),
            );
        }
        let dep_card = m3::card(card::Style::filled(theme), dep_column).width(Length::Fill);
        content = content.push(dep_card);
    }

    // PLAN 1: Relations other than the prerequisites
    content = relation_cards(theme, state, instance, package)
        .into_iter()
        .fold(content, iced::widget::Column::push);

    // 6-23: Licenses
    if !package.licenses.is_empty() {
        let lic_chips: Vec<Element<'a, Message>> = package
            .licenses
            .iter()
            .map(|lic| {
                m3::button(
                    button::Style::tonal(theme, Accent::Secondary),
                    style::btn_content(style::icons::POLICY, lic.name.as_str()),
                )
                .on_press(Message::ShowLicense(Some(lic.body.clone())))
                .into()
            })
            .collect();

        let lic_card = m3::card(
            card::Style::filled(theme),
            column![
                row![
                    style::icon(style::icons::POLICY)
                        .size(18)
                        .color(theme.primary()),
                    style::label(theme, t!("license").into_owned()).size(15),
                ]
                .spacing(8)
                .align_y(Vertical::Center),
                row(lic_chips).spacing(8),
            ]
            .spacing(8)
            .padding(Padding::from([10.0, 14.0])),
        )
        .width(Length::Fill);
        content = content.push(lic_card);
    }

    // 6-24 / 7-26: Changelog, split per version
    if let Some(changelog) = &package.changelog {
        let installed = instance
            .config
            .plugins
            .iter()
            .find(|record| record.id == package.id)
            .map(|record| record.version.as_str());
        let mut body = column![].spacing(8);
        if let (Some(version), Status::UpdateAvailable) = (installed, status) {
            body = body
                .push(
                    text(t!("changelog_range", version = version).into_owned())
                        .size(13)
                        .color(theme.primary()),
                )
                .push(crate::screen::markdown::view(
                    theme,
                    &crate::screen::changelog::range_text(changelog, version),
                    Message::OpenLink,
                ))
                .push(
                    text(t!("changelog_all").into_owned())
                        .size(13)
                        .color(theme.primary()),
                );
        }
        body = body.push(crate::screen::markdown::view(
            theme,
            changelog,
            Message::OpenLink,
        ));
        let changelog_card = m3::card(
            card::Style::filled(theme),
            column![
                row![
                    style::icon(style::icons::HISTORY)
                        .size(18)
                        .color(theme.primary()),
                    style::label(theme, t!("changelog").into_owned()).size(15),
                ]
                .spacing(8)
                .align_y(Vertical::Center),
                scrollable(body).height(Length::Fixed(240.0)),
            ]
            .spacing(8)
            .padding(Padding::from([10.0, 14.0])),
        )
        .width(Length::Fill);
        content = content.push(changelog_card);
    }

    // License modal popup if active
    let modal = state.license_dialog_content.as_ref().map(|lic_text| {
        m3::card(
            card::Style::filled(theme),
            column![
                row![
                    style::icon(style::icons::POLICY)
                        .size(20)
                        .color(theme.primary()),
                    style::label(theme, t!("license_terms").into_owned()).size(16),
                    m3::button(
                        button::Style::tonal(theme, Accent::Primary),
                        style::btn_content(style::icons::CLOSE, t!("close")),
                    )
                    .on_press(Message::ShowLicense(None)),
                ]
                .spacing(12)
                .align_y(Vertical::Center),
                scrollable(text(lic_text).size(13)).height(Length::Fixed(200.0)),
            ]
            .spacing(10)
            .padding(Padding::from([14.0, 18.0])),
        )
        .width(Length::Fill)
    });

    let list = scrollable(content)
        .height(Length::Fill)
        .style(style::scroll(theme));
    match modal {
        Some(modal) => column![modal, list].spacing(8).into(),
        None => list.into(),
    }
}

use std::borrow::Cow;
use std::collections::BTreeMap;

use iced::alignment::Vertical;
use iced::widget::{Space, column, mouse_area, row, scrollable, text};
use iced::{Element, Length};
use iced_m3::theme::{Accent, ColorScheme, Theme};
use iced_m3::widget::{self as m3, Action, button, card};
use launcher_core::{Instance, InstanceId, Kind, TaskInfo};
use rust_i18n::t;

use super::tasks::detail_label;
use crate::strings;
use crate::style;

type Ui = Element<'static, Message>;

const COLUMNS: usize = 3;
const TILE_WIDTH: f32 = 230.0;
const SIDEBAR_WIDTH: f32 = 280.0;
const TILE_PADDING: f32 = 14.0;

#[derive(Debug, Clone, Copy)]
pub enum Message {
    Select(InstanceId),
    ShowNew,
    Refresh,
    Launch,
    LaunchInstance(InstanceId),
    OpenFolder,
    Edit,
    Duplicate,
    ContextOpen(InstanceId),
    ContextClose,
    Delete,
    ConfirmDelete,
    CancelDelete,
}

pub struct Props<'a> {
    pub theme: &'a Theme,
    pub instances: &'a [Instance],
    pub selected: Option<InstanceId>,
    pub pending_delete: Option<InstanceId>,
    pub context: Option<InstanceId>,
    pub notice: Option<&'a str>,
    pub tasks: &'a [TaskInfo],
}

pub fn view(props: &Props<'_>) -> Ui {
    let theme = props.theme;
    let header = row![
        row![
            style::icon(style::icons::INSTANCES)
                .size(26)
                .color(theme.primary()),
            style::label(theme, t!("tab_instances")).size(24),
            style::label(theme, format!("({})", props.instances.len())).size(16),
        ]
        .spacing(8)
        .align_y(Vertical::Center)
        .width(Length::Fill),
        compact(
            style::icons::REFRESH,
            t!("refresh"),
            &button::Style::tonal(theme, Accent::Primary),
            Message::Refresh,
        ),
        compact(
            style::icons::ADD,
            t!("add_instance"),
            &button::Style::filled(theme, Accent::Primary),
            Message::ShowNew,
        ),
    ]
    .spacing(8)
    .align_y(Vertical::Center);

    let selected = props.selected.and_then(|id| {
        props
            .instances
            .iter()
            .find(|instance| instance.config.id == id)
    });
    let confirming = props.pending_delete.is_some() && props.pending_delete == props.selected;
    let body = row![
        scrollable(grid(theme, props.instances, props.selected, props.context))
            .width(Length::Fill)
            .height(Length::Fill)
            .style(style::scroll(theme)),
        sidebar(theme, selected, confirming),
    ]
    .spacing(style::GAP)
    .height(Length::Fill);

    let mut page = column![header].spacing(style::GAP);
    if let Some(notice) = props.notice {
        page = page.push(
            m3::card(
                card::Style::filled(theme),
                row![
                    style::icon(style::icons::INFO)
                        .size(16)
                        .color(theme.on_surface()),
                    style::label(theme, notice.to_owned()).size(12),
                ]
                .spacing(8)
                .align_y(Vertical::Center),
            )
            .width(Length::Fill),
        );
    }
    page.push(body).push(status_bar(theme, props.tasks)).into()
}

fn grid(
    theme: &Theme,
    instances: &[Instance],
    selected: Option<InstanceId>,
    context: Option<InstanceId>,
) -> Ui {
    if instances.is_empty() {
        return m3::card(
            card::Style::filled(theme),
            row![
                style::icon(style::icons::INFO)
                    .size(20)
                    .color(theme.on_surface_variant()),
                style::label(theme, t!("no_instances")),
            ]
            .spacing(8)
            .align_y(Vertical::Center),
        )
        .width(Length::Fill)
        .into();
    }
    let mut named: BTreeMap<&str, Vec<&Instance>> = BTreeMap::new();
    let mut ungrouped: Vec<&Instance> = Vec::new();
    for instance in instances {
        match instance.config.group.as_deref() {
            Some(group) => named.entry(group).or_default().push(instance),
            None => ungrouped.push(instance),
        }
    }
    let mut sections: Vec<Ui> = named
        .into_iter()
        .map(|(name, list)| section(theme, name, &list, selected, context, false))
        .collect();
    if !ungrouped.is_empty() {
        sections.push(section(
            theme,
            &t!("ungrouped"),
            &ungrouped,
            selected,
            context,
            true,
        ));
    }
    column(sections).spacing(style::GAP).into()
}

fn section(
    theme: &Theme,
    title: &str,
    list: &[&Instance],
    selected: Option<InstanceId>,
    context: Option<InstanceId>,
    is_ungrouped: bool,
) -> Ui {
    let icon_glyph = if is_ungrouped {
        style::icons::FOLDER
    } else {
        style::icons::FOLDER_OPEN
    };
    let rows: Vec<Ui> = list
        .chunks(COLUMNS)
        .map(|chunk| {
            let tiles: Vec<Ui> = chunk
                .iter()
                .map(|instance| {
                    let id = instance.config.id;
                    if context == Some(id) {
                        context_menu(theme)
                    } else {
                        tile(theme, instance, selected == Some(id))
                    }
                })
                .collect();
            row(tiles).spacing(style::GAP).into()
        })
        .collect();
    m3::card(
        card::Style::filled(theme),
        column![
            row![
                style::icon(icon_glyph).size(18).color(theme.primary()),
                style::label(theme, title.to_owned()).size(18),
                style::label(theme, format!("({})", list.len())).size(14),
            ]
            .spacing(8)
            .align_y(Vertical::Center),
            column(rows).spacing(style::GAP)
        ]
        .spacing(style::GAP),
    )
    .width(Length::Fill)
    .into()
}

fn tile(theme: &Theme, instance: &Instance, selected: bool) -> Ui {
    let config = &instance.config;
    let color = style::tile_content(theme, selected);

    let top_row = row![
        style::icon_chip::<Message>(
            theme,
            style::kind_icon(config.kind),
            strings::kind_label(config.kind),
            style::kind_tone(config.kind),
        ),
        Space::new().width(Length::Fill),
        if config.plugins.is_empty() {
            row![]
        } else {
            row![
                style::icon(style::icons::EXTENSION).size(14).color(color),
                text(config.plugins.len().to_string()).size(12).color(color),
            ]
            .spacing(3)
            .align_y(Vertical::Center)
        }
    ]
    .align_y(Vertical::Center);

    let info = column![
        text(config.name.clone()).size(17).color(color),
        row![
            style::icon(style::icons::HISTORY).size(13).color(color),
            text(config.version_label()).size(12).color(color),
        ]
        .spacing(4)
        .align_y(Vertical::Center),
    ]
    .spacing(4);

    let launch_btn = m3::button(
        button::Style::tonal(theme, Accent::Primary),
        style::btn_content(style::icons::LAUNCH, t!("launch")),
    )
    .size(button::Size::default().width(Length::Fill))
    .on_press(Message::LaunchInstance(config.id));

    let content = column![top_row, info, launch_btn].spacing(10);
    let tile = m3::card(style::tile_card(theme, selected), content)
        .interaction(card::Interaction::Press(Action::Direct(Message::Select(
            config.id,
        ))))
        .padding(TILE_PADDING)
        .width(Length::Fixed(TILE_WIDTH));
    mouse_area(tile)
        .on_right_press(Message::ContextOpen(config.id))
        .into()
}

/// Replaces the tile of the selected instance. The entries act on the selected instance.
fn context_menu(theme: &Theme) -> Ui {
    let entries: Vec<Ui> = vec![
        action(
            style::icons::LAUNCH,
            t!("launch"),
            &button::Style::filled(theme, Accent::Primary),
            Message::Launch,
        ),
        action(
            style::icons::EDIT,
            t!("edit"),
            &button::Style::tonal(theme, Accent::Primary),
            Message::Edit,
        ),
        action(
            style::icons::FOLDER_OPEN,
            t!("open_folder"),
            &button::Style::tonal(theme, Accent::Primary),
            Message::OpenFolder,
        ),
        action(
            style::icons::DUPLICATE,
            t!("duplicate"),
            &button::Style::tonal(theme, Accent::Primary),
            Message::Duplicate,
        ),
        action(
            style::icons::DELETE,
            t!("delete"),
            &style::danger_button(theme),
            Message::Delete,
        ),
        action(
            style::icons::CLOSE,
            t!("close"),
            &button::Style::tonal(theme, Accent::Primary),
            Message::ContextClose,
        ),
    ];
    m3::card(card::Style::filled(theme), column(entries).spacing(4))
        .padding(TILE_PADDING)
        .width(Length::Fixed(TILE_WIDTH))
        .into()
}

fn sidebar(theme: &Theme, instance: Option<&Instance>, confirming: bool) -> Ui {
    let content: Ui = instance.map_or_else(
        || {
            column![
                style::icon(style::icons::INSTANCES)
                    .size(32)
                    .color(theme.on_surface_variant()),
                style::label(theme, t!("no_selection")).size(14),
            ]
            .spacing(8)
            .align_x(iced::alignment::Horizontal::Center)
            .into()
        },
        |instance| details(theme, instance, confirming),
    );
    m3::card(card::Style::filled(theme), content)
        .width(Length::Fixed(SIDEBAR_WIDTH))
        .height(Length::Fill)
        .into()
}

fn details(theme: &Theme, instance: &Instance, confirming: bool) -> Ui {
    let config = &instance.config;
    let mut lines = column![
        style::label(theme, config.name.clone()).size(20),
        style::icon_chip::<Message>(
            theme,
            style::kind_icon(config.kind),
            strings::kind_label(config.kind),
            style::kind_tone(config.kind),
        ),
    ]
    .spacing(8);

    if config.kind == Kind::Ymm4 {
        lines = lines.push(field_with_icon(
            theme,
            style::icons::LAYERS,
            &t!("edition"),
            &strings::edition_label(config.edition),
        ));
    }
    lines = lines
        .push(field_with_icon(
            theme,
            style::icons::HISTORY,
            &t!("version"),
            &config.version_label(),
        ))
        .push(field_with_icon(
            theme,
            style::icons::GROUP,
            &t!("group"),
            config.group.as_deref().unwrap_or(&t!("ungrouped")),
        ))
        .push(field_with_icon(
            theme,
            style::icons::EXTENSION,
            &t!("plugins"),
            &config.plugins.len().to_string(),
        ));

    let actions: Ui = if confirming {
        column![
            action(
                style::icons::DELETE,
                t!("delete_confirm"),
                &style::danger_button(theme),
                Message::ConfirmDelete,
            ),
            action(
                style::icons::CANCEL,
                t!("cancel"),
                &button::Style::tonal(theme, Accent::Primary),
                Message::CancelDelete,
            ),
        ]
        .spacing(8)
        .into()
    } else {
        column![
            // Primary prominent launch button at top
            action(
                style::icons::LAUNCH,
                t!("launch"),
                &button::Style::filled(theme, Accent::Primary),
                Message::Launch,
            ),
            Space::new().height(Length::Fixed(4.0)),
            // Management actions
            action(
                style::icons::EDIT,
                t!("edit"),
                &button::Style::tonal(theme, Accent::Primary),
                Message::Edit,
            ),
            action(
                style::icons::FOLDER_OPEN,
                t!("open_folder"),
                &button::Style::tonal(theme, Accent::Primary),
                Message::OpenFolder,
            ),
            action(
                style::icons::DUPLICATE,
                t!("duplicate"),
                &button::Style::tonal(theme, Accent::Primary),
                Message::Duplicate,
            ),
            Space::new().height(Length::Fixed(8.0)),
            // Dangerous action separated at bottom
            action(
                style::icons::DELETE,
                t!("delete"),
                &style::danger_button(theme),
                Message::Delete,
            ),
        ]
        .spacing(8)
        .into()
    };

    column![lines, Space::new().height(Length::Fill), actions]
        .spacing(style::PADDING)
        .height(Length::Fill)
        .into()
}

fn field_with_icon(theme: &Theme, glyph: &'static str, label: &str, value: &str) -> Ui {
    row![
        style::icon(glyph).size(16).color(theme.primary()),
        style::label(theme, format!("{label}: {value}")).size(14),
    ]
    .spacing(6)
    .align_y(Vertical::Center)
    .into()
}

fn action(
    glyph: &'static str,
    label: Cow<'static, str>,
    style: &button::Style,
    message: Message,
) -> Ui {
    m3::button(*style, style::btn_content(glyph, label))
        .size(button::Size::default().width(Length::Fill))
        .on_press(message)
        .into()
}

fn compact(
    glyph: &'static str,
    label: Cow<'static, str>,
    style: &button::Style,
    message: Message,
) -> Ui {
    m3::button(*style, style::btn_content(glyph, label))
        .on_press(message)
        .into()
}

fn status_bar(theme: &Theme, tasks: &[TaskInfo]) -> Ui {
    let active: Vec<&TaskInfo> = tasks.iter().filter(|task| task.state.is_active()).collect();
    active.last().map_or_else(
        || idle_status(theme, tasks),
        |latest| active_status(theme, active.len(), latest),
    )
}

fn active_status(theme: &Theme, count: usize, latest: &TaskInfo) -> Ui {
    row![
        style::icon(style::icons::SYNC)
            .size(15)
            .color(theme.primary()),
        style::label(
            theme,
            format!(
                "{}: {} | {}: {}",
                t!("active_tasks"),
                count,
                latest.title,
                detail_label(&latest.state)
            )
        )
        .size(12),
    ]
    .spacing(6)
    .align_y(Vertical::Center)
    .into()
}

fn idle_status(theme: &Theme, tasks: &[TaskInfo]) -> Ui {
    tasks.last().map_or_else(
        || {
            row![
                style::icon(style::icons::CHECK_CIRCLE)
                    .size(15)
                    .color(theme.tertiary()),
                style::label(theme, t!("no_tasks")).size(12),
            ]
            .spacing(6)
            .align_y(Vertical::Center)
            .into()
        },
        |last| {
            row![
                style::icon(style::icons::TASKS)
                    .size(15)
                    .color(theme.on_surface_variant()),
                style::label(
                    theme,
                    format!("{}: {}", last.title, detail_label(&last.state))
                )
                .size(12),
            ]
            .spacing(6)
            .align_y(Vertical::Center)
            .into()
        },
    )
}

//! Lightweight Markdown renderer for Iced with GitHub alert, table, and task list support.

use std::fmt::Write as _;

use iced::widget::span;
use iced::widget::text::Span;
use iced::widget::{column, container, rich_text, row, text};
use iced::{Element, Font, Length, Padding};
use iced_m3::theme::{ColorScheme, Theme};
use iced_m3::widget::{self as m3, card};
use pulldown_cmark::{BlockQuoteKind, Event, HeadingLevel, Options, Parser, Tag, TagEnd};
use rust_i18n::t;

use crate::style::{self, Tone};

#[derive(Clone, Default)]
#[expect(
    clippy::struct_excessive_bools,
    reason = "each flag is an independent inline format"
)]
struct Style {
    strong: bool,
    emphasis: bool,
    strike: bool,
    code: bool,
    link: Option<String>,
}

/// Inline content of a block: text runs with their emphasis and link.
#[derive(Default)]
struct Inline {
    runs: Vec<(String, Style)>,
}

impl Inline {
    fn push(&mut self, content: &str, style: &Style) {
        self.runs.push((content.to_owned(), style.clone()));
    }

    fn push_plain(&mut self, content: &str) {
        self.push(content, &Style::default());
    }

    fn is_blank(&self) -> bool {
        self.runs
            .iter()
            .all(|(content, _)| content.trim().is_empty())
    }

    fn plain(&self) -> String {
        self.runs
            .iter()
            .map(|(content, _)| content.as_str())
            .collect()
    }

    fn clear(&mut self) {
        self.runs.clear();
    }

    /// Takes the runs without the blank edges.
    fn take(&mut self) -> Vec<(String, Style)> {
        let mut runs = std::mem::take(&mut self.runs);
        if let Some(first) = runs.first_mut() {
            first.0 = first.0.trim_start().to_owned();
        }
        if let Some(last) = runs.last_mut() {
            last.0 = last.0.trim_end().to_owned();
        }
        runs
    }
}

fn rich<'a, M: Clone + 'static>(
    theme: &Theme,
    runs: Vec<(String, Style)>,
    size: u32,
    on_link: fn(String) -> M,
) -> Element<'a, M> {
    let spans: Vec<Span<'a, String, Font>> = runs
        .into_iter()
        .map(|(content, style)| {
            let mut run = span(content).size(size).color(theme.on_surface());
            if style.strong || style.emphasis {
                run = run.font(Font {
                    weight: if style.strong {
                        iced::font::Weight::Bold
                    } else {
                        iced::font::Weight::Normal
                    },
                    style: if style.emphasis {
                        iced::font::Style::Italic
                    } else {
                        iced::font::Style::Normal
                    },
                    ..Font::DEFAULT
                });
            }
            if style.code {
                run = run.font(Font::MONOSPACE);
            }
            if style.strike {
                run = run.strikethrough(true);
            }
            if let Some(url) = style.link {
                run = run.link(url).underline(true).color(theme.primary());
            }
            run
        })
        .collect();
    rich_text(spans).on_link_click(on_link).into()
}

/// Renders a markdown string into an Iced Element.
/// Images show their alt text, because the renderer loads no pictures.
/// `on_link` makes the message for a click on a link.
pub fn view<'a, M: Clone + 'static>(
    theme: &Theme,
    markdown: &str,
    on_link: fn(String) -> M,
) -> Element<'a, M> {
    let options = Options::ENABLE_TABLES
        | Options::ENABLE_STRIKETHROUGH
        | Options::ENABLE_TASKLISTS
        | Options::ENABLE_GFM;
    let parser = Parser::new_ext(markdown, options);
    let mut elements: Vec<Element<'a, M>> = Vec::new();

    let mut current_text = Inline::default();
    let mut style = Style::default();
    let mut in_code_block = false;
    let mut code_content = String::new();
    let mut in_blockquote = false;
    let mut quote_kind: Option<BlockQuoteKind> = None;
    let mut quote_content = String::new();
    let mut current_heading_level: Option<HeadingLevel> = None;
    let mut lists: Vec<Option<u64>> = Vec::new();
    let mut table_rows: Vec<Vec<String>> = Vec::new();
    let mut table_row: Vec<String> = Vec::new();
    let mut in_table = false;
    let mut link_target: Option<String> = None;

    for event in parser {
        match event {
            Event::Start(Tag::Heading { level, .. }) => {
                flush_text(&mut current_text, &mut elements, theme, on_link);
                current_heading_level = Some(level);
            }
            Event::End(TagEnd::Heading(_)) => {
                let size = match current_heading_level.take() {
                    Some(HeadingLevel::H1) => 22,
                    Some(HeadingLevel::H2) => 18,
                    Some(HeadingLevel::H3) => 16,
                    _ => 14,
                };
                let content = current_text.plain();
                current_text.clear();
                if !content.trim().is_empty() {
                    elements.push(
                        text(content.trim().to_owned())
                            .size(size)
                            .color(theme.primary())
                            .into(),
                    );
                }
            }
            Event::End(TagEnd::Paragraph) => {
                if in_blockquote {
                    quote_content.push('\n');
                } else if lists.is_empty() && !in_table {
                    flush_text(&mut current_text, &mut elements, theme, on_link);
                } else {
                    current_text.push_plain("\n");
                }
            }
            Event::Start(Tag::CodeBlock(_)) => {
                flush_text(&mut current_text, &mut elements, theme, on_link);
                in_code_block = true;
                code_content.clear();
            }
            Event::End(TagEnd::CodeBlock) => {
                in_code_block = false;
                let code = std::mem::take(&mut code_content);
                let code_widget = m3::card(
                    style::tile_card(theme, false),
                    text(code)
                        .size(13)
                        .font(iced::Font::MONOSPACE)
                        .color(theme.on_surface()),
                )
                .padding(Padding::from([8.0, 12.0]))
                .width(Length::Fill);
                elements.push(code_widget.into());
            }
            Event::Start(Tag::BlockQuote(kind)) => {
                flush_text(&mut current_text, &mut elements, theme, on_link);
                in_blockquote = true;
                quote_kind = kind;
                quote_content.clear();
            }
            Event::End(TagEnd::BlockQuote(_)) => {
                in_blockquote = false;
                let quote = std::mem::take(&mut quote_content);
                elements.push(render_quote_or_alert(theme, quote_kind.take(), &quote));
            }
            Event::Start(Tag::List(start)) => {
                flush_text(&mut current_text, &mut elements, theme, on_link);
                lists.push(start);
            }
            Event::End(TagEnd::List(_)) => {
                flush_text(&mut current_text, &mut elements, theme, on_link);
                lists.pop();
            }
            Event::Start(Tag::Item) => {
                flush_text(&mut current_text, &mut elements, theme, on_link);
            }
            Event::End(TagEnd::Item) => {
                let blank = current_text.is_blank();
                let item = current_text.take();
                if !blank {
                    let indent = f32::from(
                        u16::try_from(lists.len().saturating_sub(1) * 16).unwrap_or(u16::MAX),
                    );
                    let marker = match lists.last_mut() {
                        Some(Some(number)) => {
                            let marker = format!("{number}.");
                            *number += 1;
                            marker
                        }
                        _ => "•".to_owned(),
                    };
                    let line = row![
                        container(text(marker).size(14).color(theme.primary()))
                            .padding(Padding::default().left(indent)),
                        rich(theme, item, 14, on_link),
                    ]
                    .spacing(8);
                    elements.push(line.into());
                }
            }
            Event::TaskListMarker(checked) => {
                current_text.push_plain(if checked { "☑ " } else { "☐ " });
            }
            Event::Start(Tag::Table(_)) => {
                flush_text(&mut current_text, &mut elements, theme, on_link);
                in_table = true;
                table_rows.clear();
                table_row.clear();
            }
            Event::End(TagEnd::TableHead | TagEnd::TableRow) => {
                table_rows.push(std::mem::take(&mut table_row));
            }
            Event::Start(Tag::TableRow) => table_row.clear(),
            Event::Start(Tag::TableCell) => current_text.clear(),
            Event::End(TagEnd::TableCell) => {
                table_row.push(current_text.plain().trim().to_owned());
                current_text.clear();
            }
            Event::End(TagEnd::Table) => {
                in_table = false;
                elements.push(render_table(theme, std::mem::take(&mut table_rows)));
            }
            Event::Text(t) => {
                if in_code_block {
                    code_content.push_str(&t);
                } else if in_blockquote {
                    quote_content.push_str(&t);
                } else {
                    current_text.push(&t, &style);
                }
            }
            Event::Start(Tag::Strong) => style.strong = true,
            Event::End(TagEnd::Strong) => style.strong = false,
            Event::Start(Tag::Emphasis) => style.emphasis = true,
            Event::End(TagEnd::Emphasis) => style.emphasis = false,
            Event::Start(Tag::Strikethrough) => style.strike = true,
            Event::End(TagEnd::Strikethrough) => style.strike = false,
            Event::Start(Tag::Link { dest_url, .. }) => {
                if in_blockquote {
                    link_target = Some(dest_url.to_string());
                } else {
                    style.link = Some(dest_url.to_string());
                }
            }
            Event::End(TagEnd::Link) => {
                style.link = None;
                if let Some(url) = link_target.take() {
                    let _ = write!(quote_content, " ({url})");
                }
            }
            Event::Code(c) => {
                if in_code_block {
                    code_content.push_str(&c);
                } else if in_blockquote {
                    let _ = write!(quote_content, "`{c}`");
                } else {
                    current_text.push(
                        &c,
                        &Style {
                            code: true,
                            ..style.clone()
                        },
                    );
                }
            }
            Event::SoftBreak | Event::HardBreak => {
                if in_code_block {
                    code_content.push('\n');
                } else if in_blockquote {
                    quote_content.push('\n');
                } else {
                    current_text.push_plain("\n");
                }
            }
            _ => {}
        }
    }

    flush_text(&mut current_text, &mut elements, theme, on_link);

    if elements.is_empty() {
        text(t!("no_description").into_owned())
            .size(13)
            .color(theme.outline())
            .into()
    } else {
        column(elements).spacing(8).into()
    }
}

/// The first row is the header row.
fn render_table<'a, M: Clone + 'static>(theme: &Theme, rows: Vec<Vec<String>>) -> Element<'a, M> {
    let columns = rows.iter().map(Vec::len).max().unwrap_or(0);
    let lines: Vec<Element<'a, M>> = rows
        .into_iter()
        .enumerate()
        .map(|(index, cells)| {
            let header = index == 0;
            let color = if header {
                theme.primary()
            } else {
                theme.on_surface()
            };
            let cells: Vec<Element<'a, M>> = (0..columns)
                .map(|column_index| {
                    let content = cells.get(column_index).cloned().unwrap_or_default();
                    container(text(content).size(13).color(color))
                        .width(Length::FillPortion(1))
                        .padding(Padding::from([4.0, 8.0]))
                        .into()
                })
                .collect();
            m3::card(style::tile_card(theme, header), row(cells))
                .padding(Padding::ZERO)
                .width(Length::Fill)
                .into()
        })
        .collect();
    column(lines).spacing(2).into()
}

fn flush_text<M: Clone + 'static>(
    current_text: &mut Inline,
    elements: &mut Vec<Element<'_, M>>,
    theme: &Theme,
    on_link: fn(String) -> M,
) {
    let blank = current_text.is_blank();
    let runs = current_text.take();
    if !blank {
        elements.push(rich(theme, runs, 14, on_link));
    }
}

/// Localized name of the alert that `label` marks.
fn alert_name(label: &str) -> String {
    match label {
        "NOTE" => t!("alert_note"),
        "TIP" => t!("alert_tip"),
        "IMPORTANT" => t!("alert_important"),
        "WARNING" => t!("alert_warning"),
        "CAUTION" => t!("alert_caution"),
        other => return other.to_owned(),
    }
    .into_owned()
}

type Alert = (&'static str, &'static str, Tone);

/// The alert that a blockquote is, and its text without the `[!NAME]` marker.
/// `kind` comes from the parser. The marker in `quote` serves a parser that reports none.
fn alert_of(kind: Option<BlockQuoteKind>, quote: &str) -> (Option<Alert>, &str) {
    let note: Alert = ("NOTE", style::icons::INFO, Tone::Primary);
    let tip: Alert = ("TIP", style::icons::CHECK_CIRCLE, Tone::Tertiary);
    let important: Alert = ("IMPORTANT", style::icons::INFO, Tone::Primary);
    let warning: Alert = ("WARNING", style::icons::WARNING, Tone::Error);
    let caution: Alert = ("CAUTION", style::icons::ERROR, Tone::Error);
    let trimmed = quote.trim();
    match kind {
        Some(BlockQuoteKind::Note) => return (Some(note), trimmed),
        Some(BlockQuoteKind::Tip) => return (Some(tip), trimmed),
        Some(BlockQuoteKind::Important) => return (Some(important), trimmed),
        Some(BlockQuoteKind::Warning) => return (Some(warning), trimmed),
        Some(BlockQuoteKind::Caution) => return (Some(caution), trimmed),
        None => {}
    }
    for (marker, alert) in [
        ("[!NOTE]", note),
        ("[!TIP]", tip),
        ("[!IMPORTANT]", important),
        ("[!WARNING]", warning),
        ("[!CAUTION]", caution),
    ] {
        if let Some(rest) = trimmed.strip_prefix(marker) {
            return (Some(alert), rest);
        }
    }
    (None, trimmed)
}

/// Renders GitHub alerts (`[!NOTE]`, `[!TIP]`, `[!WARNING]`, `[!IMPORTANT]`, `[!CAUTION]`)
/// or standard blockquotes.
fn render_quote_or_alert<'a, M: Clone + 'static>(
    theme: &Theme,
    kind: Option<BlockQuoteKind>,
    quote: &str,
) -> Element<'a, M> {
    let (alert_type, content) = alert_of(kind, quote);
    let trimmed = content.trim();
    if let Some((label, glyph, tone)) = alert_type {
        let (border_color, bg_color) = match tone {
            Tone::Primary => (theme.primary(), theme.primary_container()),
            Tone::Tertiary => (theme.tertiary(), theme.tertiary_container()),
            Tone::Secondary => (theme.secondary(), theme.secondary_container()),
            Tone::Error => (theme.error(), theme.error_container()),
        };
        m3::card(
            card::Style {
                container_color: bg_color,
                ..card::Style::filled(theme)
            },
            column![
                row![
                    style::icon(glyph).size(16).color(border_color),
                    text(alert_name(label)).size(13).color(border_color),
                ]
                .spacing(6),
                text(content.trim().to_owned())
                    .size(13)
                    .color(theme.on_surface()),
            ]
            .spacing(6),
        )
        .padding(Padding::from([8.0, 12.0]))
        .width(Length::Fill)
        .into()
    } else {
        m3::card(
            style::tile_card(theme, false),
            row![
                container(column![])
                    .width(Length::Fixed(4.0))
                    .height(Length::Fill),
                text(trimmed.to_owned())
                    .size(13)
                    .color(theme.on_surface_variant()),
            ]
            .spacing(8),
        )
        .padding(Padding::from([6.0, 10.0]))
        .width(Length::Fill)
        .into()
    }
}

#[cfg(test)]
mod tests {
    use pulldown_cmark::BlockQuoteKind;

    use super::alert_of;

    #[test]
    fn alert_comes_from_the_parser_kind() {
        let (alert, text) = alert_of(Some(BlockQuoteKind::Warning), " body \n");
        assert_eq!(alert.map(|alert| alert.0), Some("WARNING"));
        assert_eq!(text, "body");
    }

    #[test]
    fn alert_comes_from_the_marker_when_the_parser_reports_none() {
        for (marker, label) in [
            ("[!NOTE]", "NOTE"),
            ("[!TIP]", "TIP"),
            ("[!IMPORTANT]", "IMPORTANT"),
            ("[!WARNING]", "WARNING"),
            ("[!CAUTION]", "CAUTION"),
        ] {
            let quote = format!("{marker}\nbody");
            let (alert, text) = alert_of(None, &quote);
            assert_eq!(alert.map(|alert| alert.0), Some(label));
            assert_eq!(text.trim(), "body");
        }
    }

    #[test]
    fn plain_blockquote_is_no_alert() {
        let (alert, text) = alert_of(None, "just a quote");
        assert!(alert.is_none());
        assert_eq!(text, "just a quote");
    }
}

