pub const KINDS: [Kind; 6] = [
    Kind::Ymm4,
    Kind::Aviutl,
    Kind::Aviutl2,
    Kind::Neoutl,
    Kind::Freya,
    Kind::Macutl,
];

#[derive(Debug, Clone)]
pub enum Message {
    KindSelected(Kind),
    NameChanged(String),
    GroupChanged(String),
    EditionSelected(Edition),
    /// `true` selects the `AppImage`.
    AppImageToggled(bool),
    VersionSelected(VersionChoice),
    AddonSelected(VersionChoice),
    ToggleRecommended(bool),
    PickSource,
    /// `None` when the user cancelled the folder dialog.
    SourcePicked(Option<PathBuf>),
    ClearSource,
    Reload,
    Submit,
    Cancel,
}

/// What the submit button starts.
#[derive(Debug, Clone)]
pub enum Submission {
    Create(CreateRequest),
    Import(ImportRequest),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Availability {
    Available,
    UnsupportedHost,
    NoProvider,
}

pub const fn availability(kind: Kind, host: Host) -> Availability {
    if !kind.supported_on(host) {
        Availability::UnsupportedHost
    } else if !has_provider(kind) {
        Availability::NoProvider
    } else {
        Availability::Available
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct VersionChoice {
    pub tag: String,
    label: String,
}

impl From<&AppVersion> for VersionChoice {
    fn from(version: &AppVersion) -> Self {
        let label = if version.prerelease {
            format!("{} ({})", version.version, t!("prerelease"))
        } else {
            version.version.clone()
        };
        Self {
            tag: version.version.clone(),
            label,
        }
    }
}

impl fmt::Display for VersionChoice {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.label)
    }
}

pub enum Load {
    /// No request has been made for the selected kind.
    Idle,
    Loading,
    Ready,
    Failed(String),
}

pub struct Form {
    host: Host,
    pub kind: Kind,
    pub name: String,
    pub group: String,
    pub edition: Edition,
    /// Choice of the checkbox. `bundle()` tells what applies to the selected kind.
    pub app_image: bool,
    pub selected: Option<VersionChoice>,
    pub choices: Vec<VersionChoice>,
    pub addon_selected: Option<VersionChoice>,
    pub addon_choices: Vec<VersionChoice>,
    pub install_recommended: bool,
    /// Folder of an existing install. `Some` turns the submit into an import.
    pub source: Option<PathBuf>,
    pub load: Load,
    versions: Vec<AppVersion>,
    addon_versions: Vec<AppVersion>,
}

impl Form {
    pub fn new(host: Host) -> Self {
        let kind = KINDS
            .into_iter()
            .find(|kind| availability(*kind, host) == Availability::Available)
            .unwrap_or(Kind::Neoutl);
        Self {
            host,
            kind,
            name: String::new(),
            group: String::new(),
            edition: Edition::Normal,
            app_image: true,
            selected: None,
            choices: Vec::new(),
            addon_selected: None,
            addon_choices: Vec::new(),
            install_recommended: true,
            source: None,
            load: Load::Idle,
            versions: Vec::new(),
            addon_versions: Vec::new(),
        }
    }

    /// `true` when the selected kind ships in several formats on this host.
    pub fn offers_bundle(&self) -> bool {
        self.kind == Kind::Freya && self.host == Host::Linux
    }

    /// Format that the installation uses.
    pub fn bundle(&self) -> Bundle {
        if self.offers_bundle() && self.app_image {
            Bundle::AppImage
        } else {
            Bundle::Archive
        }
    }

    pub const fn needs_load(&self) -> bool {
        matches!(self.load, Load::Idle)
    }

    /// `true` when the selected kind can take over an existing install.
    pub fn offers_import(&self) -> bool {
        self.kind == Kind::Aviutl2
    }

    /// Selects the install folder. A blank name becomes the folder name.
    pub fn set_source(&mut self, source: PathBuf) {
        if self.name.trim().is_empty()
            && let Some(name) = source.file_name()
        {
            self.name = name.to_string_lossy().into_owned();
        }
        self.source = Some(source);
    }

    pub fn select_kind(&mut self, kind: Kind) {
        self.kind = kind;
        self.source = None;
        self.edition = Edition::Normal;
        self.begin_load();
    }

    pub fn begin_load(&mut self) {
        self.load = Load::Loading;
        self.versions.clear();
        self.addon_versions.clear();
        self.choices.clear();
        self.addon_choices.clear();
        self.selected = None;
        self.addon_selected = None;
    }

    pub fn finish_load(&mut self, result: Result<Versions, String>) {
        match result {
            Ok(versions) => {
                self.versions = versions.app;
                self.addon_versions = versions.addon;
                self.load = Load::Ready;
            }
            Err(reason) => {
                self.versions.clear();
                self.addon_versions.clear();
                self.load = Load::Failed(reason);
            }
        }
    }

    pub fn versions(&self) -> &[AppVersion] {
        &self.versions
    }

    pub fn addon_versions(&self) -> &[AppVersion] {
        &self.addon_versions
    }

    pub const fn has_addon(&self) -> bool {
        !self.addon_versions.is_empty()
    }

    /// Replaces the choices with the installable versions and selects the first entry of each.
    pub fn set_choices(&mut self, installable: &[AppVersion], addons: &[AppVersion]) {
        self.choices = installable.iter().map(VersionChoice::from).collect();
        self.selected = self.choices.first().cloned();
        self.addon_choices = addons.iter().map(VersionChoice::from).collect();
        self.addon_selected = self.addon_choices.first().cloned();
    }

    pub fn can_submit(&self) -> bool {
        !self.name.trim().is_empty()
            && (self.source.is_some()
                || (self.selected.is_some()
                    && (!self.has_addon() || self.addon_selected.is_some())))
    }

    pub fn submission(&self) -> Option<Submission> {
        self.source.as_ref().map_or_else(
            || self.request().map(Submission::Create),
            |source| self.import_request(source).map(Submission::Import),
        )
    }

    fn import_request(&self, source: &Path) -> Option<ImportRequest> {
        let name = self.name.trim();
        if name.is_empty() {
            return None;
        }
        let group = self.group.trim();
        Some(ImportRequest {
            name: name.to_owned(),
            kind: self.kind,
            edition: self.edition,
            group: (!group.is_empty()).then(|| group.to_owned()),
            source: source.to_owned(),
            versions: self.versions.clone(),
        })
    }

    pub fn request(&self) -> Option<CreateRequest> {
        if !self.can_submit() {
            return None;
        }
        let tag = &self.selected.as_ref()?.tag;
        let version = self
            .versions
            .iter()
            .find(|version| &version.version == tag)?
            .clone();
        let addon = match &self.addon_selected {
            Some(choice) => Some(
                self.addon_versions
                    .iter()
                    .find(|version| version.version == choice.tag)?
                    .clone(),
            ),
            None => None,
        };
        let group = self.group.trim();
        Some(CreateRequest {
            name: self.name.trim().to_owned(),
            kind: self.kind,
            edition: self.edition,
            bundle: self.bundle(),
            group: (!group.is_empty()).then(|| group.to_owned()),
            version,
            addon,
        })
    }
}

pub fn view<'a>(form: &'a Form, theme: &'a Theme, host: Host) -> Element<'a, Message> {
    let kinds: Vec<Element<'a, Message>> = KINDS
        .iter()
        .map(|kind| kind_entry(theme, *kind, form.kind, host))
        .collect();
    let kind_card = m3::card(
        card::Style::filled(theme),
        column![
            row![
                style::icon(style::icons::CATEGORY)
                    .size(20)
                    .color(theme.primary()),
                style::label(theme, t!("kind")).size(18),
            ]
            .spacing(8)
            .align_y(Vertical::Center),
            column(kinds).spacing(style::GAP)
        ]
        .spacing(style::GAP),
    )
    .width(Length::Fixed(KIND_LIST_WIDTH));

    let form_style = card::Style::filled(theme);
    let name_input = TextInput::new("", &form.name, theme)
        .with_label_text(strings::label("name"), form_style.container_color)
        .on_input(Message::NameChanged)
        .padding(INPUT_PADDING);
    let group_input = TextInput::new(&t!("group_hint"), &form.group, theme)
        .with_label_text(strings::label("group"), form_style.container_color)
        .on_input(Message::GroupChanged)
        .padding(INPUT_PADDING);

    let form_header = row![
        style::icon(style::kind_icon(form.kind))
            .size(26)
            .color(theme.primary()),
        style::label(theme, strings::kind_label(form.kind)).size(22),
        style::icon_chip::<Message>(
            theme,
            style::kind_icon(form.kind),
            strings::kind_label(form.kind),
            style::kind_tone(form.kind),
        ),
    ]
    .spacing(8)
    .align_y(Vertical::Center);

    let mut fields = column![
        form_header,
        labeled_with_icon(theme, style::icons::EDIT, t!("name"), name_input),
        labeled_with_icon(theme, style::icons::GROUP, t!("group"), group_input),
    ]
    .spacing(style::GAP);
    if form.kind == Kind::Ymm4 {
        fields = fields.push(edition_picker(theme, form.edition));
    }
    if form.offers_import() {
        fields = fields.push(labeled_with_icon(
            theme,
            style::icons::FOLDER_OPEN,
            t!("import_source"),
            source_picker(form, theme),
        ));
    }
    if form.source.is_none() {
        fields = fields.push(labeled_with_icon(
            theme,
            style::icons::HISTORY,
            t!("version"),
            version_picker(
                form,
                theme,
                &form.choices,
                form.selected.as_ref(),
                Message::VersionSelected,
            ),
        ));
        if form.has_addon() {
            fields = fields.push(labeled_with_icon(
                theme,
                style::icons::EXTENSION,
                t!("addon_version"),
                version_picker(
                    form,
                    theme,
                    &form.addon_choices,
                    form.addon_selected.as_ref(),
                    Message::AddonSelected,
                ),
            ));
        }
        if form.offers_bundle() {
            fields = fields.push(
                checkbox(form.app_image)
                    .label(t!("bundle_appimage"))
                    .on_toggle(Message::AppImageToggled),
            );
        }
        if form.kind == Kind::Aviutl2 {
            fields = fields.push(
                checkbox(form.install_recommended)
                    .label(t!("recommended_plugins"))
                    .on_toggle(Message::ToggleRecommended),
            );
        }
    }

    let submit_content = if form.source.is_some() {
        style::btn_content(style::icons::IMPORT, t!("import_submit"))
    } else {
        style::btn_content(style::icons::ADD, t!("create"))
    };
    let submit = m3::button(
        button::Style::filled(theme, Accent::Primary),
        submit_content,
    )
    .on_press_maybe(form.can_submit().then_some(Message::Submit));
    let cancel = m3::button(
        button::Style::tonal(theme, Accent::Primary),
        style::btn_content(style::icons::CLOSE, t!("cancel")),
    )
    .on_press(Message::Cancel);
    let actions = row![submit, cancel].spacing(8);

    let form_card =
        m3::card(form_style, column![fields, actions].spacing(style::PADDING)).width(Length::Fill);

    column![
        row![
            style::icon(style::icons::ADD)
                .size(26)
                .color(theme.primary()),
            style::label(theme, t!("tab_new").into_owned()).size(24),
        ]
        .spacing(8)
        .align_y(Vertical::Center),
        row![kind_card, form_card].spacing(style::GAP),
    ]
    .spacing(style::GAP)
    .into()
}

fn kind_entry<'a>(theme: &Theme, kind: Kind, current: Kind, host: Host) -> Element<'a, Message> {
    let label = strings::kind_label(kind);
    let (interaction, badge) = match availability(kind, host) {
        Availability::Available => (
            card::Interaction::Press(Action::Direct(Message::KindSelected(kind))),
            None,
        ),
        Availability::UnsupportedHost => (
            card::Interaction::Disabled,
            Some((strings::unsupported_host_badge(host), Tone::Error)),
        ),
        Availability::NoProvider => (
            card::Interaction::Disabled,
            Some((t!("planned").into_owned(), Tone::Tertiary)),
        ),
    };
    let selected = badge.is_none() && kind == current;
    let color = style::tile_content(theme, selected);
    let icon_color = if selected {
        theme.on_primary_container()
    } else {
        theme.primary()
    };
    let mut content = row![
        style::icon(style::kind_icon(kind))
            .size(20)
            .color(icon_color),
        iced::widget::text(label).color(color).width(Length::Fill)
    ]
    .spacing(8)
    .align_y(Vertical::Center);
    if let Some((text, tone)) = badge {
        content = content.push(style::chip::<Message>(theme, text, tone));
    }
    m3::card(style::tile_card(theme, selected), content)
        .interaction(interaction)
        .padding(Padding::from(ENTRY_PADDING))
        .width(Length::Fill)
        .into()
}

fn labeled_with_icon<'a>(
    theme: &Theme,
    glyph: &'static str,
    label: Cow<'a, str>,
    input: impl Into<Element<'a, Message>>,
) -> Element<'a, Message> {
    column![
        row![
            style::icon(glyph).size(15).color(theme.primary()),
            style::label(theme, label).size(14),
        ]
        .spacing(6)
        .align_y(Vertical::Center),
        input.into()
    ]
    .spacing(4)
    .into()
}

fn source_picker<'a>(form: &'a Form, theme: &Theme) -> Element<'a, Message> {
    let pick = m3::button(
        button::Style::tonal(theme, Accent::Primary),
        style::btn_content(style::icons::FOLDER_OPEN, t!("import_pick")),
    )
    .on_press(Message::PickSource);
    let mut picker = row![pick].spacing(8).align_y(Vertical::Center);
    if let Some(source) = &form.source {
        picker = picker
            .push(style::label(theme, source.display().to_string()).size(12))
            .push(
                m3::button(
                    button::Style::tonal(theme, Accent::Primary),
                    style::btn_content(style::icons::CLOSE, t!("import_clear")),
                )
                .on_press(Message::ClearSource),
            );
    }
    picker.into()
}

fn edition_picker<'a>(theme: &Theme, current: Edition) -> Element<'a, Message> {
    let entry = |edition: Edition| connected::Button {
        content: style::btn_content(style::icons::LAYERS, strings::edition_label(edition)),
        on_press: Some(Message::EditionSelected(edition)),
        selected: current == edition,
    };
    let group = m3::connected_button_group(
        button::Style::tonal(theme, Accent::Primary),
        vec![entry(Edition::Normal), entry(Edition::Lite)],
    );
    labeled_with_icon(theme, style::icons::LAYERS, t!("edition"), group)
}

fn version_picker<'a>(
    form: &'a Form,
    theme: &Theme,
    choices: &'a [VersionChoice],
    current: Option<&VersionChoice>,
    select: impl Fn(VersionChoice) -> Message + 'a,
) -> Element<'a, Message> {
    match &form.load {
        Load::Idle | Load::Loading => row![
            style::icon(style::icons::SYNC)
                .size(16)
                .color(theme.primary()),
            style::label(theme, t!("loading")).size(14),
        ]
        .spacing(8)
        .align_y(Vertical::Center)
        .into(),
        Load::Failed(reason) => column![
            row![
                style::icon(style::icons::ERROR)
                    .size(16)
                    .color(theme.error()),
                style::label(theme, format!("{}: {reason}", t!("load_failed"))).size(12),
            ]
            .spacing(6)
            .align_y(Vertical::Center),
            m3::button(
                button::Style::tonal(theme, Accent::Primary),
                style::btn_content(style::icons::REFRESH, t!("reload")),
            )
            .on_press(Message::Reload),
        ]
        .spacing(6)
        .into(),
        Load::Ready if choices.is_empty() => row![
            style::icon(style::icons::INFO)
                .size(16)
                .color(theme.on_surface_variant()),
            style::label(theme, t!("no_version")).size(14),
        ]
        .spacing(8)
        .align_y(Vertical::Center)
        .into(),
        Load::Ready => {
            let entries = choices.iter().map(|choice| {
                let selected = current == Some(choice);
                let glyph = if selected {
                    style::icons::CHECK_CIRCLE
                } else {
                    style::icons::HISTORY
                };
                let content_color = style::tile_content(theme, selected);
                m3::card(
                    style::tile_card(theme, selected),
                    row![
                        style::icon(glyph).size(16).color(content_color),
                        style::label(theme, choice.to_string()).color(content_color),
                    ]
                    .spacing(8)
                    .align_y(Vertical::Center),
                )
                .interaction(card::Interaction::Press(Action::Direct(select(
                    choice.clone(),
                ))))
                .padding(Padding::from(ENTRY_PADDING))
                .width(Length::Fill)
                .into()
            });
            scrollable(column(entries).spacing(4))
                .height(Length::Fixed(VERSION_LIST_HEIGHT))
                .style(style::scroll(theme))
                .into()
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn aviutl2_form() -> Form {
        let mut form = Form::new(Host::Windows);
        form.select_kind(Kind::Aviutl2);
        form
    }

    #[test]
    fn macos_form_starts_with_a_kind_that_macos_offers() {
        assert_eq!(Form::new(Host::MacOs).kind, Kind::Freya);
    }

    #[test]
    fn availability_follows_the_host() {
        assert_eq!(
            availability(Kind::Macutl, Host::MacOs),
            Availability::Available
        );
        assert_eq!(
            availability(Kind::Macutl, Host::Windows),
            Availability::UnsupportedHost
        );
        assert_eq!(
            availability(Kind::Neoutl, Host::MacOs),
            Availability::UnsupportedHost
        );
    }

    #[test]
    fn source_turns_the_submission_into_an_import_named_after_the_folder() {
        let mut form = aviutl2_form();
        form.set_source(PathBuf::from("tools/MyAviUtl2"));
        assert!(form.can_submit());
        assert!(matches!(
            form.submission(),
            Some(Submission::Import(request)) if request.name == "MyAviUtl2"
        ));
    }

    #[test]
    fn typed_name_survives_the_folder_selection() {
        let mut form = aviutl2_form();
        form.name = "main".to_owned();
        form.set_source(PathBuf::from("tools/MyAviUtl2"));
        assert!(matches!(
            form.submission(),
            Some(Submission::Import(request)) if request.name == "main"
        ));
    }

    #[test]
    fn blank_name_blocks_the_import() {
        let mut form = aviutl2_form();
        form.set_source(PathBuf::from("/"));
        assert_eq!(form.name, "");
        assert!(!form.can_submit());
        assert!(form.submission().is_none());
    }

    #[test]
    fn kind_change_drops_the_source() {
        let mut form = aviutl2_form();
        form.set_source(PathBuf::from("tools/MyAviUtl2"));
        form.select_kind(Kind::Ymm4);
        assert!(form.source.is_none());
    }

    #[test]
    fn only_aviutl2_offers_the_import() {
        let mut form = aviutl2_form();
        assert!(form.offers_import());
        form.select_kind(Kind::Ymm4);
        assert!(!form.offers_import());
    }
}

use std::borrow::Cow;

use iced::alignment::Vertical;
use iced::widget::{column, row, scrollable};
use iced::{Element, Length, Padding};
use iced_m3::theme::{Accent, ColorScheme, Mode, Theme};
use iced_m3::widget::text_input::TextInput;
use iced_m3::widget::{self as m3, Action, button, card, switch};
use rust_i18n::t;

use crate::i18n::Locale;
use crate::strings;
use crate::style;

const INPUT_PADDING: f32 = 12.0;
const ENTRY_PADDING: [f32; 2] = [8.0, 16.0];
const FONT_LIST_HEIGHT: f32 = 180.0;

#[derive(Debug, Clone)]
pub enum Message {
    TokenChanged(String),
    SaveToken,
    DnsChanged(String),
    SaveDns,
    ThemeToggled,
    FontSelected(Option<String>),
    LocaleSelected(Locale),
    PortableToggled(bool),
    OpenDataDirectory,
    CheckUpdate,
    ApplyUpdate,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum UpdateState {
    Idle,
    Checking,
    UpToDate,
    Available(String),
    Installing(String),
    Applied,
}

pub struct Form {
    pub token: String,
    pub dns: String,
    pub font: Option<String>,
    pub fonts: Vec<String>,
    pub locale: Locale,
    pub portable: bool,
    pub update: UpdateState,
}

pub fn view<'a>(form: &'a Form, theme: &'a Theme, data_dir: &str) -> Element<'a, Message> {
    let background = card::Style::filled(theme).container_color;
    let token = TextInput::new(&t!("github_token_hint"), &form.token, theme)
        .with_label_text(strings::label("github_token"), background)
        .on_input(Message::TokenChanged)
        .padding(INPUT_PADDING);
    let dns = TextInput::new(&t!("dns_hint"), &form.dns, theme)
        .with_label_text(strings::label("dns"), background)
        .on_input(Message::DnsChanged)
        .padding(INPUT_PADDING);
    let save_dns = m3::button(
        button::Style::filled(theme, Accent::Primary),
        style::btn_content(style::icons::SAVE, t!("save")),
    )
    .on_press(Message::SaveDns);
    let save_token = m3::button(
        button::Style::filled(theme, Accent::Primary),
        style::btn_content(style::icons::SAVE, t!("save")),
    )
    .on_press(Message::SaveToken);
    let open = m3::button(
        button::Style::tonal(theme, Accent::Primary),
        style::btn_content(style::icons::FOLDER_OPEN, t!("open_folder")),
    )
    .on_press(Message::OpenDataDirectory);

    let mode_glyph = if theme.mode == Mode::Dark {
        style::icons::DARK_MODE
    } else {
        style::icons::LIGHT_MODE
    };
    let dark_mode = row![
        row![
            style::icon(mode_glyph).size(20).color(theme.primary()),
            style::label(theme, t!("dark_mode")).size(15),
        ]
        .spacing(8)
        .align_y(Vertical::Center)
        .width(Length::Fill),
        switch(theme, theme.mode == Mode::Dark).on_toggle(Message::ThemeToggled),
    ]
    .spacing(8)
    .align_y(Vertical::Center);

    // Appearance Section
    let appearance_section = m3::card(
        card::Style::filled(theme),
        column![dark_mode, font_picker(form, theme),].spacing(style::PADDING),
    )
    .padding(style::PADDING)
    .width(Length::Fill);

    // The portable switch exists where portable mode does.
    let portable_row: Element<'a, Message> = if launcher_core::portable_root().is_some() {
        row![
            row![
                style::icon(style::icons::FOLDER_OPEN)
                    .size(18)
                    .color(theme.primary()),
                style::label(theme, t!("portable_mode")).size(14),
            ]
            .spacing(8)
            .align_y(Vertical::Center)
            .width(Length::Fill),
            switch(theme, form.portable).on_toggle(Message::PortableToggled(!form.portable)),
        ]
        .spacing(8)
        .align_y(Vertical::Center)
        .into()
    } else {
        column![].into()
    };

    // System & Storage Section
    let system_section = m3::card(
        card::Style::filled(theme),
        column![
            version_row(&form.update, theme),
            portable_row,
            row![
                row![
                    style::icon(style::icons::FOLDER_OPEN)
                        .size(18)
                        .color(theme.primary()),
                    style::label(theme, format!("{}: {data_dir}", t!("data_directory"))).size(14),
                ]
                .spacing(8)
                .align_y(Vertical::Center)
                .width(Length::Fill),
                open
            ]
            .spacing(8)
            .align_y(Vertical::Center),
        ]
        .spacing(style::PADDING),
    )
    .padding(style::PADDING)
    .width(Length::Fill);

    // Network & API Section
    let network_section = m3::card(
        card::Style::filled(theme),
        column![
            row![
                style::icon(style::icons::KEY)
                    .size(18)
                    .color(theme.primary()),
                token,
                save_token
            ]
            .spacing(8)
            .align_y(Vertical::Center),
            row![
                style::icon(style::icons::NETWORK)
                    .size(18)
                    .color(theme.primary()),
                dns,
                save_dns
            ]
            .spacing(8)
            .align_y(Vertical::Center),
            row![
                style::icon(style::icons::LANGUAGE)
                    .size(18)
                    .color(theme.primary()),
                style::label(theme, t!("language")).size(14),
                locale_selector(form, theme),
            ]
            .spacing(12)
            .align_y(Vertical::Center),
        ]
        .spacing(style::PADDING),
    )
    .padding(style::PADDING)
    .width(Length::Fill);

    let body = column![appearance_section, system_section, network_section,].spacing(style::GAP);

    column![
        row![
            style::icon(style::icons::SETTINGS)
                .size(26)
                .color(theme.primary()),
            style::label(theme, t!("tab_settings").into_owned()).size(24),
        ]
        .spacing(8)
        .align_y(Vertical::Center),
        scrollable(body)
            .height(Length::Fill)
            .style(style::scroll(theme)),
    ]
    .spacing(style::GAP)
    .into()
}

fn font_picker<'a>(form: &'a Form, theme: &'a Theme) -> Element<'a, Message> {
    let entry = |label: Cow<'a, str>, value: Option<&'a str>| -> Element<'a, Message> {
        let selected = form.font.as_deref() == value;
        let glyph = if selected {
            style::icons::CHECK_CIRCLE
        } else {
            style::icons::FONT
        };
        let color = style::tile_content(theme, selected);
        let icon_color = if selected {
            theme.on_primary_container()
        } else {
            theme.primary()
        };
        m3::card(
            style::tile_card(theme, selected),
            row![
                style::icon(glyph).size(16).color(icon_color),
                style::label(theme, label).color(color),
            ]
            .spacing(8)
            .align_y(Vertical::Center),
        )
        .interaction(card::Interaction::Press(Action::Direct(
            Message::FontSelected(value.map(str::to_owned)),
        )))
        .padding(Padding::from(ENTRY_PADDING))
        .width(Length::Fill)
        .into()
    };
    let entries = std::iter::once(entry(t!("font_default"), None)).chain(
        form.fonts
            .iter()
            .map(|name| entry(Cow::Borrowed(name.as_str()), Some(name.as_str()))),
    );
    column![
        row![
            style::icon(style::icons::FONT)
                .size(16)
                .color(theme.primary()),
            style::label(theme, t!("font")).size(14),
        ]
        .spacing(6)
        .align_y(Vertical::Center),
        scrollable(column(entries).spacing(4))
            .height(Length::Fixed(FONT_LIST_HEIGHT))
            .style(style::scroll(theme)),
    ]
    .spacing(6)
    .into()
}

fn version_row<'a>(state: &'a UpdateState, theme: &'a Theme) -> Element<'a, Message> {
    let (status, status_icon) = match state {
        UpdateState::Idle => (None, None),
        UpdateState::Checking => (
            Some(t!("checking_update").into_owned()),
            Some(style::icons::SYNC),
        ),
        UpdateState::UpToDate => (
            Some(t!("launcher_up_to_date").into_owned()),
            Some(style::icons::CHECK_CIRCLE),
        ),
        UpdateState::Available(version) => (
            Some(format!("{}: v{version}", t!("update_available"))),
            Some(style::icons::UPDATE),
        ),
        UpdateState::Installing(_) => (
            Some(t!("launcher_updating").into_owned()),
            Some(style::icons::DOWNLOAD),
        ),
        UpdateState::Applied => (
            Some(t!("launcher_updated").into_owned()),
            Some(style::icons::CHECK_CIRCLE),
        ),
    };
    let action = match state {
        UpdateState::Idle | UpdateState::UpToDate => Some(
            m3::button(
                button::Style::tonal(theme, Accent::Primary),
                style::btn_content(style::icons::REFRESH, t!("check_update")),
            )
            .on_press(Message::CheckUpdate),
        ),
        UpdateState::Available(_) => Some(
            m3::button(
                button::Style::filled(theme, Accent::Primary),
                style::btn_content(style::icons::DOWNLOAD, t!("update")),
            )
            .on_press(Message::ApplyUpdate),
        ),
        UpdateState::Checking | UpdateState::Installing(_) | UpdateState::Applied => None,
    };
    let mut line = row![
        row![
            style::icon(style::icons::UPDATE)
                .size(18)
                .color(theme.primary()),
            style::label(
                theme,
                format!("{}: v{}", t!("launcher_version"), strings::APP_VERSION)
            )
            .size(14),
        ]
        .spacing(8)
        .align_y(Vertical::Center)
        .width(Length::Fill)
    ]
    .spacing(8)
    .align_y(Vertical::Center);
    if let (Some(status), Some(icon_glyph)) = (status, status_icon) {
        line = line.push(
            row![
                style::icon(icon_glyph).size(15).color(theme.primary()),
                style::label(theme, status).size(14),
            ]
            .spacing(4)
            .align_y(Vertical::Center),
        );
    }
    if let Some(action) = action {
        line = line.push(action);
    }
    line.into()
}

fn locale_selector<'a>(form: &'a Form, theme: &'a Theme) -> Element<'a, Message> {
    let chips: Vec<Element<'a, Message>> = Locale::ALL
        .iter()
        .map(|&locale| {
            let selected = locale == form.locale;
            let color = style::tile_content(theme, selected);
            m3::card(
                style::tile_card(theme, selected),
                iced::widget::text(locale.label()).size(12).color(color),
            )
            .interaction(card::Interaction::Press(Action::Direct(
                Message::LocaleSelected(locale),
            )))
            .padding(Padding::from([4.0, 10.0]))
            .into()
        })
        .collect();

    row(chips).spacing(6).align_y(Vertical::Center).into()
}

use iced::alignment::Vertical;
use iced::widget::{column, row, scrollable, text};
use iced::{Element, Length};
use iced_m3::theme::{ColorScheme, Theme};
use iced_m3::widget::{self, card, progress_bar};
use launcher_core::{Progress, TaskInfo, TaskState};
use rust_i18n::t;

use crate::style::{self, Tone};

const BYTES_PER_MIB: u128 = 1_048_576;

pub fn view<M: Clone + 'static>(tasks: &[TaskInfo], theme: &Theme) -> Element<'static, M> {
    let list: Element<'static, M> = if tasks.is_empty() {
        widget::card(
            card::Style::filled(theme),
            row![
                style::icon(style::icons::CHECK_CIRCLE)
                    .size(22)
                    .color(theme.tertiary()),
                style::label(theme, t!("no_tasks")).size(14),
            ]
            .spacing(8)
            .align_y(Vertical::Center),
        )
        .width(Length::Fill)
        .into()
    } else {
        column(tasks.iter().rev().map(|task| task_card(task, theme)))
            .spacing(style::GAP)
            .into()
    };
    column![
        row![
            style::icon(style::icons::TASKS)
                .size(26)
                .color(theme.primary()),
            style::label(theme, t!("tab_tasks")).size(24),
            style::label(theme, format!("({})", tasks.len())).size(16),
        ]
        .spacing(8)
        .align_y(Vertical::Center),
        scrollable(list)
            .height(Length::Fill)
            .style(style::scroll(theme)),
    ]
    .spacing(style::GAP)
    .into()
}

pub fn state_label(state: &TaskState) -> String {
    match state {
        TaskState::Queued => t!("queued").into_owned(),
        TaskState::Running { done, total, .. } => {
            format!("{} {done}/{total}", t!("running"))
        }
        TaskState::Succeeded => t!("succeeded").into_owned(),
        TaskState::Failed { .. } => t!("failed").into_owned(),
    }
}

pub const fn state_icon(state: &TaskState) -> &'static str {
    match state {
        TaskState::Queued => style::icons::HOURGLASS,
        TaskState::Running { .. } => style::icons::SYNC,
        TaskState::Succeeded => style::icons::CHECK_CIRCLE,
        TaskState::Failed { .. } => style::icons::ERROR,
    }
}

/// `state_label`, or the byte progress while a download is running.
pub fn detail_label(state: &TaskState) -> String {
    match state {
        TaskState::Running {
            transfer: Some(progress),
            ..
        } => transfer_label(*progress),
        _ => state_label(state),
    }
}

fn transfer_label(progress: Progress) -> String {
    match progress.total {
        Some(total) if total > 0 => format!(
            "{} / {} ({}%)",
            mib(progress.done),
            mib(total),
            progress.done.min(total) * 100 / total
        ),
        _ => mib(progress.done),
    }
}

fn mib(bytes: u64) -> String {
    let tenths = (u128::from(bytes) * 10 + BYTES_PER_MIB / 2) / BYTES_PER_MIB;
    format!("{}.{} MiB", tenths / 10, tenths % 10)
}

const fn tone(state: &TaskState) -> Tone {
    match state {
        TaskState::Queued => Tone::Secondary,
        TaskState::Running { .. } => Tone::Primary,
        TaskState::Succeeded => Tone::Tertiary,
        TaskState::Failed { .. } => Tone::Error,
    }
}

fn task_card<M: Clone + 'static>(task: &TaskInfo, theme: &Theme) -> Element<'static, M> {
    let head = row![
        row![
            style::icon(state_icon(&task.state))
                .size(18)
                .color(theme.primary()),
            style::label(theme, task.title.clone())
                .size(16)
                .width(Length::Fill),
        ]
        .spacing(8)
        .align_y(Vertical::Center)
        .width(Length::Fill),
        style::icon_chip::<M>(
            theme,
            state_icon(&task.state),
            state_label(&task.state),
            tone(&task.state)
        ),
    ]
    .spacing(style::GAP)
    .align_y(Vertical::Center);

    let mut body = column![head].spacing(8);
    match &task.state {
        TaskState::Running {
            done,
            total,
            transfer,
        } => {
            let overall_fraction = f32::from(*done) / f32::from(*total).max(1.0);
            let overall_bar = column![
                row![
                    style::icon(style::icons::SYNC)
                        .size(13)
                        .color(theme.primary()),
                    style::label(
                        theme,
                        t!(
                            "overall_progress",
                            done = done,
                            total = total,
                            percent = *done * 100 / total.max(&1)
                        )
                        .into_owned()
                    )
                    .size(12),
                ]
                .spacing(4)
                .align_y(Vertical::Center),
                bar(theme, Some(overall_fraction)),
            ]
            .spacing(4);

            body = body.push(overall_bar);

            if let Some(progress) = transfer {
                body = body.push(transfer_bar(theme, *progress));
            }
        }
        TaskState::Failed { reason } => {
            body = body.push(
                row![
                    style::icon(style::icons::ERROR)
                        .size(14)
                        .color(theme.error()),
                    text(reason.trim_end().to_owned())
                        .size(12)
                        .color(theme.error()),
                ]
                .spacing(6)
                .align_y(Vertical::Center),
            );
        }
        TaskState::Queued | TaskState::Succeeded => {}
    }
    widget::card(card::Style::filled(theme), body)
        .padding(14.0)
        .width(Length::Fill)
        .into()
}

fn bar<M: 'static>(theme: &Theme, progress: Option<f32>) -> Element<'static, M> {
    widget::progress_bar(progress_bar::Style::new(theme))
        .progress_maybe(progress)
        .into()
}

/// `done / total` in steps of 0.001. `total` is above zero.
fn fraction(done: u64, total: u64) -> f32 {
    let permille = u128::from(done.min(total)) * 1000 / u128::from(total);
    f32::from(u16::try_from(permille).unwrap_or(1000)) / 1000.0
}

fn transfer_bar<M: 'static>(theme: &Theme, progress: Progress) -> Element<'static, M> {
    let fraction = progress
        .total
        .filter(|total| *total > 0)
        .map(|total| fraction(progress.done, total));
    column![
        bar(theme, fraction),
        row![
            style::icon(style::icons::DOWNLOAD)
                .size(13)
                .color(theme.on_surface_variant()),
            style::label(theme, transfer_label(progress)).size(12),
        ]
        .spacing(4)
        .align_y(Vertical::Center)
    ]
    .spacing(4)
    .into()
}

