//! Copies `WebView2Loader.dll` next to the executables when the target links it dynamically.
//! `webview2-com-sys` links `WebView2LoaderStatic` for `msvc` and `WebView2Loader.dll` for other
//! Windows targets. The crate leaves the DLL in its `OUT_DIR`, so the loader fails to start
//! `Madoka-Browser.exe` with status 0xc0000135 without this copy.

use std::env;
use std::error::Error;
use std::fs;
use std::path::PathBuf;

const LOADER: &str = "WebView2Loader.dll";
const SOURCE: &str = "redist/x64/WebView2Loader.dll";

fn main() -> Result<(), Box<dyn Error>> {
    println!("cargo:rerun-if-changed=build.rs");
    println!("cargo:rerun-if-changed={SOURCE}");
    let target = |key| env::var(key).unwrap_or_default();
    if target("CARGO_CFG_TARGET_OS") != "windows" || target("CARGO_CFG_TARGET_ENV") == "msvc" {
        return Ok(());
    }
    assert_eq!(
        target("CARGO_CFG_TARGET_ARCH"),
        "x86_64",
        "{SOURCE} supports x86_64 only"
    );
    let manifest = required_path("CARGO_MANIFEST_DIR")?;
    let out = required_path("OUT_DIR")?;
    // OUT_DIR is `<profile dir>/build/<package>-<hash>/out`.
    let Some(profile) = out.ancestors().nth(3) else {
        return Err("profile directory above OUT_DIR is missing".into());
    };
    fs::copy(manifest.join(SOURCE), profile.join(LOADER))
        .map_err(|error| format!("copy {LOADER}: {error}"))?;
    Ok(())
}

fn required_path(key: &str) -> Result<PathBuf, String> {
    env::var_os(key)
        .map(PathBuf::from)
        .ok_or_else(|| format!("{key} is unset"))
}

#![cfg_attr(windows, windows_subsystem = "windows")]

//! Web view window. Usage: `Madoka-Browser <url> [--profile <dir>] [--save-dir <dir>]`.
//!
//! `--profile` keeps cookies and storage in `<dir>`, so a login (BOOTH) lasts across launches.
//!
//! Without `--save-dir`, a download that starts in the page is cancelled, the window closes,
//! and stdout receives one line: `download <file name>\t<url>`.
//! The file name is empty when the web view reports none.
//!
//! With `--save-dir`, the web view saves the download into `<dir>` with its own session,
//! so a download that needs the login of the page succeeds. stdout receives
//! `download <file name>\t<url>` at the start and `saved <absolute path>\t<url>` after the file
//! is complete, then the window closes. A failed download writes `failed <url>` to stdout
//! and keeps the window open.
//!
//! A new window request (`window.open`, `target="_blank"`) with an http or https url
//! navigates this window. A failure writes one line to stderr and exits with status 1.

use std::io::Write;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

use tao::dpi::LogicalSize;
use tao::event::{Event, WindowEvent};
use tao::event_loop::{ControlFlow, EventLoopBuilder};
use tao::window::WindowBuilder;
use wry::{NewWindowResponse, WebContext, WebViewBuilder};

const TITLE: &str = "Madoka Browser";
const WIDTH: f64 = 1100.0;
const HEIGHT: f64 = 760.0;
const DOWNLOAD_PREFIX: &str = "download ";
const SAVED_PREFIX: &str = "saved ";
const FAILED_PREFIX: &str = "failed ";
const PROFILE_FLAG: &str = "--profile";
const SAVE_DIR_FLAG: &str = "--save-dir";
const FALLBACK_NAME: &str = "download";

enum Signal {
    Download,
    Navigate(String),
}

struct Options {
    url: String,
    profile: Option<PathBuf>,
    save_dir: Option<PathBuf>,
}

fn main() -> ExitCode {
    match run() {
        Ok(()) => ExitCode::SUCCESS,
        Err(message) => {
            let _ = writeln!(std::io::stderr(), "{message}");
            ExitCode::FAILURE
        }
    }
}

fn parse_options() -> Result<Options, String> {
    let usage = "usage: Madoka-Browser <url> [--profile <dir>] [--save-dir <dir>]";
    let mut args = std::env::args().skip(1);
    let url = args.next().ok_or(usage)?;
    let mut options = Options {
        url,
        profile: None,
        save_dir: None,
    };
    while let Some(flag) = args.next() {
        let value = args.next().map(PathBuf::from).ok_or(usage)?;
        match flag.as_str() {
            PROFILE_FLAG => options.profile = Some(value),
            SAVE_DIR_FLAG => options.save_dir = Some(value),
            _ => return Err(usage.to_owned()),
        }
    }
    Ok(options)
}

/// `<dir>/<name>`, or `<dir>/<stem> (<n>)<.ext>` for the smallest `n >= 1` that is free.
fn unique_path(dir: &Path, name: &str) -> PathBuf {
    let name = Path::new(name)
        .file_name()
        .map(|name| name.to_string_lossy().into_owned())
        .filter(|name| !name.is_empty())
        .unwrap_or_else(|| FALLBACK_NAME.to_owned());
    let first = dir.join(&name);
    if !first.exists() {
        return first;
    }
    let path = Path::new(&name);
    let stem = path
        .file_stem()
        .map_or_else(|| name.clone(), |stem| stem.to_string_lossy().into_owned());
    let extension = path
        .extension()
        .map_or_default(|extension| format!(".{}", extension.to_string_lossy()));
    (1..=u32::MAX)
        .map(|n| dir.join(format!("{stem} ({n}){extension}")))
        .find(|candidate| !candidate.exists())
        .unwrap_or(first)
}

fn emit(line: &str) {
    let mut out = std::io::stdout();
    let _ = writeln!(out, "{line}");
    let _ = out.flush();
}

fn run() -> Result<(), String> {
    let options = parse_options()?;
    if let Some(dir) = &options.save_dir {
        std::fs::create_dir_all(dir)
            .map_err(|error| format!("save dir {}: {error}", dir.display()))?;
    }
    if let Some(dir) = &options.profile {
        std::fs::create_dir_all(dir)
            .map_err(|error| format!("profile {}: {error}", dir.display()))?;
    }
    let event_loop = EventLoopBuilder::<Signal>::with_user_event().build();
    let proxy = event_loop.create_proxy();
    let navigate_proxy = proxy.clone();
    let completed_proxy = proxy.clone();
    let window = WindowBuilder::new()
        .with_title(TITLE)
        .with_inner_size(LogicalSize::new(WIDTH, HEIGHT))
        .build(&event_loop)
        .map_err(|error| format!("window: {error}"))?;
    let mut context = WebContext::new(options.profile.clone());
    let save_dir = options.save_dir.clone();
    let saves = save_dir.is_some();
    let builder = WebViewBuilder::new_with_web_context(&mut context)
        .with_url(options.url)
        .with_download_started_handler(move |url, path| {
            let name = path
                .file_name()
                .map_or_default(|name| name.to_string_lossy().into_owned());
            emit(&format!("{DOWNLOAD_PREFIX}{name}\t{url}"));
            save_dir.as_ref().map_or_else(
                || {
                    let _ = proxy.send_event(Signal::Download);
                    false
                },
                |dir| {
                    *path = unique_path(dir, &name);
                    true
                },
            )
        })
        .with_download_completed_handler(move |url, path, success| {
            if !saves {
                return;
            }
            match path.filter(|_| success) {
                Some(path) => {
                    emit(&format!("{SAVED_PREFIX}{}\t{url}", path.display()));
                    let _ = completed_proxy.send_event(Signal::Download);
                }
                None => emit(&format!("{FAILED_PREFIX}{url}")),
            }
        })
        .with_new_window_req_handler(move |url, _| {
            if url.starts_with("https://") || url.starts_with("http://") {
                let _ = navigate_proxy.send_event(Signal::Navigate(url));
            }
            NewWindowResponse::Deny
        });
    #[cfg(any(target_os = "windows", target_os = "macos"))]
    let webview = builder.build(&window);
    #[cfg(not(any(target_os = "windows", target_os = "macos")))]
    let webview = {
        use tao::platform::unix::WindowExtUnix;
        use wry::WebViewBuilderExtUnix;
        let vbox = window.default_vbox().ok_or("window has no gtk box")?;
        builder.build_gtk(vbox)
    };
    let webview = webview.map_err(|error| format!("web view: {error}"))?;
    event_loop.run(move |event, _, flow| {
        *flow = ControlFlow::Wait;
        match event {
            Event::UserEvent(Signal::Navigate(url)) => {
                let _ = webview.load_url(&url);
            }
            Event::WindowEvent {
                event: WindowEvent::CloseRequested,
                ..
            }
            | Event::UserEvent(Signal::Download) => *flow = ControlFlow::Exit,
            _ => {}
        }
    })
}

use std::collections::HashSet;
use std::fs::{self, File, OpenOptions};
use std::io::{self, BufReader, Cursor, Read};
use std::path::{Component, Path, PathBuf};

use zip::ZipArchive;

use crate::Error;
use crate::model::{ensure_relative_path, ensure_single_component};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Layout {
    /// Entries may sit in sub-directories.
    Tree,
    /// Like `Tree`. When one directory holds every entry, that directory is dropped from the paths.
    TreeWithoutRoot,
}

struct Entry {
    index: usize,
    rel: String,
    is_dir: bool,
    /// Target of a symbolic link entry. Validated by `ensure_link_inside`.
    link: Option<String>,
}

/// Files and directories that a task created, in creation order.
#[derive(Default)]
pub struct Created {
    pub(crate) files: Vec<PathBuf>,
    dirs: Vec<PathBuf>,
}

impl Created {
    pub(crate) fn roll_back(self) {
        for file in self.files {
            let _ = fs::remove_file(file);
        }
        for dir in self.dirs.into_iter().rev() {
            let _ = fs::remove_dir(dir);
        }
    }
}

const MAGIC_LEN: usize = 4;
const ZSTD_MAGIC: [u8; MAGIC_LEN] = [0x28, 0xB5, 0x2F, 0xFD];
const ELF_MAGIC: [u8; MAGIC_LEN] = [0x7F, b'E', b'L', b'F'];
/// Mach-O 64-bit little endian, and the universal (fat) binary.
const MACHO_MAGICS: [[u8; MAGIC_LEN]; 2] = [[0xCF, 0xFA, 0xED, 0xFE], [0xCA, 0xFE, 0xBA, 0xBE]];
const LINK_TARGET_LIMIT: u64 = 4096;
const JUNK_NAMES: [&str; 2] = ["__MACOSX", ".DS_Store"];
const APPLE_DOUBLE_PREFIX: &str = "._";

enum Source {
    Zip(ZipArchive<BufReader<File>>),
    /// Zstandard-compressed tar. `Entry::index` is the position in the stream.
    TarZstd,
    /// One file that is stored under `Entry::rel`.
    Single,
}

/// Container of a download, told by its first bytes.
enum Format {
    Zip,
    TarZstd,
    Executable,
}

fn sniff(path: &Path) -> Result<Format, Error> {
    let mut bytes = Vec::with_capacity(MAGIC_LEN);
    File::open(path)
        .map_err(|e| Error::io(path, e))?
        .take(MAGIC_LEN as u64)
        .read_to_end(&mut bytes)
        .map_err(|e| Error::io(path, e))?;
    let head: [u8; MAGIC_LEN] = bytes.try_into().unwrap_or_default();
    Ok(if head == ELF_MAGIC || MACHO_MAGICS.contains(&head) {
        Format::Executable
    } else if head == ZSTD_MAGIC {
        Format::TarZstd
    } else {
        Format::Zip
    })
}

pub struct Archive {
    path: PathBuf,
    source: Source,
    entries: Vec<Entry>,
}

impl Archive {
    /// Opens a zip. Validates every entry name and type. Writes nothing.
    pub(crate) fn open(path: &Path, layout: Layout) -> Result<Self, Error> {
        let file = File::open(path).map_err(|e| Error::io(path, e))?;
        let mut zip = ZipArchive::new(BufReader::new(file)).map_err(|e| Error::zip(path, e))?;
        let mut entries = Vec::with_capacity(zip.len());
        let mut seen = HashSet::new();
        for index in 0..zip.len() {
            let entry = zip.by_index_raw(index).map_err(|e| Error::zip(path, e))?;
            let name = entry.name().map_err(|e| Error::zip(path, e))?.into_owned();
            let is_symlink = entry.is_symlink();
            let is_dir = entry.is_dir();
            drop(entry);
            let rel = name.replace('\\', "/").trim_end_matches('/').to_owned();
            if is_junk(&rel) {
                continue;
            }
            ensure_relative_path(&rel)?;
            let link = if is_symlink {
                let target = read_link_target(&mut zip, index, path, &name)?;
                ensure_link_inside(&rel, &target)?;
                Some(target)
            } else {
                None
            };
            if !seen.insert(rel.clone()) {
                return Err(Error::UnsafePath(name));
            }
            entries.push(Entry {
                index,
                rel,
                is_dir,
                link,
            });
        }
        ensure_not_below_link(&entries)?;
        Ok(Self::new(path, Source::Zip(zip), entries, layout))
    }

    /// Like `open`, and accepts the other downloads of an app: a Zstandard-compressed tar,
    /// and a bare executable, which becomes the single file `single_name`.
    pub(crate) fn open_app(path: &Path, layout: Layout, single_name: &str) -> Result<Self, Error> {
        match sniff(path)? {
            Format::Zip => Self::open(path, layout),
            Format::TarZstd => Self::open_tar(path, layout),
            Format::Executable => {
                ensure_single_component(single_name)?;
                let entry = Entry {
                    index: 0,
                    rel: single_name.to_owned(),
                    is_dir: false,
                    link: None,
                };
                Ok(Self::new(path, Source::Single, vec![entry], layout))
            }
        }
    }

    fn open_tar(path: &Path, layout: Layout) -> Result<Self, Error> {
        let mut tar = tar_stream(path)?;
        let mut entries = Vec::new();
        let mut seen = HashSet::new();
        for (index, entry) in tar.entries().map_err(|e| Error::tar(path, e))?.enumerate() {
            let entry = entry.map_err(|e| Error::tar(path, e))?;
            let kind = entry.header().entry_type();
            if kind.is_pax_global_extensions() {
                continue;
            }
            let name = entry
                .path()
                .map_err(|e| Error::tar(path, e))?
                .to_string_lossy()
                .into_owned();
            if kind.is_symlink() || kind.is_hard_link() {
                return Err(Error::SymlinkEntry(name));
            }
            let is_dir = kind.is_dir();
            if !is_dir && !kind.is_file() {
                return Err(Error::UnsafePath(name));
            }
            let normalized = name.replace('\\', "/");
            let rel = normalized.trim_start_matches("./").trim_end_matches('/');
            if rel.is_empty() || rel == "." {
                continue;
            }
            ensure_relative_path(rel)?;
            if !seen.insert(rel.to_owned()) {
                return Err(Error::UnsafePath(name));
            }
            entries.push(Entry {
                index,
                rel: rel.to_owned(),
                is_dir,
                link: None,
            });
        }
        Ok(Self::new(path, Source::TarZstd, entries, layout))
    }

    fn new(path: &Path, source: Source, mut entries: Vec<Entry>, layout: Layout) -> Self {
        if layout == Layout::TreeWithoutRoot {
            strip_common_root(&mut entries);
        }
        Self {
            path: path.to_owned(),
            source,
            entries,
        }
    }

    pub(crate) fn files(&self) -> Vec<String> {
        self.entries
            .iter()
            .filter(|entry| !entry.is_dir)
            .map(|entry| entry.rel.clone())
            .collect()
    }

    /// Creates every file with `create_new`. On failure removes the files and directories it created.
    pub(crate) fn extract(&mut self, dest: &Path) -> Result<(), Error> {
        let mut created = Created::default();
        let result = match &mut self.source {
            Source::Zip(zip) => write_zip(zip, &self.entries, &self.path, dest, &mut created),
            Source::TarZstd => write_tar(&self.entries, &self.path, dest, &mut created),
            Source::Single => write_single(&self.entries, &self.path, dest, &mut created),
        };
        if result.is_err() {
            created.roll_back();
        }
        result
    }
}

fn tar_stream(path: &Path) -> Result<tar::Archive<impl Read>, Error> {
    let file = File::open(path).map_err(|e| Error::io(path, e))?;
    let decoder = zstd::stream::read::Decoder::new(file).map_err(|e| Error::tar(path, e))?;
    Ok(tar::Archive::new(decoder))
}

/// Creates `target` with `create_new` and records it in `created`.
fn create_file(target: &Path, created: &mut Created) -> Result<File, Error> {
    let out = OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(target)
        .map_err(|e| Error::io(target, e))?;
    created.files.push(target.to_owned());
    Ok(out)
}

fn write_zip(
    zip: &mut ZipArchive<BufReader<File>>,
    entries: &[Entry],
    archive: &Path,
    dest: &Path,
    created: &mut Created,
) -> Result<(), Error> {
    for entry in entries {
        let target = dest.join(&entry.rel);
        if entry.is_dir {
            make_dirs(&target, created)?;
            continue;
        }
        if let Some(parent) = target.parent() {
            make_dirs(parent, created)?;
        }
        if let Some(link) = &entry.link {
            make_symlink(link, &target, created)?;
            continue;
        }
        let mut source = zip
            .by_index(entry.index)
            .map_err(|e| Error::zip(archive, e))?;
        let mut out = create_file(&target, created)?;
        io::copy(&mut source, &mut out).map_err(|e| Error::io(&target, e))?;
        #[cfg(unix)]
        set_mode(&target, source.unix_mode())?;
    }
    Ok(())
}

fn write_tar(
    entries: &[Entry],
    archive: &Path,
    dest: &Path,
    created: &mut Created,
) -> Result<(), Error> {
    let mut tar = tar_stream(archive)?;
    let mut wanted = entries.iter().peekable();
    for (index, entry) in tar
        .entries()
        .map_err(|e| Error::tar(archive, e))?
        .enumerate()
    {
        let Some(want) = wanted.next_if(|want| want.index == index) else {
            continue;
        };
        let mut entry = entry.map_err(|e| Error::tar(archive, e))?;
        let target = dest.join(&want.rel);
        if want.is_dir {
            make_dirs(&target, created)?;
            continue;
        }
        if let Some(parent) = target.parent() {
            make_dirs(parent, created)?;
        }
        let mut out = create_file(&target, created)?;
        io::copy(&mut entry, &mut out).map_err(|e| Error::tar(archive, e))?;
        #[cfg(unix)]
        set_mode(&target, entry.header().mode().ok())?;
    }
    Ok(())
}

/// Copies the downloaded executable to its entry and sets the executable bits.
fn write_single(
    entries: &[Entry],
    source: &Path,
    dest: &Path,
    created: &mut Created,
) -> Result<(), Error> {
    for entry in entries {
        let target = dest.join(&entry.rel);
        copy_file(source, &target, created)?;
        #[cfg(unix)]
        set_mode(&target, Some(0o755))?;
    }
    Ok(())
}

/// Metadata that macOS archivers add: `__MACOSX/`, `.DS_Store`, and `AppleDouble` `._*` files.
fn is_junk(rel: &str) -> bool {
    rel.split('/')
        .any(|part| JUNK_NAMES.contains(&part) || part.starts_with(APPLE_DOUBLE_PREFIX))
}

fn read_link_target(
    zip: &mut ZipArchive<BufReader<File>>,
    index: usize,
    archive: &Path,
    name: &str,
) -> Result<String, Error> {
    let entry = zip.by_index(index).map_err(|e| Error::zip(archive, e))?;
    let mut target = String::new();
    entry
        .take(LINK_TARGET_LIMIT)
        .read_to_string(&mut target)
        .map_err(|_| Error::SymlinkEntry(name.to_owned()))?;
    Ok(target)
}

/// Accepts a symbolic link only on unix, and only when its target is relative and made of
/// leading `..` components followed by normal components, with no more `..` than the link
/// has parent directories.
///
/// Every accepted target names a path inside the archive root without resolving any other
/// link. Together with `ensure_not_below_link` no chain of links can leave the root.
fn ensure_link_inside(rel: &str, target: &str) -> Result<(), Error> {
    let rejected = || Error::SymlinkEntry(rel.to_owned());
    if !cfg!(unix) || target.is_empty() || target.contains(['\\', '\0']) {
        return Err(rejected());
    }
    let parents = rel.split('/').count() - 1;
    let mut ups = 0_usize;
    let mut normals = 0_usize;
    for component in Path::new(target).components() {
        match component {
            Component::ParentDir if normals == 0 => ups += 1,
            Component::Normal(_) => normals += 1,
            Component::CurDir => {}
            _ => return Err(rejected()),
        }
    }
    if ups > parents {
        return Err(rejected());
    }
    Ok(())
}

/// Rejects an entry whose parent directory is a symbolic link of the same archive.
fn ensure_not_below_link(entries: &[Entry]) -> Result<(), Error> {
    let links: HashSet<&str> = entries
        .iter()
        .filter(|entry| entry.link.is_some())
        .map(|entry| entry.rel.as_str())
        .collect();
    if links.is_empty() {
        return Ok(());
    }
    entries
        .iter()
        .find(|entry| {
            Path::new(&entry.rel)
                .ancestors()
                .skip(1)
                .filter_map(Path::to_str)
                .any(|ancestor| links.contains(ancestor))
        })
        .map_or(Ok(()), |entry| Err(Error::UnsafePath(entry.rel.clone())))
}

/// Creates the symbolic link `target` that points to `link`.
#[cfg(unix)]
fn make_symlink(link: &str, target: &Path, created: &mut Created) -> Result<(), Error> {
    std::os::unix::fs::symlink(link, target).map_err(|e| Error::io(target, e))?;
    created.files.push(target.to_owned());
    Ok(())
}

/// `ensure_link_inside` rejects every link on this host, so no entry reaches this function.
#[cfg(not(unix))]
fn make_symlink(link: &str, _target: &Path, _created: &mut Created) -> Result<(), Error> {
    Err(Error::SymlinkEntry(link.to_owned()))
}

/// Copies the symbolic link `from` to `to` and keeps its target text.
#[cfg(unix)]
pub(crate) fn copy_link(from: &Path, to: &Path, created: &mut Created) -> Result<(), Error> {
    let link = fs::read_link(from).map_err(|e| Error::io(from, e))?;
    std::os::unix::fs::symlink(link, to).map_err(|e| Error::io(to, e))?;
    created.files.push(to.to_owned());
    Ok(())
}

/// Symbolic links are left out on this host, as in `store::copy_dir`.
#[cfg(not(unix))]
pub(crate) fn copy_link(_from: &Path, _to: &Path, _created: &mut Created) -> Result<(), Error> {
    Ok(())
}

/// Removes the first path component of every entry when one directory holds all entries.
fn strip_common_root(entries: &mut Vec<Entry>) {
    let Some(root) = entries
        .first()
        .and_then(|entry| entry.rel.split('/').next())
        .map(str::to_owned)
    else {
        return;
    };
    let prefix = format!("{root}/");
    let all_inside = entries
        .iter()
        .all(|entry| (entry.is_dir && entry.rel == root) || entry.rel.starts_with(&prefix));
    let has_child = entries.iter().any(|entry| entry.rel.starts_with(&prefix));
    if !(all_inside && has_child) {
        return;
    }
    entries.retain(|entry| entry.rel != root);
    for entry in entries.iter_mut() {
        if let Some(stripped) = entry.rel.strip_prefix(&prefix).map(str::to_owned) {
            entry.rel = stripped;
        }
    }
}

/// Sets 0o755 on entries that carry an executable bit in the zip, 0o644 on the others.
#[cfg(unix)]
fn set_mode(path: &Path, zip_mode: Option<u32>) -> Result<(), Error> {
    use std::os::unix::fs::PermissionsExt;

    let executable = zip_mode.is_some_and(|mode| mode & 0o111 != 0);
    let mode = if executable { 0o755 } else { 0o644 };
    fs::set_permissions(path, fs::Permissions::from_mode(mode)).map_err(|e| Error::io(path, e))
}

pub fn make_dirs(path: &Path, created: &mut Created) -> Result<(), Error> {
    let mut missing = Vec::new();
    let mut current = Some(path);
    while let Some(dir) = current {
        if dir.exists() {
            break;
        }
        missing.push(dir.to_owned());
        current = dir.parent();
    }
    for dir in missing.into_iter().rev() {
        fs::create_dir(&dir).map_err(|e| Error::io(&dir, e))?;
        created.dirs.push(dir);
    }
    Ok(())
}

/// Copies `source` to `target` with `create_new`, creating the missing parent directories.
/// Fails with `AlreadyExists` when `target` exists.
pub fn copy_file(source: &Path, target: &Path, created: &mut Created) -> Result<(), Error> {
    if let Some(parent) = target.parent() {
        make_dirs(parent, created)?;
    }
    let mut input = File::open(source).map_err(|e| Error::io(source, e))?;
    let mut out = OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(target)
        .map_err(|e| match e.kind() {
            io::ErrorKind::AlreadyExists => Error::AlreadyExists(target.to_owned()),
            _ => Error::io(target, e),
        })?;
    created.files.push(target.to_owned());
    io::copy(&mut input, &mut out).map_err(|e| Error::io(target, e))?;
    Ok(())
}

/// Names of the file entries of the zip at `path`. Separators are `/`.
///
/// # Errors
///
/// Returns `Error::Io` when `path` cannot be opened and `Error::Zip` when it is not a zip
/// or an entry cannot be read.
pub fn zip_entry_names(path: &Path) -> Result<Vec<String>, Error> {
    let file = File::open(path).map_err(|source| Error::io(path, source))?;
    let mut zip =
        ZipArchive::new(BufReader::new(file)).map_err(|source| Error::zip(path, source))?;
    let mut names = Vec::with_capacity(zip.len());
    for index in 0..zip.len() {
        let entry = zip
            .by_index(index)
            .map_err(|source| Error::zip(path, source))?;
        if !entry.is_dir() {
            let name = entry.name().map_err(|source| Error::zip(path, source))?;
            names.push(name.replace('\\', "/"));
        }
    }
    Ok(names)
}

/// Reads the file entry `name` of the zip at `path` (case-insensitive, `/` separators).
/// Returns `None` when there is no such entry or it exceeds `limit` bytes.
///
/// # Errors
///
/// Returns `Error::Io` when `path` cannot be opened and `Error::Zip` when it is not a zip.
pub fn zip_read_entry(path: &Path, name: &str, limit: u64) -> Result<Option<Vec<u8>>, Error> {
    let file = File::open(path).map_err(|source| Error::io(path, source))?;
    let mut zip =
        ZipArchive::new(BufReader::new(file)).map_err(|source| Error::zip(path, source))?;
    for index in 0..zip.len() {
        let entry = zip
            .by_index(index)
            .map_err(|source| Error::zip(path, source))?;
        if entry.is_dir() {
            continue;
        }
        let Ok(entry_name) = entry.name() else {
            continue;
        };
        if !entry_name.replace('\\', "/").eq_ignore_ascii_case(name) || entry.size() > limit {
            continue;
        }
        let mut bytes = Vec::new();
        entry
            .take(limit)
            .read_to_end(&mut bytes)
            .map_err(|source| Error::io(path, source))?;
        return Ok(Some(bytes));
    }
    Ok(None)
}

const SEVEN_ZIP_SIGNATURE: [u8; 6] = [0x37, 0x7A, 0xBC, 0xAF, 0x27, 0x1C];

/// Offset of the first 7z signature in `bytes`.
fn find_seven_zip_signature(bytes: &[u8]) -> Option<usize> {
    bytes
        .windows(SEVEN_ZIP_SIGNATURE.len())
        .position(|window| window == SEVEN_ZIP_SIGNATURE)
}

/// Extracts the 7z data of the self-extracting executable `sfx` into `dest`.
/// An entry whose path leaves `dest` is skipped.
///
/// # Errors
///
/// Returns `Error::Io` when `sfx` cannot be read or `dest` cannot be created,
/// and `Error::Zip` when `sfx` holds no 7z data or the extraction fails.
pub fn extract_sfx(sfx: &Path, dest: &Path) -> Result<(), Error> {
    let bytes = fs::read(sfx).map_err(|source| Error::io(sfx, source))?;
    let payload = find_seven_zip_signature(&bytes)
        .and_then(|offset| bytes.get(offset..))
        .ok_or_else(|| Error::zip(sfx, "7z signature not found"))?;
    fs::create_dir_all(dest).map_err(|source| Error::io(dest, source))?;
    sevenz_rust2::decompress_with_extract_fn_and_password(
        Cursor::new(payload),
        dest,
        sevenz_rust2::Password::empty(),
        |entry, reader, target| {
            if ensure_relative_path(entry.name()).is_err() {
                return Ok(true);
            }
            sevenz_rust2::default_entry_extract_fn(entry, reader, target)
        },
    )
    .map_err(|source| Error::zip(sfx, source))
}

#[cfg(test)]
mod sfx_tests {
    use super::{SEVEN_ZIP_SIGNATURE, find_seven_zip_signature};

    #[test]
    fn signature_is_found_after_the_executable_stub() {
        let mut bytes = vec![0x4D, 0x5A, 0x00, 0x37, 0x7A];
        let offset = bytes.len();
        bytes.extend_from_slice(&SEVEN_ZIP_SIGNATURE);
        bytes.extend_from_slice(&[0, 4]);
        assert_eq!(find_seven_zip_signature(&bytes), Some(offset));
    }

    #[test]
    fn signature_is_absent_from_a_plain_executable() {
        assert_eq!(find_seven_zip_signature(&[0x4D, 0x5A, 0x90, 0x00]), None);
    }
}

#[cfg(test)]
mod bundle_tests {
    use super::{Entry, ensure_link_inside, ensure_not_below_link, is_junk};

    fn entry(rel: &str, link: Option<&str>) -> Entry {
        Entry {
            index: 0,
            rel: rel.to_owned(),
            is_dir: false,
            link: link.map(str::to_owned),
        }
    }

    #[test]
    fn apple_metadata_is_junk() {
        assert!(is_junk("__MACOSX/X.app/._Info.plist"));
        assert!(is_junk("X.app/Contents/.DS_Store"));
        assert!(is_junk("X.app/Contents/._MacOS"));
        assert!(!is_junk("X.app/Contents/MacOS/x"));
    }

    #[cfg(unix)]
    #[test]
    fn links_inside_the_root_are_accepted() {
        assert!(ensure_link_inside("X.app/Frameworks/F.framework/Versions/Current", "A").is_ok());
        assert!(
            ensure_link_inside(
                "X.app/Frameworks/F.framework/Resources",
                "Versions/Current/Resources"
            )
            .is_ok()
        );
        assert!(ensure_link_inside("a/b/l", "../../x").is_ok());
    }

    #[test]
    fn links_leaving_the_root_are_rejected() {
        for (rel, target) in [
            ("l", "/etc/passwd"),
            ("l", ".."),
            ("a/l", "../.."),
            ("a/l", "b/../../.."),
            ("l", ""),
            ("l", "C:\\x"),
        ] {
            assert!(
                ensure_link_inside(rel, target).is_err(),
                "{rel} -> {target}"
            );
        }
    }

    #[test]
    fn an_entry_below_a_link_is_rejected() {
        let entries = [entry("a/l", Some("b")), entry("a/l/file", None)];
        assert!(ensure_not_below_link(&entries).is_err());
        let entries = [entry("a/l", Some("b")), entry("a/other", None)];
        assert!(ensure_not_below_link(&entries).is_ok());
    }
}

//! Application bundles (`X.app`) of macOS.

use std::ffi::OsStr;
use std::path::{Path, PathBuf};

use sysinfo::System;

const BUNDLE_EXTENSION: &str = "app";
const EXECUTABLE_DIR: [&str; 2] = ["Contents", "MacOS"];
const INFO_PLIST: [&str; 2] = ["Contents", "Info.plist"];
const EXECUTABLE_KEY: &str = "CFBundleExecutable";
const MIN_OS_KEY: &str = "LSMinimumSystemVersion";

/// `true` for a directory name that ends with `.app`.
pub fn is_bundle_dir(path: &Path) -> bool {
    path.extension()
        .is_some_and(|extension| extension.eq_ignore_ascii_case(BUNDLE_EXTENSION))
}

/// `X.app` of the executable `X.app/Contents/MacOS/<exe>`. `None` for any other layout.
pub fn bundle_root(exe: &Path) -> Option<&Path> {
    let macos = exe.parent()?;
    let contents = macos.parent()?;
    let bundle = contents.parent()?;
    let [first, second] = EXECUTABLE_DIR;
    (macos.file_name()? == second && contents.file_name()? == first && is_bundle_dir(bundle))
        .then_some(bundle)
}

/// Directory `Contents/MacOS` of `bundle`.
pub fn executable_dir(bundle: &Path) -> PathBuf {
    EXECUTABLE_DIR
        .into_iter()
        .fold(bundle.to_path_buf(), |path, part| path.join(part))
}

/// String value of `key` in `Contents/Info.plist`. `None` when the file or the key is missing.
fn info_string(bundle: &Path, key: &str) -> Option<String> {
    let plist = INFO_PLIST
        .into_iter()
        .fold(bundle.to_path_buf(), |path, part| path.join(part));
    plist::Value::from_file(plist)
        .ok()?
        .as_dictionary()?
        .get(key)?
        .as_string()
        .map(str::to_owned)
}

/// Executable that `CFBundleExecutable` names, below `Contents/MacOS`.
/// `None` when the plist is missing or the value is not a plain file name.
pub fn declared_executable(bundle: &Path) -> Option<PathBuf> {
    let name = info_string(bundle, EXECUTABLE_KEY)?;
    (Path::new(&name).file_name() == Some(OsStr::new(&name)))
        .then(|| executable_dir(bundle).join(name))
}

/// `LSMinimumSystemVersion` of `bundle` when the running macOS is older, else `None`.
pub fn unsupported_min_os(bundle: &Path) -> Option<String> {
    let required = info_string(bundle, MIN_OS_KEY)?;
    let current = System::os_version().ok()?;
    is_older(&current, &required).then_some(required)
}

/// `true` when the dotted version `current` is older than `required`. Missing parts count as 0.
fn is_older(current: &str, required: &str) -> bool {
    let parts = |version: &str| -> Vec<u32> {
        version
            .split('.')
            .map_while(|part| part.parse().ok())
            .collect()
    };
    let (current, required) = (parts(current), parts(required));
    (0..current.len().max(required.len()))
        .map(|index| {
            (
                current.get(index).copied().unwrap_or(0),
                required.get(index).copied().unwrap_or(0),
            )
        })
        .find(|(have, need)| have != need)
        .is_some_and(|(have, need)| have < need)
}

#[cfg(test)]
mod tests {
    use std::fs;

    use tempfile::tempdir;

    use super::{declared_executable, is_older};

    fn bundle_with(executable: &str) -> tempfile::TempDir {
        let dir = tempdir().unwrap();
        let contents = dir.path().join("X.app/Contents");
        fs::create_dir_all(&contents).unwrap();
        let plist = format!(
            "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<plist version=\"1.0\"><dict>\
             <key>CFBundleExecutable</key><string>{executable}</string></dict></plist>"
        );
        fs::write(contents.join("Info.plist"), plist).unwrap();
        dir
    }

    #[test]
    fn older_version_is_detected_with_padding() {
        assert!(is_older("15.1", "27.0"));
        assert!(is_older("27", "27.0.1"));
        assert!(!is_older("27", "27.0"));
        assert!(!is_older("27.1", "27.0"));
    }

    #[test]
    fn declared_executable_names_a_file_of_contents_macos() {
        let dir = bundle_with("Tool");
        let bundle = dir.path().join("X.app");
        assert_eq!(
            declared_executable(&bundle),
            Some(bundle.join("Contents/MacOS/Tool"))
        );
    }

    #[test]
    fn declared_executable_rejects_a_path() {
        let dir = bundle_with("../Tool");
        assert_eq!(declared_executable(&dir.path().join("X.app")), None);
    }

    #[test]
    fn declared_executable_is_none_without_plist() {
        let dir = tempdir().unwrap();
        assert_eq!(declared_executable(dir.path()), None);
    }
}

use std::fs::File;
use std::io::Read;
use std::path::Path;

use base64::Engine;
use base64::engine::general_purpose::STANDARD;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256, Sha384};
use url::Url;
use xxhash_rust::xxh3::Xxh3;

use crate::{Arch, Bundle, Edition, Host};

const SHA256_DIGEST_PREFIX: &str = "sha256:";
const SHA384_SRI_PREFIX: &str = "sha384-";
const SHA384_BYTES: usize = 48;
const XXH3_128_HEX_DIGITS: usize = 32;
const READ_CHUNK: usize = 64 * 1024;
/// Seconds that `Step::RunAuoSetup` waits for the setup program.
pub const AUO_SETUP_TIMEOUT_SECS: u64 = 600;
const HEX_RADIX: u32 = 16;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum HashAlgo {
    Sha256,
    Sha384,
    Xxh3_128,
}

/// `hex` holds lowercase hexadecimal digits.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Hash {
    pub algo: HashAlgo,
    pub hex: String,
}

impl Hash {
    /// Parses the `sha256:<64 hex digits>` form that GitHub reports per release asset.
    #[must_use]
    pub fn parse_digest(digest: &str) -> Option<Self> {
        let hex = digest.strip_prefix(SHA256_DIGEST_PREFIX)?;
        let valid = hex.len() == 64 && hex.bytes().all(|b| b.is_ascii_hexdigit());
        valid.then(|| Self {
            algo: HashAlgo::Sha256,
            hex: hex.to_ascii_lowercase(),
        })
    }

    /// Parses the `sha384-<base64>` Subresource Integrity form of the APM data.
    #[must_use]
    pub fn parse_sri(text: &str) -> Option<Self> {
        let encoded = text.strip_prefix(SHA384_SRI_PREFIX)?;
        let bytes = STANDARD.decode(encoded).ok()?;
        (bytes.len() == SHA384_BYTES).then(|| Self {
            algo: HashAlgo::Sha384,
            hex: to_hex(bytes.iter()),
        })
    }

    /// Parses the 32 hexadecimal digits of an XXH3-128 value.
    #[must_use]
    pub fn parse_xxh3_128(text: &str) -> Option<Self> {
        let valid =
            text.len() == XXH3_128_HEX_DIGITS && text.bytes().all(|b| b.is_ascii_hexdigit());
        valid.then(|| Self {
            algo: HashAlgo::Xxh3_128,
            hex: text.to_ascii_lowercase(),
        })
    }

    /// # Errors
    ///
    /// Returns the `std::io::Error` of opening or reading `path`.
    pub fn of_file(algo: HashAlgo, path: &Path) -> std::io::Result<Self> {
        let mut file = File::open(path)?;
        let mut buffer = vec![0u8; READ_CHUNK];
        let hex = match algo {
            HashAlgo::Sha256 => {
                let mut hasher = Sha256::new();
                read_chunks(&mut file, &mut buffer, |chunk| hasher.update(chunk))?;
                to_hex(hasher.finalize().iter())
            }
            HashAlgo::Sha384 => {
                let mut hasher = Sha384::new();
                read_chunks(&mut file, &mut buffer, |chunk| hasher.update(chunk))?;
                to_hex(hasher.finalize().iter())
            }
            HashAlgo::Xxh3_128 => {
                let mut hasher = Xxh3::new();
                read_chunks(&mut file, &mut buffer, |chunk| hasher.update(chunk))?;
                format!("{:032x}", hasher.digest128())
            }
        };
        Ok(Self { algo, hex })
    }
}

fn to_hex<'a>(bytes: impl Iterator<Item = &'a u8>) -> String {
    bytes.fold(String::new(), |mut hex, &byte| {
        for nibble in [byte >> 4, byte & 0x0f] {
            hex.extend(char::from_digit(u32::from(nibble), HEX_RADIX));
        }
        hex
    })
}

fn read_chunks<R>(
    file: &mut File,
    buffer: &mut [u8],
    mut consume: impl FnMut(&[u8]) -> R,
) -> std::io::Result<()> {
    loop {
        let read = file.read(buffer)?;
        if read == 0 {
            return Ok(());
        }
        if let Some(chunk) = buffer.get(..read) {
            consume(chunk);
        }
    }
}

