/// Base directory of a `Location`.
/// `App` is the directory of the editor executable, `Data` is `<App>/data`,
/// `Tmp` is the working directory of one installation.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum Root {
    Tmp,
    App,
    Data,
}

/// `rel` uses `/` and has no `.` or `..` component. It is empty for the root itself.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Location {
    pub root: Root,
    pub rel: String,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub enum Step {
    /// Extracts the downloaded zip into `Root::Tmp`.
    Extract,
    /// Extracts the downloaded 7z self-extracting executable into `Root::Tmp`.
    /// The 7z data starts at the first 7z signature of the executable.
    ExtractSfx,
    /// Runs the setup program `auo_setup2.exe` at `path` and waits until it exits.
    /// The exit code is ignored. The step fails after `AUO_SETUP_TIMEOUT_SECS` seconds.
    RunAuoSetup { path: Location },
    /// Copies a file into the directory `to`, or the content of a directory into `to`.
    Copy { from: Location, to: Location },
    /// Deletes the file or directory at `path` if it exists.
    Delete { path: Location },
    /// Runs the program at `path` with `args`, optionally elevated.
    /// Waits until the program exits. Fails when the exit status is non-zero.
    Run {
        path: Location,
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        args: Vec<String>,
        #[serde(default, skip_serializing_if = "std::ops::Not::not")]
        elevate: bool,
    },
    /// Copies an extracted file or directory to `<App>/<name>`.
    /// The source is `<archive_dir>/<last component of name>` below `Root::Tmp`.
    /// Without `archive_dir`, or when that path is absent, the source is the unique
    /// entry whose path ends with `name`, then the unique entry with the same last component.
    Place {
        name: String,
        archive_dir: Option<String>,
        directory: bool,
    },
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct FileCheck {
    pub location: Location,
    pub hash: Hash,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub enum Origin {
    Direct(Url),
    GithubRelease {
        owner: String,
        repo: String,
        /// Regular expression for the asset name. Without it the single `.zip` asset is used.
        pattern: Option<String>,
    },
}

impl Origin {
    #[must_use]
    pub fn label(&self) -> String {
        match self {
            Self::Direct(url) => url.to_string(),
            Self::GithubRelease { owner, repo, .. } => format!("github:{owner}/{repo}"),
        }
    }
}

fn describe(location: &Location) -> String {
    let root = match location.root {
        Root::Tmp => "tmp",
        Root::App => "app",
        Root::Data => "data",
    };
    if location.rel.is_empty() {
        root.to_owned()
    } else {
        format!("{root}/{}", location.rel)
    }
}

/// Installation procedure that a catalog entry describes. The download URL is resolved from `origin`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Recipe {
    pub version: String,
    pub origin: Origin,
    /// Hash of the downloaded archive.
    pub hash: Option<Hash>,
    pub steps: Vec<Step>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub uninstall_steps: Vec<Step>,
    /// Hashes of the files that exist after the steps ran.
    pub checks: Vec<FileCheck>,
}

impl Recipe {
    /// One line per planned operation: the download, each step, and each hash check.
    #[must_use]
    pub fn outline(&self) -> Vec<String> {
        let mut lines = vec![format!("download {}", self.origin.label())];
        for step in &self.steps {
            lines.push(match step {
                Step::Extract => "extract zip -> tmp".to_owned(),
                Step::ExtractSfx => "extract 7z self-extractor -> tmp".to_owned(),
                Step::RunAuoSetup { path } => format!("run auo_setup2 {}", describe(path)),
                Step::Copy { from, to } => format!("copy {} -> {}", describe(from), describe(to)),
                Step::Delete { path } => format!("delete {}", describe(path)),
                Step::Run {
                    path,
                    args,
                    elevate,
                } => {
                    let mut text = format!("run {}", describe(path));
                    if !args.is_empty() {
                        text.push(' ');
                        text.push_str(&args.join(" "));
                    }
                    if *elevate {
                        text.push_str(" (elevated)");
                    }
                    text
                }
                Step::Place {
                    name,
                    archive_dir,
                    directory,
                } => format!(
                    "place {} {name}{}",
                    if *directory { "directory" } else { "file" },
                    archive_dir
                        .as_deref()
                        .map_or_default(|dir| format!(" (archive directory {dir})"))
                ),
            });
        }
        for check in &self.checks {
            lines.push(format!(
                "check {:?} {} = {}",
                check.hash.algo,
                describe(&check.location),
                check.hash.hex
            ));
        }
        for step in &self.uninstall_steps {
            let line = match step {
                Step::Delete { path } => format!("uninstall delete {}", describe(path)),
                Step::Run {
                    path,
                    args,
                    elevate,
                } => {
                    let mut text = format!("uninstall run {}", describe(path));
                    if !args.is_empty() {
                        text.push(' ');
                        text.push_str(&args.join(" "));
                    }
                    if *elevate {
                        text.push_str(" (elevated)");
                    }
                    text
                }
                _ => "uninstall".to_owned(),
            };
            lines.push(line);
        }
        lines
    }
}

