}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum InstallPlan {
    Download(Vec<Artifact>),
    Staged(StagedPlan),
    OpenInBrowser(Url),
}

impl InstallPlan {
    /// `false` when the installation writes files that no hash covers.
    #[must_use]
    pub fn is_verified(&self) -> bool {
        match self {
            Self::Download(artifacts) => artifacts.iter().all(|artifact| artifact.hash.is_some()),
            Self::Staged(plan) => plan.artifact.hash.is_some() || !plan.checks.is_empty(),
            Self::OpenInBrowser(_) => true,
        }
    }
}

const COMMONS_WORKS_URL: &str = "https://commons.nicovideo.jp/works/";

/// Work page of a niconi commons ID: `nc` followed by one or more ASCII digits.
/// Surrounding whitespace is ignored. Any other text returns `None`.
#[must_use]
pub fn commons_url(commons_id: &str) -> Option<Url> {
    let id = commons_id.trim();
    let digits = id.strip_prefix("nc")?;
    if digits.is_empty() || !digits.bytes().all(|byte| byte.is_ascii_digit()) {
        return None;
    }
    Url::parse(&format!("{COMMONS_WORKS_URL}{id}")).ok()
}

use std::fs;
use std::io::ErrorKind;
use std::net::IpAddr;
use std::path::Path;

use serde::{Deserialize, Serialize};

use crate::Error;

const CONFIG_FILE: &str = "config.toml";
const TEMP_EXTENSION: &str = "toml.tmp";

#[derive(Debug, Default, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Config {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub github_token: Option<String>,
    /// Name of an `iced::Theme`, as printed by its `Display` implementation.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub theme: Option<String>,
    /// Family name of the UI font. `None` selects the iced default.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub font: Option<String>,
    /// Selected locale code (e.g. "ja", "en", "ko", "zh-CN", "zh-TW").
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub locale: Option<String>,
    /// DNS servers of the launcher requests. Empty selects the built-in default.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub dns: Vec<IpAddr>,
    /// The dialog of installed deprecated packages stays closed after the user chose so.
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub hide_deprecated_notice: bool,
}

impl Config {
    /// Returns the default value when `<root>/config.toml` does not exist.
    ///
    /// # Errors
    ///
    /// Returns `Error::Io` when the file exists and cannot be read,
    /// and `Error::Parse` when its content is not a valid `Config`.
    pub fn load(root: &Path) -> Result<Self, Error> {
        let path = root.join(CONFIG_FILE);
        let text = match fs::read_to_string(&path) {
            Ok(text) => text,
            Err(e) if e.kind() == ErrorKind::NotFound => return Ok(Self::default()),
            Err(e) => return Err(Error::io(&path, e)),
        };
        toml::from_str(&text).map_err(|source| Error::Parse { path, source })
    }

    /// Writes `<root>/config.toml` through a temporary file.
    ///
    /// # Errors
    ///
    /// Returns `Error::Serialize` when the value cannot be encoded,
    /// and `Error::Io` when the directory, the temporary file, or the rename fails.
    pub fn save(&self, root: &Path) -> Result<(), Error> {
        let text = toml::to_string_pretty(self)?;
        fs::create_dir_all(root).map_err(|e| Error::io(root, e))?;
        let path = root.join(CONFIG_FILE);
        let temp = path.with_extension(TEMP_EXTENSION);
        fs::write(&temp, text).map_err(|e| Error::io(&temp, e))?;
        fs::rename(&temp, &path).map_err(|e| Error::io(&path, e))
    }
}

use std::future::Future;
use std::path::Path;

use url::Url;

use crate::Error;

/// Hosts that `https` downloads may use.
pub const ALLOWED_HOSTS: [&str; 11] = [
    "github.com",
    "api.github.com",
    "codeberg.org",
    "objects.githubusercontent.com",
    "release-assets.githubusercontent.com",
    "spring-fragrance.mints.ne.jp",
    "drive.google.com",
    "drive.usercontent.google.com",
    "docs.google.com",
    "rigaya3458.github.io",
    "booth.pm",
];

/// Hosts that `http` downloads may use. The installer requires a hash for such a download.
pub const HTTP_HOSTS: [&str; 1] = ["spring-fragrance.mints.ne.jp"];

/// Accepts `https` URLs whose host is listed in `ALLOWED_HOSTS`
/// and `http` URLs whose host is listed in `HTTP_HOSTS`.
#[must_use]
pub fn is_allowed_url(url: &Url) -> bool {
    let Some(host) = url.host_str() else {
        return false;
    };
    match url.scheme() {
        "https" => ALLOWED_HOSTS.contains(&host),
        "http" => HTTP_HOSTS.contains(&host),
        _ => false,
    }
}

/// Bytes received so far. `total` is `None` when the server does not report a length.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Progress {
    pub done: u64,
    pub total: Option<u64>,
}

pub trait ProgressSink: Send + Sync {
    fn report(&self, progress: Progress);
}

#[derive(Debug, Clone, Copy, Default)]
pub struct NoProgress;

impl ProgressSink for NoProgress {
    fn report(&self, _progress: Progress) {}
}

/// Writes the body of `url` to `dest` and reports progress after the response header and after
/// every received chunk. Implementations apply `is_allowed_url` to every redirect target.
pub trait Fetcher: Send + Sync {
    fn fetch(
        &self,
        url: &Url,
        dest: &Path,
        progress: &dyn ProgressSink,
    ) -> impl Future<Output = Result<(), Error>> + Send;
}

//! Detection of catalog packages whose files exist in an instance without an installer record.

use std::collections::HashSet;
use std::fs;
use std::hash::BuildHasher;
use std::path::{Path, PathBuf};
use std::thread;

use crate::catalog::{AppVersion, FileCheck, Hash, HashAlgo, Root};
use crate::runner::find_executable;
use crate::stage::DATA_DIR;
use crate::{Host, Kind};

/// Directories under the app directory and under its `data` directory
/// that hold manually placed plugins and scripts.
pub const SCAN_DIRS: [&str; 4] = ["Plugin", "Plugins", "Script", "Scripts"];

const MAX_THREADS: usize = 8;

/// XXH3-128 values of every file under `SCAN_DIRS` of `app_dir` and of `app_dir/data`,
/// subdirectories included.
/// Each value has 32 lowercase hexadecimal digits. Unreadable files are skipped.
#[must_use]
pub fn scan_xxh3_128(app_dir: &Path) -> HashSet<String> {
    let mut files = Vec::new();
    for base in [app_dir.to_path_buf(), app_dir.join(DATA_DIR)] {
        for sub in SCAN_DIRS {
            collect_files(&base.join(sub), &mut files);
        }
    }
    if files.is_empty() {
        return HashSet::new();
    }
    let threads = thread::available_parallelism()
        .map_or(1, usize::from)
        .min(MAX_THREADS)
        .min(files.len());
    let chunk = files.len().div_ceil(threads);
    thread::scope(|scope| {
        #[expect(
            clippy::needless_collect,
            reason = "every thread must start before the first join"
        )]
        let workers: Vec<_> = files
            .chunks(chunk)
            .map(|paths| {
                scope.spawn(move || {
                    paths
                        .iter()
                        .filter_map(|path| Hash::of_file(HashAlgo::Xxh3_128, path).ok())
                        .map(|hash| hash.hex)
                        .collect::<Vec<_>>()
                })
            })
            .collect();
        workers
            .into_iter()
            .flat_map(|worker| worker.join().unwrap_or_default())
            .collect()
    })
}

/// Holds when `checks` is not empty and every check holds.
///
/// A check holds when the file at its path has the recorded hash,
/// or, for XXH3-128, when a scanned file at another path has that hash.
/// `app_dir` is the directory of the executable. `Root::Tmp` checks do not hold.
#[must_use]
pub fn is_present<S: BuildHasher>(
    app_dir: &Path,
    checks: &[FileCheck],
    scanned: &HashSet<String, S>,
) -> bool {
    !checks.is_empty() && checks.iter().all(|check| holds(app_dir, check, scanned))
}

/// Version of `versions` whose recorded files all match the install at `app_dir`.
///
/// `versions` holds the newest first. Versions can share the same files, so the oldest match
/// is returned: a wrong label then offers an update instead of hiding one.
/// `None` when `app_dir` holds no executable of `kind` or no version matches.
#[must_use]
pub fn detect_version<'a>(
    app_dir: &Path,
    kind: Kind,
    host: Host,
    versions: &'a [AppVersion],
) -> Option<&'a AppVersion> {
    let exe = find_executable(app_dir, kind, host).ok()?;
    let exe_dir = exe.parent()?;
    let scanned = HashSet::new();
    versions
        .iter()
        .rev()
        .find(|version| is_present(exe_dir, &version.checks, &scanned))
}

/// Path of the file that `check` names, below `app_dir`, the directory of the executable.
/// `None` for `Root::Tmp`.
#[must_use]
pub fn check_path(app_dir: &Path, check: &FileCheck) -> Option<PathBuf> {
    let base = match check.location.root {
        Root::App => app_dir.to_path_buf(),
        Root::Data => app_dir.join(DATA_DIR),
        Root::Tmp => return None,
    };
    Some(
        check
            .location
            .rel
            .split('/')
            .fold(base, |path, part| path.join(part)),
    )
}

fn holds<S: BuildHasher>(app_dir: &Path, check: &FileCheck, scanned: &HashSet<String, S>) -> bool {
    let Some(path) = check_path(app_dir, check) else {
        return false;
    };
    let expected = check.hash.hex.to_ascii_lowercase();
    if Hash::of_file(check.hash.algo, &path).is_ok_and(|hash| hash.hex == expected) {
        return true;
    }
    check.hash.algo == HashAlgo::Xxh3_128 && scanned.contains(&expected)
}

/// Appends the regular files under `dir`. Symbolic links are not followed.
fn collect_files(dir: &Path, files: &mut Vec<PathBuf>) {
    let Ok(entries) = fs::read_dir(dir) else {
        return;
    };
    for entry in entries.flatten() {
        let Ok(kind) = entry.file_type() else {
            continue;
        };
        if kind.is_dir() {
            collect_files(&entry.path(), files);
        } else if kind.is_file() {
            files.push(entry.path());
        }
    }
}

use crate::Kind;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Host {
    Windows,
    Linux,
    MacOs,
}

impl Host {
    #[must_use]
    pub const fn current() -> Self {
        if cfg!(windows) {
            Self::Windows
        } else if cfg!(target_os = "macos") {
            Self::MacOs
        } else {
            Self::Linux
        }
    }
}

/// CPU architecture of the host. Only macOS ships builds for both.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Arch {
    X86_64,
    Aarch64,
}

impl Arch {
    #[must_use]
    pub const fn current() -> Self {
        if cfg!(target_arch = "aarch64") {
            Self::Aarch64
        } else {
            Self::X86_64
        }
    }
}

impl Kind {
    #[must_use]
    pub const fn supported_on(self, host: Host) -> bool {
        match host {
            Host::Windows => !matches!(self, Self::Macutl),
            Host::Linux => matches!(self, Self::Neoutl | Self::Freya),
            Host::MacOs => matches!(self, Self::Freya | Self::Macutl),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::{Host, Kind};

    #[test]
    fn macos_supports_freya_and_macutl_only() {
        for kind in [Kind::Aviutl, Kind::Aviutl2, Kind::Ymm4, Kind::Neoutl] {
            assert!(!kind.supported_on(Host::MacOs));
        }
        assert!(Kind::Freya.supported_on(Host::MacOs));
        assert!(Kind::Macutl.supported_on(Host::MacOs));
    }

    #[test]
    fn macutl_is_macos_only() {
        assert!(!Kind::Macutl.supported_on(Host::Windows));
        assert!(!Kind::Macutl.supported_on(Host::Linux));
    }
}

