impl InstanceConfig {
    /// `app_version`, followed by the addon version when there is one.
    #[must_use]
    pub fn version_label(&self) -> String {
        self.addon_version.as_ref().map_or_else(
            || self.app_version.clone(),
            |addon| format!("{} / {ADDON_LABEL} {addon}", self.app_version),
        )
    }

    /// Splits the combined `app_version` of earlier launcher versions into both fields.
    pub(crate) fn normalize(&mut self) {
        if self.addon_version.is_some() {
            return;
        }
        let split = self
            .app_version
            .split_once(LEGACY_ADDON_SEPARATOR)
            .map(|(app, addon)| (app.to_owned(), addon.to_owned()));
        if let Some((app, addon)) = split {
            self.app_version = app;
            self.addon_version = Some(addon);
        }
    }

    /// # Errors
    ///
    /// Returns `Error::EmptyName` for a blank name, `Error::InvalidEdition` for `Edition::Lite`
    /// on a kind other than `Kind::Ymm4`, `Error::InvalidBundle` for `Bundle::AppImage`
    /// on a kind other than `Kind::Freya`, `Error::EmptyPluginId` for a blank plugin id,
    /// and `Error::UnsafePath` for a plugin file path that leaves the app directory.
    pub fn validate(&self) -> Result<(), Error> {
        if self.name.trim().is_empty() {
            return Err(Error::EmptyName);
        }
        if self.edition == Edition::Lite && self.kind != Kind::Ymm4 {
            return Err(Error::InvalidEdition {
                kind: self.kind,
                edition: self.edition,
            });
        }
        if self.bundle == Bundle::AppImage && self.kind != Kind::Freya {
            return Err(Error::InvalidBundle {
                kind: self.kind,
                bundle: self.bundle,
            });
        }
        for plugin in &self.plugins {
            if plugin.id.trim().is_empty() {
                return Err(Error::EmptyPluginId);
            }
            for file in &plugin.files {
                ensure_relative_path(file)?;
            }
        }
        Ok(())
    }
}

