const SEARCH_DEPTH: usize = 2;
const POLL_INTERVAL: Duration = Duration::from_millis(100);

/// A process that exits with a failure status inside this window is reported as a failed launch.
pub const PROBE_WINDOW: Duration = Duration::from_secs(5);

impl Kind {
    /// File name under which a bare executable download is stored.
    pub(crate) const fn executable_name(self) -> &'static str {
        match self.executable_stems() {
            [first, ..] => first,
            [] => "",
        }
    }

    /// File stems accepted as the executable. Compared case-insensitively.
    const fn executable_stems(self) -> &'static [&'static str] {
        match self {
            Self::Aviutl => &["aviutl"],
            Self::Aviutl2 => &["aviutl2"],
            Self::Ymm4 => &["YukkuriMovieMaker"],
            Self::Neoutl => &["NeoUtl"],
            Self::Freya => &["freya-nle", "freya", "aviqtl"],
            Self::Macutl => &["MacUtl"],
        }
    }
}

fn is_executable_name(path: &Path, stems: &[&str], host: Host) -> bool {
    let Some(name) = path.file_name().and_then(|name| name.to_str()) else {
        return false;
    };
    let stem = match host {
        Host::Windows => {
            let named = Path::new(name);
            if !named
                .extension()
                .is_some_and(|extension| extension.eq_ignore_ascii_case("exe"))
            {
                return false;
            }
            named
                .file_stem()
                .and_then(|stem| stem.to_str())
                .unwrap_or_default()
        }
        Host::Linux | Host::MacOs => name,
    };
    stems
        .iter()
        .any(|candidate| candidate.eq_ignore_ascii_case(stem))
}

/// Executable of an application bundle: the file that `CFBundleExecutable` names,
/// else the file of `Contents/MacOS` that matches `stems`.
fn bundle_executable(bundle: &Path, stems: &[&str]) -> Option<PathBuf> {
    declared_executable(bundle)
        .filter(|exe| exe.is_file())
        .or_else(|| {
            fs::read_dir(executable_dir(bundle))
                .ok()?
                .filter_map(Result::ok)
                .map(|entry| entry.path())
                .filter(|path| path.is_file() && is_executable_name(path, stems, Host::MacOs))
                .min()
        })
}

/// Searches `app_dir` and its sub-directories down to depth 2, shallowest level first.
///
/// Within one level the smallest path wins.
/// On macOS an `.app` directory counts as one candidate, whose executable is a file of
/// `Contents/MacOS`. A bare executable is accepted as well.
///
/// # Errors
///
/// Returns `Error::Io` when a directory cannot be read,
/// and `Error::ExecutableNotFound` when no file name matches `kind`.
pub fn find_executable(app_dir: &Path, kind: Kind, host: Host) -> Result<PathBuf, Error> {
    let stems = kind.executable_stems();
    let mut level = vec![app_dir.to_owned()];
    for _ in 0..=SEARCH_DEPTH {
        let mut found = Vec::new();
        let mut next = Vec::new();
        for dir in &level {
            for entry in fs::read_dir(dir).map_err(|e| Error::io(dir, e))? {
                let entry = entry.map_err(|e| Error::io(dir, e))?;
                let path = entry.path();
                let file_type = entry.file_type().map_err(|e| Error::io(&path, e))?;
                if file_type.is_dir() {
                    if host == Host::MacOs && is_bundle_dir(&path) {
                        found.extend(bundle_executable(&path, stems));
                    } else {
                        next.push(path);
                    }
                } else if file_type.is_file() && is_executable_name(&path, stems, host) {
                    found.push(path);
                }
            }
        }
        if let Some(path) = found.into_iter().min() {
            debug!(exe = %path.display(), ?kind, "executable found");
            return Ok(path);
        }
        level = next;
    }
    warn!(dir = %app_dir.display(), ?kind, "executable not found");
    Err(Error::ExecutableNotFound {
        kind,
        dir: app_dir.to_owned(),
    })
}

/// A spawned editor process. stdout and stderr go to `<instance>/launch.log`.
#[derive(Debug)]
pub struct Launched {
    child: Child,
    exe: PathBuf,
    log: PathBuf,
}

impl Launched {
    /// # Errors
    ///
    /// Returns the errors of `find_executable`, and `Error::Io` when the executable bit,
    /// the log file, or the process start fails.
    pub fn spawn(instance: &Instance, host: Host) -> Result<Self, Error> {
        let exe = find_executable(&instance.app_dir(), instance.config.kind, host)?;
        if let Some(required) = bundle_root(&exe).and_then(unsupported_min_os) {
            return Err(Error::MinOsUnsupported { required });
        }
        #[cfg(unix)]
        ensure_executable(&exe)?;
        let log = instance.dir.join(LOG_FILE);
        let out = File::create(&log).map_err(|e| Error::io(&log, e))?;
        let err = out.try_clone().map_err(|e| Error::io(&log, e))?;
        let child = Command::new(&exe)
            .current_dir(exe.parent().unwrap_or(instance.dir.as_path()))
            .stdin(Stdio::null())
            .stdout(out)
            .stderr(err)
            .spawn()
            .map_err(|e| Error::io(&exe, e))?;
        info!(exe = %exe.display(), pid = child.id(), log = %log.display(), "process spawned");
        Ok(Self { child, exe, log })
    }

    /// Blocks up to `window`. Returns `LaunchFailed` with the log tail when the process
    /// exits with a failure status inside the window.
    ///
    /// # Errors
    ///
    /// Returns `Error::LaunchFailed` for a failure exit status inside `window`,
    /// and `Error::Io` when the process state cannot be read.
    pub fn confirm(self, window: Duration) -> Result<(), Error> {
        let Self {
            mut child,
            exe,
            log,
        } = self;
        let deadline = Instant::now() + window;
        loop {
            match child.try_wait().map_err(|e| Error::io(&exe, e))? {
                Some(status) if status.success() => {
                    info!(exe = %exe.display(), %status, "process exited with success");
                    return Ok(());
                }
                Some(status) => {
                    warn!(exe = %exe.display(), %status, "process exited with failure");
                    return Err(Error::LaunchFailed {
                        exe,
                        status: status.to_string(),
                        log: read_tail(&log),
                    });
                }
                None if Instant::now() >= deadline => {
                    info!(exe = %exe.display(), window_ms = window.as_millis(), "process still running");
                    reap(child);
                    return Ok(());
                }
                None => thread::sleep(POLL_INTERVAL),
            }
        }
    }
}

/// Adds the executable bits to a file that has none. The launcher has selected this file
/// as the executable of the instance, so the bits are set at launch.
#[cfg(unix)]
pub fn ensure_executable(path: &Path) -> Result<(), Error> {
    use std::os::unix::fs::PermissionsExt;

    let metadata = fs::metadata(path).map_err(|e| Error::io(path, e))?;
    let mut permissions = metadata.permissions();
    let mode = permissions.mode();
    if mode & 0o111 == 0 {
        permissions.set_mode(mode | 0o111);
        fs::set_permissions(path, permissions).map_err(|e| Error::io(path, e))?;
        info!(exe = %path.display(), "executable bit set");
    }
    Ok(())
}

/// Opens `dir` in the file manager of `host`.
///
/// # Errors
///
/// Returns `Error::Io` when the file manager cannot start.
pub fn open_directory(dir: &Path, host: Host) -> Result<(), Error> {
    debug!(dir = %dir.display(), "open directory");
    open_with_shell(dir.as_os_str(), host, dir)
}

/// Opens an `http` or `https` URL in the default browser of `host`.
///
/// # Errors
///
/// Returns `Error::UnsafePath` for another scheme, and `Error::Io` when the browser cannot start.
pub fn open_url(url: &Url, host: Host) -> Result<(), Error> {
    if !matches!(url.scheme(), "http" | "https") {
        return Err(Error::UnsafePath(url.to_string()));
    }
    debug!(%url, "open url");
    open_with_shell(OsStr::new(url.as_str()), host, Path::new(url.as_str()))
}

fn open_with_shell(target: &OsStr, host: Host, error_path: &Path) -> Result<(), Error> {
    let program = match host {
        Host::Windows => "explorer",
        Host::Linux => "xdg-open",
        Host::MacOs => "open",
    };
    let child = Command::new(program)
        .arg(target)
        .spawn()
        .map_err(|e| Error::io(error_path, e))?;
    reap(child);
    Ok(())
}

fn reap(mut child: Child) {
    thread::spawn(move || {
        let _ = child.wait();
    });
}

fn read_tail(path: &Path) -> String {
    let bytes = fs::read(path).unwrap_or_default();
    let start = bytes.len().saturating_sub(LOG_TAIL_BYTES);
    bytes.get(start..).map_or_else(String::new, |tail| {
        String::from_utf8_lossy(tail).trim().to_owned()
    })
}

/// Checks if an executable belonging to this instance is currently running.
#[must_use]
pub fn is_instance_running(instance: &Instance) -> bool {
    let Ok(mut system) = System::new_with_specifics(
        RefreshKind::nothing().with_processes(
            ProcessRefreshKind::nothing()
                .with_exe(sysinfo::UpdateKind::OnlyIfNotSet)
                .with_cwd(sysinfo::UpdateKind::OnlyIfNotSet),
        ),
    )
    .inspect_err(|error| tracing::warn!(%error, "process list is unavailable")) else {
        return false;
    };
    system.refresh_processes_specifics(
        sysinfo::ProcessesToUpdate::All,
        true,
        ProcessRefreshKind::nothing()
            .with_exe(sysinfo::UpdateKind::OnlyIfNotSet)
            .with_cwd(sysinfo::UpdateKind::OnlyIfNotSet),
    );

    let instance_dir = &instance.dir;
    let stems = instance.config.kind.executable_stems();

    for process in system.processes().values() {
        if process
            .exe()
            .is_some_and(|exe| exe.starts_with(instance_dir))
        {
            return true;
        }
        let proc_name = process.name().to_string_lossy();
        let stem = proc_name.strip_suffix(".exe").unwrap_or(&proc_name);
        if stems.iter().any(|s| s.eq_ignore_ascii_case(stem))
            && process
                .cwd()
                .is_some_and(|cwd| cwd.starts_with(instance_dir))
        {
            return true;
        }
    }
    false
}

use std::path::Path;
use std::process::{Command, Stdio};

use tracing::{info, warn};

use crate::Error;

const VERIFY_ARGS: [&str; 3] = ["--verify", "--deep", "--strict"];
/// `-s -` selects the ad-hoc identity.
const AD_HOC_ARGS: [&str; 4] = ["--force", "--deep", "-s", "-"];

/// Leaves `bundle` with a valid code signature.
/// A bundle that fails verification gets an ad-hoc signature, because Apple Silicon
/// kills unsigned code. The quarantine attribute is not touched: files that the launcher
/// extracts itself do not carry it.
///
/// # Errors
///
/// Returns `Error::Io` when `codesign` cannot start and `Error::CodeSignFailed`
/// when the ad-hoc signature fails.
pub fn ensure_signed(bundle: &Path) -> Result<(), Error> {
    if run(&VERIFY_ARGS, bundle)? {
        info!(bundle = %bundle.display(), "signature valid");
        return Ok(());
    }
    warn!(bundle = %bundle.display(), "signature invalid, signing ad hoc");
    if run(&AD_HOC_ARGS, bundle)? {
        Ok(())
    } else {
        Err(Error::CodeSignFailed(bundle.to_owned()))
    }
}

fn run(args: &[&str], bundle: &Path) -> Result<bool, Error> {
    Command::new("codesign")
        .args(args)
        .arg(bundle)
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status()
        .map(|status| status.success())
        .map_err(|e| Error::io(bundle, e))
}

//! Orderings of catalog packages. Every key derives from catalog data:
//! `Package::dependencies` and `Package::release_dates`.

use std::collections::{HashMap, HashSet};

use time::{Date, Duration, OffsetDateTime};

use crate::Package;

/// A release within this many days up to `today` counts for the trend.
pub const TREND_DAYS: i64 = 90;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum SortOrder {
    /// Packages that most other catalog packages depend on come first.
    #[default]
    Popularity,
    /// Packages with the most releases in the last `TREND_DAYS` days come first.
    Trend,
    /// Packages with the newest first release come first.
    Newest,
    /// Packages with the newest latest release come first.
    Updated,
}

/// Current UTC date.
#[must_use]
pub fn today() -> Date {
    OffsetDateTime::now_utc().date()
}

/// Sorts `shown` in place. Packages without a key come last.
/// Ties fall back to the other key, then to the lowercase name, then to the id.
/// `catalog` is the full list in which popularity counts dependents.
pub fn sort_packages(shown: &mut [&Package], order: SortOrder, catalog: &[Package], today: Date) {
    let dependents = dependents(catalog);
    let popularity = |package: &Package| {
        dependents
            .get(package.id.as_str())
            .copied()
            .unwrap_or_default()
    };
    let window_end = iso(today);
    let window_start = iso(today
        .checked_sub(Duration::days(TREND_DAYS))
        .unwrap_or(Date::MIN));
    let trend = |package: &Package| {
        package
            .release_dates
            .iter()
            .filter(|date| {
                date.as_str() >= window_start.as_str() && date.as_str() <= window_end.as_str()
            })
            .count()
    };
    shown.sort_by(|a, b| {
        let primary = match order {
            SortOrder::Popularity => popularity(b)
                .cmp(&popularity(a))
                .then_with(|| trend(b).cmp(&trend(a))),
            SortOrder::Trend => trend(b)
                .cmp(&trend(a))
                .then_with(|| popularity(b).cmp(&popularity(a))),
            SortOrder::Newest => b.first_release().cmp(&a.first_release()),
            SortOrder::Updated => b.latest_release().cmp(&a.latest_release()),
        };
        primary
            .then_with(|| a.name.to_lowercase().cmp(&b.name.to_lowercase()))
            .then_with(|| a.id.cmp(&b.id))
    });
}

/// Number of catalog packages that list each id in `dependencies`.
fn dependents(catalog: &[Package]) -> HashMap<&str, usize> {
    let mut counts = HashMap::new();
    for package in catalog {
        let unique: HashSet<&str> = package.dependencies.iter().map(String::as_str).collect();
        for id in unique {
            *counts.entry(id).or_insert(0) += 1;
        }
    }
    counts
}

fn iso(date: Date) -> String {
    format!(
        "{:04}-{:02}-{:02}",
        date.year(),
        u8::from(date.month()),
        date.day()
    )
}

use std::fs;
use std::path::{Path, PathBuf};

use tracing::{debug, info};

use crate::archive::{Archive, Created, Layout, copy_file, copy_link, extract_sfx, make_dirs};
use crate::model::ensure_relative_path;
use crate::{
    AUO_SETUP_TIMEOUT_SECS, Error, FileCheck, Hash, Kind, Location, Root, Step, find_executable,
};

pub const DATA_DIR: &str = "data";

/// Directories that `Location` values resolve against.
pub struct Roots {
    tmp: Option<PathBuf>,
    pub(crate) app: PathBuf,
    pub(crate) data: PathBuf,
}

impl Roots {
    /// `App` is the directory of the executable below `app_dir`.
    /// Only `AviUtl` and `AviUtl2` have catalogs that address files by location.
    pub(crate) fn locate(kind: Kind, app_dir: &Path, tmp: Option<&Path>) -> Result<Self, Error> {
        if !matches!(kind, Kind::Aviutl | Kind::Aviutl2) {
            return Err(Error::PluginUnsupported(kind));
        }
        let exe = find_executable(app_dir, kind, crate::Host::Windows)?;
        let app = exe.parent().unwrap_or(app_dir).to_owned();
        Ok(Self {
            tmp: tmp.map(Path::to_owned),
            data: app.join(DATA_DIR),
            app,
        })
    }

    fn resolve(&self, location: &Location) -> Result<PathBuf, Error> {
        let base = match location.root {
            Root::Tmp => self
                .tmp
                .as_ref()
                .ok_or_else(|| Error::UnsafePath(location.rel.clone()))?,
            Root::App => &self.app,
            Root::Data => &self.data,
        };
        if location.rel.is_empty() {
            return Ok(base.clone());
        }
        ensure_relative_path(&location.rel)?;
        Ok(base.join(location.rel.replace('\\', "/")))
    }
}

/// Runs `steps` in order. `download` is the downloaded archive.
/// Every file and directory that a step creates is recorded in `created`.
pub fn run(
    roots: &Roots,
    download: &Path,
    steps: &[Step],
    created: &mut Created,
) -> Result<(), Error> {
    for step in steps {
        debug!(?step, "step");
        match step {
            Step::Extract => {
                let tmp = roots.resolve(&Location {
                    root: Root::Tmp,
                    rel: String::new(),
                })?;
                Archive::open(download, Layout::Tree)?.extract(&tmp)?;
            }
            Step::ExtractSfx => {
                let tmp = roots.resolve(&Location {
                    root: Root::Tmp,
                    rel: String::new(),
                })?;
                extract_sfx(download, &tmp)?;
            }
            Step::RunAuoSetup { path } => {
                let exe = roots.resolve(path)?;
                let before = snapshot_files(&roots.app);
                let result = run_auo_setup(&exe);
                // Files the setup program wrote belong to the task, even when it failed.
                let mut added: Vec<PathBuf> = snapshot_files(&roots.app)
                    .into_iter()
                    .filter(|file| !before.contains(file))
                    .collect();
                added.sort();
                created.files.extend(added);
                result?;
            }
            Step::Run {
                path,
                args,
                elevate,
            } => {
                let exe = roots.resolve(path)?;
                let before = snapshot_files(&roots.app);
                let result = run_program(&exe, args, *elevate);
                let mut added: Vec<PathBuf> = snapshot_files(&roots.app)
                    .into_iter()
                    .filter(|file| !before.contains(file))
                    .collect();
                added.sort();
                created.files.extend(added);
                result?;
            }
            Step::Delete { path } => {
                let target = roots.resolve(path)?;
                delete_path(&target)?;
            }
            Step::Copy { from, to } => {
                copy(&roots.resolve(from)?, &roots.resolve(to)?, created)?;
            }
            Step::Place {
                name,
                archive_dir,
                directory,
            } => place(
                roots,
                download,
                name,
                archive_dir.as_deref(),
                *directory,
                created,
            )?,
        }
    }
    Ok(())
}

/// Compares the hash of every file in `checks` with the file on disk.
pub fn verify(roots: &Roots, checks: &[FileCheck]) -> Result<(), Error> {
    for check in checks {
        let path = roots.resolve(&check.location)?;
        let actual = Hash::of_file(check.hash.algo, &path).map_err(|e| Error::io(&path, e))?;
        if !actual.hex.eq_ignore_ascii_case(&check.hash.hex) {
            return Err(Error::HashMismatch {
                name: check.location.rel.clone(),
                expected: check.hash.hex.clone(),
                actual: actual.hex,
            });
        }
        debug!(file = %check.location.rel, "file hash verified");
    }
    Ok(())
}

/// Copies a file into the directory `to_dir`. Copies the content of a directory into `to_dir`.
fn copy(from: &Path, to_dir: &Path, created: &mut Created) -> Result<(), Error> {
    let metadata = fs::symlink_metadata(from).map_err(|e| Error::io(from, e))?;
    if metadata.is_dir() {
        return copy_tree(from, to_dir, created);
    }
    let name = from
        .file_name()
        .ok_or_else(|| Error::UnsafePath(from.display().to_string()))?;
    copy_file(from, &to_dir.join(name), created)
}

fn copy_tree(from: &Path, to: &Path, created: &mut Created) -> Result<(), Error> {
    make_dirs(to, created)?;
    let mut children = Vec::new();
    for entry in fs::read_dir(from).map_err(|e| Error::io(from, e))? {
        children.push(entry.map_err(|e| Error::io(from, e))?.path());
    }
    children.sort();
    for child in children {
        let Some(name) = child.file_name() else {
            continue;
        };
        let target = to.join(name);
        let file_type = fs::symlink_metadata(&child)
            .map_err(|e| Error::io(&child, e))?
            .file_type();
        if file_type.is_dir() {
            copy_tree(&child, &target, created)?;
        } else if file_type.is_file() {
            copy_file(&child, &target, created)?;
        } else if file_type.is_symlink() {
            copy_link(&child, &target, created)?;
        }
    }
    Ok(())
}

fn place(
    roots: &Roots,
    download: &Path,
    name: &str,
    archive_dir: Option<&str>,
    directory: bool,
    created: &mut Created,
) -> Result<(), Error> {
    let tmp = roots.resolve(&Location {
        root: Root::Tmp,
        rel: String::new(),
    })?;
    let source = find_source(&tmp, download, name, archive_dir, directory)?;
    let target = roots.resolve(&Location {
        root: Root::App,
        rel: name.to_owned(),
    })?;
    debug!(source = %source.display(), target = %target.display(), "place");
    if directory {
        copy_tree(&source, &target, created)
    } else {
        copy_file(&source, &target, created)
    }
}

/// Paths below `dir` relative to `dir`, written with `/`. `skip` is left out.
fn list(dir: &Path, skip: &Path) -> Result<Vec<(String, bool)>, Error> {
    let mut found = Vec::new();
    collect(dir, dir, skip, &mut found)?;
    Ok(found)
}

fn collect(
    base: &Path,
    dir: &Path,
    skip: &Path,
    found: &mut Vec<(String, bool)>,
) -> Result<(), Error> {
    for entry in fs::read_dir(dir).map_err(|e| Error::io(dir, e))? {
        let path = entry.map_err(|e| Error::io(dir, e))?.path();
        if path == skip {
            continue;
        }
        let file_type = fs::symlink_metadata(&path)
            .map_err(|e| Error::io(&path, e))?
            .file_type();
        let Ok(rel) = path.strip_prefix(base) else {
            continue;
        };
        let rel = rel
            .components()
            .map(|component| component.as_os_str().to_string_lossy().into_owned())
            .collect::<Vec<_>>()
            .join("/");
        if file_type.is_dir() {
            found.push((rel, true));
            collect(base, &path, skip, found)?;
        } else if file_type.is_file() {
            found.push((rel, false));
        }
    }
    Ok(())
}

fn find_source(
    tmp: &Path,
    download: &Path,
    name: &str,
    archive_dir: Option<&str>,
    directory: bool,
) -> Result<PathBuf, Error> {
    let candidates: Vec<String> = list(tmp, download)?
        .into_iter()
        .filter(|(_, is_dir)| *is_dir == directory)
        .map(|(rel, _)| rel)
        .collect();
    let name = name.replace('\\', "/").trim_matches('/').to_owned();
    let base = name.rsplit('/').next().unwrap_or(&name).to_owned();
    let exact = match archive_dir.map(|dir| dir.replace('\\', "/")) {
        Some(dir) if !dir.trim_matches('/').is_empty() => {
            format!("{}/{base}", dir.trim_matches('/'))
        }
        Some(_) => base.clone(),
        None => name.clone(),
    };

    let unique = |matches: Vec<&String>| -> Result<Option<PathBuf>, Error> {
        match matches.as_slice() {
            [] => Ok(None),
            [only] => Ok(Some(tmp.join(only.as_str()))),
            _ => Err(Error::EntryAmbiguous(name.clone())),
        }
    };
    let same = |candidate: &String, wanted: &str| candidate.eq_ignore_ascii_case(wanted);
    let ends_with = |candidate: &String, wanted: &str| {
        let candidate = candidate.to_ascii_lowercase();
        let wanted = format!("/{}", wanted.to_ascii_lowercase());
        candidate.ends_with(&wanted)
    };

    if let Some(path) = unique(candidates.iter().filter(|c| same(c, &exact)).collect())? {
        return Ok(path);
    }
    if let Some(path) = unique(
        candidates
            .iter()
            .filter(|c| same(c, &name) || ends_with(c, &name))
            .collect(),
    )? {
        return Ok(path);
    }
    unique(
        candidates
            .iter()
            .filter(|c| same(c, &base) || ends_with(c, &base))
            .collect(),
    )?
    .ok_or_else(|| Error::EntryNotFound(name.clone()))
}

/// Starts `exe` in its own directory and waits until it exits. The exit code is ignored.
fn run_auo_setup(exe: &Path) -> Result<(), Error> {
    let mut command = std::process::Command::new(exe);
    if let Some(dir) = exe.parent() {
        command.current_dir(dir);
    }
    let mut child = command.spawn().map_err(|source| Error::io(exe, source))?;
    let started = std::time::Instant::now();
    let timeout = std::time::Duration::from_secs(AUO_SETUP_TIMEOUT_SECS);
    loop {
        if let Some(status) = child.try_wait().map_err(|source| Error::io(exe, source))? {
            info!(exe = %exe.display(), %status, "auo setup finished");
            return Ok(());
        }
        if started.elapsed() >= timeout {
            let _ = child.kill();
            return Err(Error::LaunchFailed {
                exe: exe.to_owned(),
                status: format!("no exit within {AUO_SETUP_TIMEOUT_SECS} seconds"),
                log: String::new(),
            });
        }
        std::thread::sleep(std::time::Duration::from_millis(200));
    }
}

/// Lists every file below `dir`. Unreadable directories are skipped.
fn snapshot_files(dir: &Path) -> std::collections::HashSet<PathBuf> {
    let mut files = std::collections::HashSet::new();
    let mut pending = vec![dir.to_owned()];
    while let Some(current) = pending.pop() {
        let Ok(entries) = fs::read_dir(&current) else {
            continue;
        };
        for entry in entries.flatten() {
            let path = entry.path();
            match entry.file_type() {
                Ok(kind) if kind.is_dir() => pending.push(path),
                Ok(kind) if kind.is_file() => {
                    files.insert(path);
                }
                _ => {}
            }
        }
    }
    files
}

/// Runs uninstall `steps` in order.
pub fn run_uninstall(roots: &Roots, steps: &[Step]) -> Result<(), Error> {
    for step in steps {
        debug!(?step, "uninstall step");
        match step {
            Step::Delete { path } => {
                let target = roots.resolve(path)?;
                delete_path(&target)?;
            }
            Step::Run {
                path,
                args,
                elevate,
            } => {
                let exe = roots.resolve(path)?;
                run_program(&exe, args, *elevate)?;
            }
            Step::RunAuoSetup { path } => {
                let exe = roots.resolve(path)?;
                run_auo_setup(&exe)?;
            }
            _ => {}
        }
    }
    Ok(())
}

/// Deletes a file or directory tree at `path` if it exists.
pub fn delete_path(path: &Path) -> Result<(), Error> {
    let Ok(metadata) = fs::symlink_metadata(path) else {
        return Ok(());
    };
    if metadata.is_dir() {
        fs::remove_dir_all(path).map_err(|e| Error::io(path, e))?;
    } else {
        fs::remove_file(path).map_err(|e| Error::io(path, e))?;
    }
    Ok(())
}

fn run_program(exe: &Path, args: &[String], elevate: bool) -> Result<(), Error> {
    if !exe.is_file() {
        return Err(Error::io(
            exe,
            std::io::Error::new(std::io::ErrorKind::NotFound, "executable not found"),
        ));
    }
    #[cfg(unix)]
    crate::runner::ensure_executable(exe)?;

    let mut command = if elevate && cfg!(windows) {
        let mut cmd = std::process::Command::new("powershell.exe");
        let arg_list = args
            .iter()
            .map(|a| format!("'{}'", a.replace('\'', "''")))
            .collect::<Vec<_>>()
            .join(", ");
        let script = if arg_list.is_empty() {
            format!(
                "$p = Start-Process -FilePath '{}' -Verb RunAs -Wait -PassThru; exit $p.ExitCode",
                exe.display()
            )
        } else {
            format!(
                "$p = Start-Process -FilePath '{}' -ArgumentList @({arg_list}) -Verb RunAs -Wait -PassThru; exit $p.ExitCode",
                exe.display()
            )
        };
        cmd.args(["-NoProfile", "-NonInteractive", "-Command", &script]);
        cmd
    } else {
        let mut cmd = std::process::Command::new(exe);
        cmd.args(args);
        cmd
    };
    if let Some(dir) = exe.parent() {
        command.current_dir(dir);
    }
    let status = command.status().map_err(|source| Error::io(exe, source))?;
    if !status.success() {
        return Err(Error::LaunchFailed {
            exe: exe.to_owned(),
            status: status.to_string(),
            log: String::new(),
        });
    }
    Ok(())
}

use std::fs;
use std::path::{Path, PathBuf};

use time::OffsetDateTime;
use tracing::info;

use crate::{
    Error, Host, Instance, InstanceConfig, InstanceId, NewInstance, PluginRecord, find_executable,
};

const INSTANCES_DIR: &str = "instances";
const TEMP_SUFFIX: &str = ".tmp";

#[derive(Debug)]
pub struct ListFailure {
    pub dir: PathBuf,
    pub error: Error,
}

#[derive(Debug, Default)]
pub struct Listing {
    pub instances: Vec<Instance>,
    pub failures: Vec<ListFailure>,
}

#[derive(Debug, Clone)]
pub struct InstanceStore {
    instances_dir: PathBuf,
}

impl InstanceStore {
    pub fn new(root: impl AsRef<Path>) -> Self {
        Self {
            instances_dir: root.as_ref().join(INSTANCES_DIR),
        }
    }

    /// # Errors
    ///
    /// Returns `Error::UnsupportedKind` when `host` cannot run `new.kind`, the errors of
    /// `InstanceConfig::validate`, and `Error::Io` or `Error::Serialize` when the instance
    /// directory or `instance.toml` cannot be written.
    pub fn create(&self, new: NewInstance, host: Host) -> Result<Instance, Error> {
        if !new.kind.supported_on(host) {
            return Err(Error::UnsupportedKind {
                kind: new.kind,
                host,
            });
        }
        let config = InstanceConfig {
            id: InstanceId::generate(),
            name: new.name,
            kind: new.kind,
            edition: new.edition,
            bundle: new.bundle,
            app_version: new.app_version,
            addon_version: None,
            group: new.group,
            created_at: OffsetDateTime::now_utc(),
            plugins: Vec::new(),
        };
        config.validate()?;
        let instance = Instance {
            dir: self.dir_of(config.id),
            config,
        };
        let app_dir = instance.app_dir();
        fs::create_dir_all(&app_dir).map_err(|e| Error::io(&app_dir, e))?;
        if let Err(error) = self.save(&instance) {
            let _ = fs::remove_dir_all(&instance.dir);
            return Err(error);
        }
        info!(
            id = %instance.config.id,
            kind = ?instance.config.kind,
            dir = %instance.dir.display(),
            "instance created"
        );
        Ok(instance)
    }

    /// Copies the install at `source` into the app directory of a new instance.
    /// The source stays unchanged. Symbolic links are kept on unix. `launch.log` is left out.
    ///
    /// # Errors
    ///
    /// Returns `Error::OverlappingSource` when `source` contains or lies inside the instances
    /// directory, `Error::ExecutableNotFound` when `source` holds no executable of `new.kind`,
    /// the errors of `create`, and `Error::Io` when the copy fails.
    /// The new directory is removed on failure.
    pub fn import(&self, new: NewInstance, source: &Path, host: Host) -> Result<Instance, Error> {
        self.ensure_disjoint(source)?;
        find_executable(source, new.kind, host)?;
        let instance = self.create(new, host)?;
        if let Err(error) = copy_dir(source, &instance.app_dir()) {
            let _ = fs::remove_dir_all(&instance.dir);
            return Err(error);
        }
        info!(
            id = %instance.config.id,
            source = %source.display(),
            dir = %instance.dir.display(),
            "instance imported"
        );
        Ok(instance)
    }

    /// # Errors
    ///
    /// Returns `Error::Io` when a directory cannot be created or resolved,
    /// and `Error::OverlappingSource` when one directory contains the other.
    fn ensure_disjoint(&self, source: &Path) -> Result<(), Error> {
        fs::create_dir_all(&self.instances_dir).map_err(|e| Error::io(&self.instances_dir, e))?;
        let instances = self
            .instances_dir
            .canonicalize()
            .map_err(|e| Error::io(&self.instances_dir, e))?;
        let resolved = source.canonicalize().map_err(|e| Error::io(source, e))?;
        if instances.starts_with(&resolved) || resolved.starts_with(&instances) {
            Err(Error::OverlappingSource(resolved))
        } else {
            Ok(())
        }
    }

    /// # Errors
    ///
    /// Returns `Error::NotFound` when the instance directory does not exist,
    /// `Error::Io` or `Error::Parse` when `instance.toml` cannot be read,
    /// `Error::IdMismatch` when its id differs from the directory name,
    /// and the errors of `InstanceConfig::validate`.
    pub fn load(&self, id: InstanceId) -> Result<Instance, Error> {
        let dir = self.dir_of(id);
        if !dir.is_dir() {
            return Err(Error::NotFound(id));
        }
        Self::load_dir(dir, id)
    }

    /// # Errors
    ///
    /// Returns the errors of `InstanceConfig::validate`, `Error::Serialize`,
    /// and `Error::Io` when `instance.toml` cannot be written.
    pub fn save(&self, instance: &Instance) -> Result<(), Error> {
        instance.config.validate()?;
        let text = toml::to_string_pretty(&instance.config)?;
        let path = instance.config_path();
        let temp = path.with_extension(format!("toml{TEMP_SUFFIX}"));
        fs::write(&temp, text).map_err(|e| Error::io(&temp, e))?;
        fs::rename(&temp, &path).map_err(|e| Error::io(&path, e))
    }

    /// Changes the name and the group. The group is removed when `group` is `None`.
    ///
    /// # Errors
    ///
    /// Returns the errors of `load` and `save`.
    pub fn update(
        &self,
        id: InstanceId,
        name: String,
        group: Option<String>,
    ) -> Result<Instance, Error> {
        let mut instance = self.load(id)?;
        instance.config.name = name;
        instance.config.group = group;
        self.save(&instance)?;
        Ok(instance)
    }

    /// Writes the versions of the app and of the addon.
    ///
    /// # Errors
    ///
    /// Returns the errors of `load` and `save`.
    pub fn set_versions(
        &self,
        id: InstanceId,
        app_version: String,
        addon_version: Option<String>,
    ) -> Result<Instance, Error> {
        let mut instance = self.load(id)?;
        instance.config.app_version = app_version;
        instance.config.addon_version = addon_version;
        self.save(&instance)?;
        Ok(instance)
    }

    /// Sets the paused state of a plugin.
    ///
    /// # Errors
    ///
    /// Returns `Error::NotFound` when the plugin is not installed, and the errors of `load` and `save`.
    pub fn set_plugin_paused(
        &self,
        id: InstanceId,
        plugin_id: &str,
        paused: bool,
    ) -> Result<Instance, Error> {
        let mut instance = self.load(id)?;
        let Some(record) = instance
            .config
            .plugins
            .iter_mut()
            .find(|record| record.id == plugin_id)
        else {
            return Err(Error::NotFound(id));
        };
        record.paused = paused;
        self.save(&instance)?;
        Ok(instance)
    }

    /// Adds or updates a plugin record for the instance.
    ///
    /// # Errors
    ///
    /// Returns the errors of `load`, and `Error::Io` or `Error::Serialize`
    /// when `instance.toml` cannot be written.
    pub fn add_or_update_plugin(
        &self,
        id: InstanceId,
        record: PluginRecord,
    ) -> Result<Instance, Error> {
        let mut instance = self.load(id)?;
        if let Some(existing) = instance
            .config
            .plugins
            .iter_mut()
            .find(|p| p.id == record.id)
        {
            *existing = record;
        } else {
            instance.config.plugins.push(record);
        }
        self.save(&instance)?;
        Ok(instance)
    }

    /// Copies the instance directory, except the launch log, under a new id and name.
    ///
    /// # Errors
    ///
    /// Returns the errors of `load`, the errors of `InstanceConfig::validate`,
    /// and `Error::Io` or `Error::Serialize` when the copy or `instance.toml` fails.
    /// The new directory is removed on failure.
    pub fn duplicate(&self, id: InstanceId, name: String) -> Result<Instance, Error> {
        let source = self.load(id)?;
        let mut config = source.config.clone();
        config.id = InstanceId::generate();
        config.name = name;
        config.created_at = OffsetDateTime::now_utc();
        config.validate()?;
        let instance = Instance {
            dir: self.dir_of(config.id),
            config,
        };
        let copied = copy_dir(&source.dir, &instance.dir).and_then(|()| self.save(&instance));
        if let Err(error) = copied {
            let _ = fs::remove_dir_all(&instance.dir);
            return Err(error);
        }
        info!(
            from = %id,
            id = %instance.config.id,
            dir = %instance.dir.display(),
            "instance duplicated"
        );
        Ok(instance)
    }

    /// # Errors
    ///
    /// Returns `Error::NotFound` when the instance directory does not exist,
    /// and `Error::Io` when it cannot be removed.
    pub fn delete(&self, id: InstanceId) -> Result<(), Error> {
        let dir = self.dir_of(id);
        if !dir.is_dir() {
            return Err(Error::NotFound(id));
        }
        fs::remove_dir_all(&dir).map_err(|e| Error::io(&dir, e))?;
        info!(%id, dir = %dir.display(), "instance deleted");
        Ok(())
    }

    /// Instances that fail to load go to `Listing::failures`.
    ///
    /// # Errors
    ///
    /// Returns `Error::Io` when the instances directory exists and cannot be read.
    pub fn list(&self) -> Result<Listing, Error> {
        let mut listing = Listing::default();
        let entries = match fs::read_dir(&self.instances_dir) {
            Ok(entries) => entries,
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(listing),
            Err(e) => return Err(Error::io(&self.instances_dir, e)),
        };
        for entry in entries {
            let entry = entry.map_err(|e| Error::io(&self.instances_dir, e))?;
            let dir = entry.path();
            let Some(id) = dir
                .file_name()
                .and_then(|name| name.to_str())
                .and_then(|name| name.parse::<InstanceId>().ok())
            else {
                continue;
            };
            match Self::load_dir(dir.clone(), id) {
                Ok(instance) => listing.instances.push(instance),
                Err(error) => listing.failures.push(ListFailure { dir, error }),
            }
        }
        listing.instances.sort_by(|a, b| {
            (a.config.created_at, a.config.id.to_string())
                .cmp(&(b.config.created_at, b.config.id.to_string()))
        });
        Ok(listing)
    }

    fn dir_of(&self, id: InstanceId) -> PathBuf {
        self.instances_dir.join(id.to_string())
    }

    fn load_dir(dir: PathBuf, id: InstanceId) -> Result<Instance, Error> {
        let path = dir.join(Instance::CONFIG_FILE);
        let text = fs::read_to_string(&path).map_err(|e| Error::io(&path, e))?;
        let mut config: InstanceConfig = toml::from_str(&text).map_err(|source| Error::Parse {
            path: path.clone(),
            source,
        })?;
        config.normalize();
        if config.id != id {
            return Err(Error::IdMismatch {
                dir: id,
                file: config.id,
            });
        }
        config.validate()?;
        Ok(Instance { dir, config })
    }
}

const SKIPPED_ON_COPY: [&str; 2] = ["launch.log", "instance.toml.tmp"];

/// Copies files and directories. Symbolic links are kept on unix and left out elsewhere.
fn copy_dir(from: &Path, to: &Path) -> Result<(), Error> {
    fs::create_dir_all(to).map_err(|e| Error::io(to, e))?;
    for entry in fs::read_dir(from).map_err(|e| Error::io(from, e))? {
        let entry = entry.map_err(|e| Error::io(from, e))?;
        let name = entry.file_name();
        if name
            .to_str()
            .is_some_and(|name| SKIPPED_ON_COPY.contains(&name))
        {
            continue;
        }
        let source = entry.path();
        let target = to.join(&name);
        let file_type = entry.file_type().map_err(|e| Error::io(&source, e))?;
        if file_type.is_dir() {
            copy_dir(&source, &target)?;
        } else if file_type.is_file() {
            fs::copy(&source, &target).map_err(|e| Error::io(&target, e))?;
        } else if file_type.is_symlink() {
            copy_symlink(&source, &target)?;
        }
    }
    Ok(())
}

#[cfg(unix)]
fn copy_symlink(source: &Path, target: &Path) -> Result<(), Error> {
    let link = fs::read_link(source).map_err(|e| Error::io(source, e))?;
    std::os::unix::fs::symlink(link, target).map_err(|e| Error::io(target, e))
}

#[cfg(not(unix))]
fn copy_symlink(_source: &Path, _target: &Path) -> Result<(), Error> {
    Ok(())
}

use std::fs;
use std::path::{Path, PathBuf};

use crate::Error;
use crate::archive::{Created, copy_file, copy_link, make_dirs};

/// Content of one directory tree, as paths relative to its base.
#[derive(Default)]
struct Tree {
    dirs: Vec<PathBuf>,
    files: Vec<PathBuf>,
    links: Vec<PathBuf>,
}

impl Tree {
    fn collect(&mut self, base: &Path, rel: &Path) -> Result<(), Error> {
        let dir = base.join(rel);
        for entry in fs::read_dir(&dir).map_err(|e| Error::io(&dir, e))? {
            let entry = entry.map_err(|e| Error::io(&dir, e))?;
            let child = rel.join(entry.file_name());
            let file_type = entry.file_type().map_err(|e| Error::io(entry.path(), e))?;
            if file_type.is_dir() {
                self.dirs.push(child.clone());
                self.collect(base, &child)?;
            } else if file_type.is_file() {
                self.files.push(child);
            } else if file_type.is_symlink() {
                self.links.push(child);
            }
        }
        Ok(())
    }
}

/// Copy of a source tree over a destination tree.
/// A destination file that exists moves to the backup directory first.
/// `roll_back` removes the copied files and moves the backups back.
pub struct Swap {
    moved: Vec<(PathBuf, PathBuf)>,
    created: Created,
    /// Directories that `replace_dir` moved into place.
    placed: Vec<PathBuf>,
}

impl Swap {
    /// Copies every file below `source` to the same relative path below `dest`.
    /// A failure rolls back the copy before the error returns.
    pub(crate) fn apply(source: &Path, dest: &Path, backup: &Path) -> Result<Self, Error> {
        let mut tree = Tree::default();
        tree.collect(source, Path::new(""))?;
        let mut swap = Self {
            moved: Vec::new(),
            created: Created::default(),
            placed: Vec::new(),
        };
        match swap.write(&tree, source, dest, backup) {
            Ok(()) => Ok(swap),
            Err(error) => {
                swap.roll_back();
                Err(error)
            }
        }
    }

    /// Replaces the directory `dest` with the directory `source` as a whole.
    /// `dest` moves to `backup` first, then `source` moves to `dest`.
    /// Both moves are renames, so `source`, `dest`, and `backup` must share one volume.
    /// A failure rolls back before the error returns.
    pub(crate) fn replace_dir(source: &Path, dest: &Path, backup: &Path) -> Result<Self, Error> {
        let mut swap = Self {
            moved: Vec::new(),
            created: Created::default(),
            placed: Vec::new(),
        };
        match swap.move_dir(source, dest, backup) {
            Ok(()) => Ok(swap),
            Err(error) => {
                swap.roll_back();
                Err(error)
            }
        }
    }

    fn move_dir(&mut self, source: &Path, dest: &Path, backup: &Path) -> Result<(), Error> {
        if fs::symlink_metadata(dest).is_ok() {
            let name = dest
                .file_name()
                .ok_or_else(|| Error::UnsafePath(dest.display().to_string()))?;
            let saved = backup.join(name);
            fs::create_dir_all(backup).map_err(|e| Error::io(backup, e))?;
            fs::rename(dest, &saved).map_err(|e| Error::io(dest, e))?;
            self.moved.push((dest.to_owned(), saved));
        }
        if let Some(parent) = dest.parent() {
            fs::create_dir_all(parent).map_err(|e| Error::io(parent, e))?;
        }
        fs::rename(source, dest).map_err(|e| Error::io(dest, e))?;
        self.placed.push(dest.to_owned());
        Ok(())
    }

    pub(crate) fn roll_back(self) {
        self.created.roll_back();
        for dir in self.placed {
            let _ = fs::remove_dir_all(dir);
        }
        for (target, saved) in self.moved.into_iter().rev() {
            let _ = fs::rename(saved, target);
        }
    }

    fn write(
        &mut self,
        tree: &Tree,
        source: &Path,
        dest: &Path,
        backup: &Path,
    ) -> Result<(), Error> {
        for dir in &tree.dirs {
            make_dirs(&dest.join(dir), &mut self.created)?;
        }
        for rel in &tree.files {
            let target = dest.join(rel);
            self.back_up(&target, rel, backup)?;
            let from = source.join(rel);
            copy_file(&from, &target, &mut self.created)?;
            let permissions = fs::metadata(&from)
                .map_err(|e| Error::io(&from, e))?
                .permissions();
            fs::set_permissions(&target, permissions).map_err(|e| Error::io(&target, e))?;
        }
        for rel in &tree.links {
            let target = dest.join(rel);
            self.back_up(&target, rel, backup)?;
            copy_link(&source.join(rel), &target, &mut self.created)?;
        }
        Ok(())
    }

    /// Moves a file or link at `target` to `backup/<rel>`. A missing or directory `target` stays.
    fn back_up(&mut self, target: &Path, rel: &Path, backup: &Path) -> Result<(), Error> {
        if fs::symlink_metadata(target).is_ok_and(|metadata| !metadata.is_dir()) {
            let saved = backup.join(rel);
            if let Some(parent) = saved.parent() {
                fs::create_dir_all(parent).map_err(|e| Error::io(parent, e))?;
            }
            fs::rename(target, &saved).map_err(|e| Error::io(target, e))?;
            self.moved.push((target.to_owned(), saved));
        }
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use std::fs;

    use tempfile::tempdir;

    use super::Swap;

    fn bundle(path: &std::path::Path, marker: &str) {
        fs::create_dir_all(path.join("Contents")).unwrap();
        fs::write(path.join("Contents/marker"), marker).unwrap();
    }

    #[test]
    fn replace_dir_drops_files_of_the_old_directory() {
        let dir = tempdir().unwrap();
        let dest = dir.path().join("app/X.app");
        let source = dir.path().join("new/X.app");
        bundle(&dest, "old");
        fs::write(dest.join("Contents/stale"), "stale").unwrap();
        bundle(&source, "new");

        let swap = Swap::replace_dir(&source, &dest, &dir.path().join("old")).unwrap();

        assert_eq!(
            fs::read_to_string(dest.join("Contents/marker")).unwrap(),
            "new"
        );
        assert!(!dest.join("Contents/stale").exists());
        drop(swap);
    }

    #[test]
    fn roll_back_restores_the_old_directory() {
        let dir = tempdir().unwrap();
        let dest = dir.path().join("app/X.app");
        let source = dir.path().join("new/X.app");
        bundle(&dest, "old");
        bundle(&source, "new");

        Swap::replace_dir(&source, &dest, &dir.path().join("old"))
            .unwrap()
            .roll_back();

        assert_eq!(
            fs::read_to_string(dest.join("Contents/marker")).unwrap(),
            "old"
        );
    }

    #[test]
    fn a_missing_source_leaves_the_old_directory_in_place() {
        let dir = tempdir().unwrap();
        let dest = dir.path().join("app/X.app");
        bundle(&dest, "old");

        let result = Swap::replace_dir(&dir.path().join("none"), &dest, &dir.path().join("old"));

        assert!(result.is_err());
        assert_eq!(
            fs::read_to_string(dest.join("Contents/marker")).unwrap(),
            "old"
        );
    }

    #[cfg(unix)]
    #[test]
    fn apply_keeps_links_and_roll_back_restores_the_old_link() {
        use std::os::unix::fs::symlink;

        let dir = tempdir().unwrap();
        let source = dir.path().join("new");
        let dest = dir.path().join("app");
        fs::create_dir_all(&source).unwrap();
        fs::create_dir_all(&dest).unwrap();
        symlink("a.so.2", source.join("a.so")).unwrap();
        symlink("a.so.1", dest.join("a.so")).unwrap();

        let swap = Swap::apply(&source, &dest, &dir.path().join("old")).unwrap();
        assert_eq!(
            fs::read_link(dest.join("a.so")).unwrap().to_str(),
            Some("a.so.2")
        );

        swap.roll_back();
        assert_eq!(
            fs::read_link(dest.join("a.so")).unwrap().to_str(),
            Some("a.so.1")
        );
    }
}

use std::fmt::Display;
use std::sync::{Arc, Mutex, MutexGuard, PoisonError};

use tracing::debug;

use crate::{Progress, ProgressSink};

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct TaskId(u64);

/// `Running` counts steps of one task: `done` of `total`.
/// `transfer` is the byte progress of the download in the current step.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum TaskState {
    Queued,
    Running {
        done: u16,
        total: u16,
        transfer: Option<Progress>,
    },
    Succeeded,
    Failed {
        reason: String,
    },
}

impl TaskState {
    #[must_use]
    pub const fn is_active(&self) -> bool {
        matches!(self, Self::Queued | Self::Running { .. })
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TaskInfo {
    pub id: TaskId,
    pub title: String,
    pub state: TaskState,
}

#[derive(Debug, Default)]
struct Entries {
    next_id: u64,
    tasks: Vec<TaskInfo>,
}

/// Task list shared between task futures and the UI. Entries stay in insertion order.
#[derive(Debug, Clone, Default)]
pub struct TaskBoard {
    entries: Arc<Mutex<Entries>>,
}

impl TaskBoard {
    pub fn add(&self, title: impl Into<String>) -> TaskHandle {
        let id = {
            let mut entries = self.lock();
            let id = TaskId(entries.next_id);
            entries.next_id += 1;
            entries.tasks.push(TaskInfo {
                id,
                title: title.into(),
                state: TaskState::Queued,
            });
            id
        };
        TaskHandle {
            board: self.clone(),
            id,
        }
    }

    #[must_use]
    pub fn snapshot(&self) -> Vec<TaskInfo> {
        self.lock().tasks.clone()
    }

    #[must_use]
    pub fn has_active(&self) -> bool {
        self.lock().tasks.iter().any(|task| task.state.is_active())
    }

    fn set(&self, id: TaskId, state: TaskState) {
        if let Some(task) = self.lock().tasks.iter_mut().find(|task| task.id == id) {
            debug!(task = %task.title, ?state, "task state");
            task.state = state;
        }
    }

    fn set_transfer(&self, id: TaskId, progress: Progress) {
        if let Some(task) = self.lock().tasks.iter_mut().find(|task| task.id == id)
            && let TaskState::Running { transfer, .. } = &mut task.state
        {
            *transfer = Some(progress);
        }
    }

    fn lock(&self) -> MutexGuard<'_, Entries> {
        self.entries.lock().unwrap_or_else(PoisonError::into_inner)
    }
}

#[derive(Debug)]
pub struct TaskHandle {
    board: TaskBoard,
    id: TaskId,
}

/// Reference to one task that reports download progress. Clones share the task.
#[derive(Debug, Clone)]
pub struct TaskSink {
    board: TaskBoard,
    id: TaskId,
}

impl ProgressSink for TaskSink {
    fn report(&self, progress: Progress) {
        self.board.set_transfer(self.id, progress);
    }
}

impl TaskHandle {
    #[must_use]
    pub fn sink(&self) -> TaskSink {
        TaskSink {
            board: self.board.clone(),
            id: self.id,
        }
    }

    pub fn running(&self, done: u16, total: u16) {
        self.board.set(
            self.id,
            TaskState::Running {
                done,
                total,
                transfer: None,
            },
        );
    }

    pub fn finish<T, E: Display>(self, result: &Result<T, E>) {
        let state = match result {
            Ok(_) => TaskState::Succeeded,
            Err(error) => TaskState::Failed {
                reason: error.to_string(),
            },
        };
        self.board.set(self.id, state);
    }
}

/// Records the download progress of the current step. Ignored unless the task is running.
impl ProgressSink for TaskHandle {
    fn report(&self, progress: Progress) {
        self.board.set_transfer(self.id, progress);
    }
}

