use std::sync::Mutex;
use std::sync::atomic::{AtomicUsize, Ordering};

use launcher_core::{
    Artifact, Edition, Error, Fetcher, FileCheck, Hash, HashAlgo, Host, Installer, Instance,
    InstanceStore, Kind, Location, NewInstance, NoProgress, Package, PackageSource, Progress,
    ProgressSink, Root,
};
