/// Name resolution of every request that a `ReqwestHttp` or `ReqwestFetcher` sends.
/// The resolver starts at the first lookup.
/// A failed build or lookup falls back to the system resolver.
#[derive(Clone)]
pub struct Dns {
    servers: Arc<[IpAddr]>,
    resolver: Arc<OnceLock<Option<TokioResolver>>>,
}

impl Default for Dns {
    fn default() -> Self {
        Self::new(&[])
    }
}

impl Dns {
    /// Uses `servers`, or `ADGUARD_DNS` when `servers` is empty.
    #[must_use]
    pub fn new(servers: &[IpAddr]) -> Self {
        let servers: Arc<[IpAddr]> = if servers.is_empty() {
            Arc::from(ADGUARD_DNS.as_slice())
        } else {
            Arc::from(servers)
        };
        Self {
            servers,
            resolver: Arc::new(OnceLock::new()),
        }
    }

    fn resolver(&self) -> Option<&TokioResolver> {
        self.resolver
            .get_or_init(|| {
                let group = ServerGroup {
                    ips: &self.servers,
                    server_name: "",
                    path: "",
                };
                TokioResolver::builder_with_config(
                    ResolverConfig::udp_and_tcp(&group),
                    TokioRuntimeProvider::default(),
                )
                .build()
                .inspect_err(|error| warn!(%error, "DNS resolver build failed"))
                .ok()
            })
            .as_ref()
    }

    async fn lookup_configured(&self, host: &str) -> Option<Vec<SocketAddr>> {
        let resolver = self.resolver()?;
        match resolver.lookup_ip(host).await {
            Ok(lookup) => Some(lookup.iter().map(|ip| SocketAddr::new(ip, 0)).collect()),
            Err(error) => {
                warn!(host, %error, "configured DNS failed");
                None
            }
        }
    }

    async fn lookup(&self, host: &str) -> io::Result<Vec<SocketAddr>> {
        if let Some(addrs) = self.lookup_configured(host).await {
            return Ok(addrs);
        }
        Ok(tokio::net::lookup_host((host, 0)).await?.collect())
    }
}

impl Resolve for Dns {
    fn resolve(&self, name: Name) -> Resolving {
        let dns = self.clone();
        Box::pin(async move {
            let addrs = dns.lookup(name.as_str()).await?;
            Ok(Box::new(addrs.into_iter()) as Addrs)
        })
    }
}

//! Confirmation page of Google Drive for files above the virus-scan size limit.

use url::Url;

const DOWNLOAD_ENDPOINT: &str = "https://drive.usercontent.google.com/download";

/// Reads the download URL out of the `download-form` of a confirmation page.
/// The URL is the form action with every named input as a query parameter.
#[must_use]
pub fn confirm_url(html: &str) -> Option<Url> {
    let mut rest = html;
    while let Some(start) = rest.find("<form") {
        let (_, from_form) = rest.split_at_checked(start)?;
        let (tag, after) = split_tag(from_form)?;
        rest = after;
        if attribute(tag, "id").as_deref() != Some("download-form") {
            continue;
        }
        let body = after.split_once("</form>").map_or(after, |(body, _)| body);
        let mut url = Url::parse(&attribute(tag, "action")?).ok()?;
        for input in tags(body, "<input") {
            if let Some(name) = attribute(input, "name") {
                let value = attribute(input, "value").unwrap_or_default();
                url.query_pairs_mut().append_pair(&name, &value);
            }
        }
        return Some(url);
    }
    None
}

/// Download URL that skips the confirmation page.
#[must_use]
pub fn fallback_url(file_id: &str) -> Option<Url> {
    Url::parse_with_params(
        DOWNLOAD_ENDPOINT,
        [("id", file_id), ("export", "download"), ("confirm", "t")],
    )
    .ok()
}

/// Splits `text` after its first `>` into the tag, `>` included, and the remainder.
fn split_tag(text: &str) -> Option<(&str, &str)> {
    let end = text.find('>')?;
    text.split_at_checked(end + 1)
}

fn tags<'a>(html: &'a str, open: &'a str) -> impl Iterator<Item = &'a str> {
    html.match_indices(open).filter_map(|(start, _)| {
        let (tag, _) = split_tag(html.get(start..)?)?;
        Some(tag)
    })
}

fn attribute(tag: &str, name: &str) -> Option<String> {
    let needle = format!(" {name}=\"");
    let (_, after_needle) = tag.split_once(&needle)?;
    let (value, _) = after_needle.split_once('"')?;
    Some(unescape(value))
}

fn unescape(text: &str) -> String {
    text.replace("&quot;", "\"")
        .replace("&#39;", "'")
        .replace("&lt;", "<")
        .replace("&gt;", ">")
        .replace("&amp;", "&")
}

#[cfg(test)]
mod tests {
    use super::*;

    const PAGE: &str = r#"<html><body><form id="download-form" action="https://drive.usercontent.google.com/download" method="get"><input type="hidden" name="id" value="abc123"><input type="hidden" name="export" value="download"><input type="hidden" name="confirm" value="t"><input type="hidden" name="uuid" value="u-1&amp;x"></form></body></html>"#;

    #[test]
    fn reads_form_inputs() {
        let url = confirm_url(PAGE).expect("url");
        assert_eq!(url.host_str(), Some("drive.usercontent.google.com"));
        let pairs: Vec<(String, String)> = url
            .query_pairs()
            .map(|(k, v)| (k.into_owned(), v.into_owned()))
            .collect();
        assert_eq!(
            pairs,
            [
                ("id".to_owned(), "abc123".to_owned()),
                ("export".to_owned(), "download".to_owned()),
                ("confirm".to_owned(), "t".to_owned()),
                ("uuid".to_owned(), "u-1&x".to_owned()),
            ]
        );
    }

    #[test]
    fn ignores_other_forms() {
        let html = r#"<form id="search" action="https://example.com/"></form>"#;
        assert_eq!(confirm_url(html), None);
        assert_eq!(confirm_url("plain text"), None);
    }

    #[test]
    fn fallback_has_confirm() {
        let url = fallback_url("abc123").expect("url");
        assert_eq!(
            url.as_str(),
            "https://drive.usercontent.google.com/download?id=abc123&export=download&confirm=t"
        );
    }
}

use std::path::Path;
use std::time::{Duration, Instant};

use launcher_core::{Error, Fetcher, Progress, ProgressSink, is_allowed_url};
use reqwest::redirect::Policy;
use tokio::io::AsyncWriteExt;
use tracing::{debug, info, warn};
use url::Url;

use crate::dns::Dns;
use crate::http::{CONNECT_TIMEOUT, describe};

/// A transfer that receives no data for this long fails.
const READ_TIMEOUT: Duration = Duration::from_secs(30);
const MAX_REDIRECTS: usize = 10;
const PROGRESS_STEP: u64 = 8 * 1024 * 1024;

/// Follows a redirect when `is_allowed_url` accepts its target.
pub fn allowed_redirects() -> Policy {
    Policy::custom(|attempt| {
        if is_allowed_url(attempt.url()) {
            debug!(to = %attempt.url(), "redirect");
            attempt.follow()
        } else {
            let message = format!("redirect to {} is not allowed", attempt.url());
            warn!(to = %attempt.url(), "redirect rejected");
            attempt.error(message)
        }
    })
}

/// Streams a response body to a file. Every redirect target must satisfy `is_allowed_url`.
pub struct ReqwestFetcher {
    client: reqwest::Client,
}

impl ReqwestFetcher {
    /// Uses the default `Dns`.
    ///
    /// # Errors
    ///
    /// Returns `Error::Fetch` when the HTTP client cannot be built.
    pub fn new(user_agent: &str) -> Result<Self, Error> {
        Self::with_dns(user_agent, Dns::default())
    }

    /// Allows redirects to hosts that `is_allowed_url` accepts.
    ///
    /// # Errors
    ///
    /// Returns `Error::Fetch` when the HTTP client cannot be built.
    pub fn with_dns(user_agent: &str, dns: Dns) -> Result<Self, Error> {
        Self::build(user_agent, dns, allowed_redirects())
    }

    /// Follows redirects to any host. The caller holds the user's consent for the first URL.
    ///
    /// # Errors
    ///
    /// Returns `Error::Fetch` when the HTTP client cannot be built.
    pub fn unrestricted(user_agent: &str, dns: Dns) -> Result<Self, Error> {
        Self::build(user_agent, dns, Policy::limited(MAX_REDIRECTS))
    }

    fn build(user_agent: &str, dns: Dns, policy: Policy) -> Result<Self, Error> {
        let client = reqwest::Client::builder()
            .user_agent(user_agent)
            .redirect(policy)
            .cookie_store(true)
            .dns_resolver(dns)
            .connect_timeout(CONNECT_TIMEOUT)
            .read_timeout(READ_TIMEOUT)
            .build()
            .map_err(|e| Error::Fetch {
                url: String::new(),
                message: describe(&e),
            })?;
        Ok(Self { client })
    }
}

impl ReqwestFetcher {
    /// Sends a GET request to `target`. Errors name `origin`, the URL that the caller asked for.
    async fn request(&self, origin: &Url, target: &Url) -> Result<reqwest::Response, Error> {
        let fail = |message: String| Error::Fetch {
            url: origin.to_string(),
            message,
        };
        let started = Instant::now();
        info!(%target, "fetch start");
        let response = self.client.get(target.clone()).send().await.map_err(|e| {
            warn!(%target, error = %describe(&e), "fetch request failed");
            fail(describe(&e))
        })?;
        let status = response.status();
        info!(
            url = %origin,
            status = status.as_u16(),
            content_length = ?response.content_length(),
            elapsed_ms = started.elapsed().as_millis(),
            "fetch response"
        );
        if status.is_success() {
            Ok(response)
        } else {
            Err(fail(format!("status {}", status.as_u16())))
        }
    }
}

fn is_html(response: &reqwest::Response) -> bool {
    response
        .headers()
        .get(reqwest::header::CONTENT_TYPE)
        .and_then(|value| value.to_str().ok())
        .is_some_and(|value| value.starts_with("text/html"))
}

impl Fetcher for ReqwestFetcher {
    async fn fetch(
        &self,
        url: &Url,
        dest: &Path,
        progress: &dyn ProgressSink,
    ) -> Result<(), Error> {
        let fail = |message: String| Error::Fetch {
            url: url.to_string(),
            message,
        };
        let started = Instant::now();
        let drive_id = crate::au2pkg::extract_google_drive_id(url);
        let target_url = drive_id
            .as_deref()
            .and_then(|id| Url::parse(&crate::au2pkg::google_drive_direct_url(id)).ok())
            .unwrap_or_else(|| url.clone());
        info!(%target_url, dest = %dest.display(), "fetch");
        let mut response = self.request(url, &target_url).await?;
        if let Some(id) = drive_id.as_deref() {
            if is_html(&response) {
                let html = response.text().await.map_err(|e| fail(describe(&e)))?;
                let confirm = crate::drive::confirm_url(&html)
                    .or_else(|| crate::drive::fallback_url(id))
                    .filter(is_allowed_url)
                    .ok_or_else(|| fail("confirmation page has no download link".to_owned()))?;
                info!(%confirm, "drive confirmation");
                response = self.request(url, &confirm).await?;
            }
            if is_html(&response) {
                return Err(fail("drive returned a page instead of a file".to_owned()));
            }
        }
        let total = response.content_length();
        let mut file = tokio::fs::File::create(dest)
            .await
            .map_err(|e| fail(e.to_string()))?;
        let mut written: u64 = 0;
        progress.report(Progress { done: 0, total });
        let mut next_report = PROGRESS_STEP;
        while let Some(chunk) = response.chunk().await.map_err(|e| {
            warn!(%url, written, error = %describe(&e), "fetch body failed");
            fail(describe(&e))
        })? {
            file.write_all(&chunk)
                .await
                .map_err(|e| fail(e.to_string()))?;
            written += chunk.len() as u64;
            progress.report(Progress {
                done: written,
                total,
            });
            if written >= next_report {
                debug!(%url, written, elapsed_ms = started.elapsed().as_millis(), "fetch progress");
                next_report += PROGRESS_STEP;
            }
        }
        file.flush().await.map_err(|e| fail(e.to_string()))?;
        info!(%url, written, elapsed_ms = started.elapsed().as_millis(), "fetch done");
        Ok(())
    }
}

use std::sync::LazyLock;

use launcher_core::{
    AppSelection, AppVersion, Arch, Artifact, Bundle, Host, InstallPlan, Kind, Package,
};
use regex::Regex;
use url::Url;

use crate::release::{app_versions_from_json, parse_url};
use crate::{Http, Provider, ProviderError};

const RELEASES_URL: &str = "https://api.github.com/repos/GT-610/freya-nle/releases?per_page=30";

/// Releases before 0.8 name the Linux archive after the identifier that predates Freya NLE.
const LEGACY_LINUX_ARCHIVE: &str = "AviQtl-Arch-Linux-x86_64.zip";
const BUNDLES: [Bundle; 2] = [Bundle::Archive, Bundle::AppImage];

#[expect(clippy::expect_used, reason = "the patterns are constant literals")]
fn pattern(text: &str) -> Regex {
    Regex::new(text).expect("static regex")
}

/// `AviQtl-…` names belong to releases before 0.8. Later releases name assets
/// `Freya-NLE-<version>-<platform>.<extension>`.
static WINDOWS_ASSET: LazyLock<Regex> = LazyLock::new(|| {
    pattern(r"^(?:AviQtl-(?:MSVC|MSYS2-UCRT64)-x86_64|Freya-NLE-.+-windows-x86_64)\.zip$")
});
static LINUX_ARCHIVE: LazyLock<Regex> =
    LazyLock::new(|| pattern(r"^Freya-NLE-.+-linux-x86_64-archlinux\.tar\.zst$"));
static LINUX_APPIMAGE: LazyLock<Regex> =
    LazyLock::new(|| pattern(r"^Freya-NLE-.+-linux-x86_64\.AppImage$"));

/// macOS builds are zip archives of one `.app`. Releases up to 0.8.0 ship the arm64 build only,
/// named `Freya-NLE-macOS-Xcode-arm64.zip`, or `AviQtl-…` before 0.8.
static MACOS_ARM64_ASSET: LazyLock<Regex> = LazyLock::new(|| {
    pattern(r"^(?:Freya-NLE-.+-macos-arm64|(?:Freya-NLE|AviQtl)-macOS-Xcode-arm64)\.zip$")
});
static MACOS_X86_64_ASSET: LazyLock<Regex> =
    LazyLock::new(|| pattern(r"^Freya-NLE-.+-macos-x86_64\.zip$"));

pub struct FreyaProvider<H> {
    http: H,
}

impl<H: Http> FreyaProvider<H> {
    pub const fn new(http: H) -> Self {
        Self { http }
    }
}

fn is_asset_of(host: Host, arch: Arch, bundle: Bundle, name: &str) -> bool {
    match (host, bundle) {
        (Host::Windows, _) => WINDOWS_ASSET.is_match(name),
        (Host::Linux, Bundle::Archive) => {
            name == LEGACY_LINUX_ARCHIVE || LINUX_ARCHIVE.is_match(name)
        }
        (Host::Linux, Bundle::AppImage) => LINUX_APPIMAGE.is_match(name),
        (Host::MacOs, _) => match arch {
            Arch::Aarch64 => MACOS_ARM64_ASSET.is_match(name),
            Arch::X86_64 => MACOS_X86_64_ASSET.is_match(name),
        },
    }
}

fn is_any_asset(name: &str) -> bool {
    is_asset_of(Host::Windows, Arch::X86_64, Bundle::Archive, name)
        || BUNDLES
            .into_iter()
            .any(|bundle| is_asset_of(Host::Linux, Arch::X86_64, bundle, name))
        || [Arch::Aarch64, Arch::X86_64]
            .into_iter()
            .any(|arch| is_asset_of(Host::MacOs, arch, Bundle::Archive, name))
}

impl<H: Http> Provider for FreyaProvider<H> {
    fn kind(&self) -> Kind {
        Kind::Freya
    }

    async fn app_versions(&self) -> Result<Vec<AppVersion>, ProviderError> {
        let url = parse_url(RELEASES_URL)?;
        let bytes = self.http.get(&url).await?;
        app_versions_from_json(&bytes, is_any_asset)
    }

    fn catalog(&self) -> impl Future<Output = Result<Vec<Package>, ProviderError>> + Send {
        std::future::ready(Ok(Vec::new()))
    }

    fn plan_install_app(
        &self,
        version: &AppVersion,
        selection: AppSelection,
    ) -> Result<Vec<Artifact>, ProviderError> {
        version
            .artifacts
            .iter()
            .find(|artifact| {
                is_asset_of(
                    selection.host,
                    selection.arch,
                    selection.bundle,
                    &artifact.name,
                )
            })
            .cloned()
            .map(|artifact| vec![artifact])
            .ok_or_else(|| ProviderError::NoMatchingAsset {
                version: version.version.clone(),
            })
    }

    fn plan_install_package(
        &self,
        package: &Package,
    ) -> impl Future<Output = Result<InstallPlan, ProviderError>> + Send {
        std::future::ready(Ok(InstallPlan::OpenInBrowser(Url::clone(
            &package.page_url,
        ))))
    }
}

use regex::Regex;
