const HISTORY_URL: &str = "https://spring-fragrance.mints.ne.jp/aviutl/oldver2.php";

pub async fn fetch_page<H: Http>(http: &H) -> Result<Vec<u8>, ProviderError> {
    Ok(http.get(&parse_url(HISTORY_URL)?).await?)
}

/// `(version, archive URL)` of every match of `pattern` in `page`, in page order.
/// Capture group 1 is the link target, capture group 2 is the version.
pub fn parse_rows(page: &[u8], pattern: &str) -> Result<Vec<(String, Url)>, ProviderError> {
    let base = parse_url(HISTORY_URL)?;
    let text = String::from_utf8_lossy(page);
    let row = Regex::new(pattern).map_err(|e| ProviderError::CatalogShapeChanged(e.to_string()))?;
    row.captures_iter(&text)
        .map(|capture| {
            let url = base
                .join(&capture[1])
                .map_err(|_| ProviderError::InvalidUrl(capture[1].to_owned()))?;
            Ok((capture[2].to_owned(), url))
        })
        .collect()
}

use std::error::Error as _;
use std::future::Future;
use std::time::{Duration, Instant};

use tracing::{debug, warn};

use crate::dns::Dns;
use url::Url;

#[derive(Debug, thiserror::Error)]
pub enum HttpError {
    #[error("status {status} for {url}")]
    Status { status: u16, url: String },
    #[error("transport error for {url}: {message}")]
    Transport { url: String, message: String },
}

pub trait Http: Send + Sync {
    fn get(&self, url: &Url) -> impl Future<Output = Result<Vec<u8>, HttpError>> + Send;
}

const GITHUB_API_HOST: &str = "api.github.com";
pub const CONNECT_TIMEOUT: Duration = Duration::from_secs(15);
const REQUEST_TIMEOUT: Duration = Duration::from_secs(30);

/// Joins the message of `error` and of every error in its source chain.
pub fn describe(error: &reqwest::Error) -> String {
    let mut text = error.to_string();
    let mut source = error.source();
    while let Some(cause) = source {
        text.push_str(": ");
        text.push_str(&cause.to_string());
        source = cause.source();
    }
    if error.is_timeout() {
        text.insert_str(0, "timeout: ");
    }
    text
}

#[derive(Clone)]
pub struct ReqwestHttp {
    client: reqwest::Client,
    github_token: Option<String>,
}

impl ReqwestHttp {
    /// Uses the default `Dns`.
    ///
    /// # Errors
    ///
    /// Returns `HttpError::Transport` when the HTTP client cannot be built.
    pub fn new(user_agent: &str, github_token: Option<String>) -> Result<Self, HttpError> {
        Self::with_dns(user_agent, github_token, Dns::default())
    }

    /// Resolves names through `dns`.
    ///
    /// # Errors
    ///
    /// Returns `HttpError::Transport` when the HTTP client cannot be built.
    pub fn with_dns(
        user_agent: &str,
        github_token: Option<String>,
        dns: Dns,
    ) -> Result<Self, HttpError> {
        let client = reqwest::Client::builder()
            .user_agent(user_agent)
            .dns_resolver(dns)
            .connect_timeout(CONNECT_TIMEOUT)
            .timeout(REQUEST_TIMEOUT)
            .build()
            .map_err(|e| HttpError::Transport {
                url: String::new(),
                message: describe(&e),
            })?;
        Ok(Self {
            client,
            github_token,
        })
    }
}

impl Http for ReqwestHttp {
    async fn get(&self, url: &Url) -> Result<Vec<u8>, HttpError> {
        let started = Instant::now();
        let transport = |e: reqwest::Error| {
            let message = describe(&e);
            warn!(%url, error = %message, elapsed_ms = started.elapsed().as_millis(), "http get failed");
            HttpError::Transport {
                url: url.to_string(),
                message,
            }
        };
        debug!(%url, "http get");
        let mut request = self.client.get(url.clone());
        if url.host_str() == Some(GITHUB_API_HOST) {
            request = request.header("Accept", "application/vnd.github+json");
            if let Some(token) = &self.github_token {
                request = request.bearer_auth(token);
            }
        }
        let response = request.send().await.map_err(transport)?;
        let status = response.status();
        if !status.is_success() {
            warn!(%url, status = status.as_u16(), "http get returned an error status");
            return Err(HttpError::Status {
                status: status.as_u16(),
                url: url.to_string(),
            });
        }
        let bytes = response.bytes().await.map_err(transport)?;
        debug!(
            %url,
            status = status.as_u16(),
            bytes = bytes.len(),
            elapsed_ms = started.elapsed().as_millis(),
            "http get done"
        );
        Ok(bytes.to_vec())
    }
}

