    ProviderError, Versions, Ymm4Provider,
};

/// Kinds for which `MadokaProvider::for_kind` returns a provider.
#[must_use]
pub const fn has_provider(kind: Kind) -> bool {
    matches!(
        kind,
        Kind::Aviutl | Kind::Aviutl2 | Kind::Ymm4 | Kind::Neoutl | Kind::Freya | Kind::Macutl
    )
}

/// Kinds whose `Provider::catalog` returns packages.
#[must_use]
pub const fn has_catalog(kind: Kind) -> bool {
    matches!(kind, Kind::Aviutl | Kind::Aviutl2 | Kind::Ymm4)
}

/// Dispatches `Provider` calls by `Kind`. `Provider` is not object-safe.
pub enum MadokaProvider<H> {
    Aviutl(AviutlProvider<H>),
    Aviutl2(Aviutl2Provider<H>),
    Ymm4(Ymm4Provider<H>),
    Neoutl(NeoutlProvider<H>),
    Freya(FreyaProvider<H>),
    Macutl(MacutlProvider<H>),
}

impl<H: Http> MadokaProvider<H> {
    /// # Errors
    ///
    /// Returns `ProviderError::NoProvider` when `kind` has no provider.
    /// Every current `Kind` has one.
    pub const fn for_kind(kind: Kind, http: H) -> Result<Self, ProviderError> {
        match kind {
            Kind::Aviutl => Ok(Self::Aviutl(AviutlProvider::new(http))),
            Kind::Aviutl2 => Ok(Self::Aviutl2(Aviutl2Provider::new(http))),
            Kind::Ymm4 => Ok(Self::Ymm4(Ymm4Provider::new(http))),
            Kind::Neoutl => Ok(Self::Neoutl(NeoutlProvider::new(http))),
            Kind::Freya => Ok(Self::Freya(FreyaProvider::new(http))),
            Kind::Macutl => Ok(Self::Macutl(MacutlProvider::new(http))),
        }
    }
}

macro_rules! dispatch {
    ($self:expr, $provider:ident => $call:expr) => {
        match $self {
            Self::Aviutl($provider) => $call,
            Self::Aviutl2($provider) => $call,
            Self::Ymm4($provider) => $call,
            Self::Neoutl($provider) => $call,
            Self::Freya($provider) => $call,
            Self::Macutl($provider) => $call,
        }
    };
}

impl<H: Http> Provider for MadokaProvider<H> {
    fn kind(&self) -> Kind {
        dispatch!(self, provider => provider.kind())
    }

    async fn app_versions(&self) -> Result<Vec<AppVersion>, ProviderError> {
        dispatch!(self, provider => provider.app_versions().await)
    }

    async fn versions(&self) -> Result<Versions, ProviderError> {
        dispatch!(self, provider => provider.versions().await)
    }

    async fn catalog(&self) -> Result<Vec<Package>, ProviderError> {
        dispatch!(self, provider => provider.catalog().await)
    }

    fn plan_install_app(
        &self,
        version: &AppVersion,
        selection: AppSelection,
    ) -> Result<Vec<Artifact>, ProviderError> {
        dispatch!(self, provider => provider.plan_install_app(version, selection))
    }

    async fn plan_install_package(&self, package: &Package) -> Result<InstallPlan, ProviderError> {
        dispatch!(self, provider => provider.plan_install_package(package).await)
    }
}

use crate::{Http, HttpError};
use launcher_core::{AppVersion, Artifact, Hash};
use serde::Deserialize;
use url::Url;

use crate::ProviderError;

#[derive(Debug, Deserialize)]
pub struct Release {
    tag_name: String,
    #[serde(default)]
    draft: bool,
    #[serde(default)]
    prerelease: bool,
    published_at: Option<String>,
    #[serde(default)]
    assets: Vec<Asset>,
}

#[derive(Debug, Deserialize)]
struct Asset {
    name: String,
    size: Option<u64>,
    digest: Option<String>,
    browser_download_url: String,
}

impl Asset {
    fn into_artifact(self) -> Result<Artifact, ProviderError> {
        let url = Url::parse(&self.browser_download_url)
            .map_err(|_| ProviderError::InvalidUrl(self.browser_download_url.clone()))?;
        Ok(Artifact {
            hash: self.digest.as_deref().and_then(Hash::parse_digest),
            name: self.name,
            url,
            size: self.size,
        })
    }
}

impl Release {
    pub(crate) fn list_from_json(bytes: &[u8]) -> Result<Vec<Self>, ProviderError> {
        serde_json::from_slice(bytes).map_err(|source| ProviderError::Json {
            context: "release list",
            source,
        })
    }

    pub(crate) fn from_json(bytes: &[u8]) -> Result<Self, ProviderError> {
        serde_json::from_slice(bytes).map_err(|source| ProviderError::Json {
            context: "release",
            source,
        })
    }

    pub(crate) fn into_artifacts(self) -> Result<Vec<Artifact>, ProviderError> {
        self.assets.into_iter().map(Asset::into_artifact).collect()
    }

    /// Keeps published releases that have at least one asset accepted by `accepts`.
    pub(crate) fn into_app_version(
        self,
        accepts: impl Fn(&str) -> bool,
    ) -> Result<Option<AppVersion>, ProviderError> {
        if self.draft {
            return Ok(None);
        }
        let version = self.tag_name.clone();
        let prerelease = self.prerelease;
        let published_at = self.published_at.clone();
        let artifacts: Vec<Artifact> = self
            .into_artifacts()?
            .into_iter()
            .filter(|artifact| accepts(&artifact.name))
            .collect();
        Ok((!artifacts.is_empty()).then_some(AppVersion {
            version,
            prerelease,
            published_at,
            artifacts,
            checks: Vec::new(),
        }))
    }
}

pub fn app_versions_from_json(
    bytes: &[u8],
    accepts: impl Fn(&str) -> bool,
) -> Result<Vec<AppVersion>, ProviderError> {
    let mut versions = Vec::new();
    for release in Release::list_from_json(bytes)? {
        versions.extend(release.into_app_version(&accepts)?);
    }
    Ok(versions)
}

pub fn parse_url(text: &str) -> Result<Url, ProviderError> {
    Url::parse(text).map_err(|_| ProviderError::InvalidUrl(text.to_owned()))
}

/// Artifacts of the latest release of `owner/repo`. `None` when the repository has no release.
pub async fn latest_artifacts<H: Http>(
    http: &H,
    owner: &str,
    repo: &str,
) -> Result<Option<Vec<Artifact>>, ProviderError> {
    let url = parse_url(&format!(
        "https://api.github.com/repos/{owner}/{repo}/releases/latest"
    ))?;
    match http.get(&url).await {
        Ok(bytes) => Ok(Some(Release::from_json(&bytes)?.into_artifacts()?)),
        Err(HttpError::Status { status: 404, .. }) => Ok(None),
        Err(error) => Err(error.into()),
    }
}

use std::fmt::Display;
use std::path::PathBuf;
use std::sync::Arc;

use launcher_core::{Progress, ProgressSink};
use self_update::backends::github::Update;
use tracing::info;

use crate::ProviderError;
use crate::dns::Dns;
use crate::fetch::allowed_redirects;
use crate::http::CONNECT_TIMEOUT;

const REPO_OWNER: &str = "TeamNeoUtl";
const REPO_NAME: &str = "Madoka-launcher";
const LAUNCHER_BIN: &str = "Madoka-Launcher";
const BROWSER_BIN: &str = "Madoka-Browser";
const TARGET: &str = if cfg!(windows) {
    "windows-x86_64"
} else if cfg!(all(target_os = "macos", target_arch = "aarch64")) {
    "macos-arm64"
} else if cfg!(target_os = "macos") {
    "macos-x86_64"
} else {
    "linux-x86_64"
};
/// Layout of the release archive built by `release.yml`.
const BIN_PATH_IN_ARCHIVE: &str = "Madoka-launcher-v{{ version }}-{{ target }}/{{ bin }}";

/// Checks the GitHub Releases of the launcher and replaces the executables.
/// Methods block the calling thread. Run them on a blocking worker.
#[derive(Clone)]
pub struct SelfUpdater {
    user_agent: String,
    dns: Dns,
    token: Option<String>,
    current_version: String,
    api_base_url: Option<String>,
}

impl SelfUpdater {
    #[must_use]
    pub fn new(user_agent: &str, dns: Dns, token: Option<String>, current_version: &str) -> Self {
        Self {
            user_agent: user_agent.to_owned(),
            dns,
            token,
            current_version: current_version.to_owned(),
            api_base_url: None,
        }
    }

    /// Requests `url` instead of `https://api.github.com`.
    #[must_use]
    pub fn with_api_base_url(mut self, url: &str) -> Self {
        self.api_base_url = Some(url.to_owned());
        self
    }

    /// Returns the version of the latest release when it is newer than the running version.
    ///
    /// # Errors
    ///
    /// Returns `ProviderError::SelfUpdate` when the request fails or the release tag is not a version.
    pub fn check(&self) -> Result<Option<String>, ProviderError> {
        let releases = self
            .configure(LAUNCHER_BIN, None, None, None)?
            .get_latest_release()
            .map_err(failed)?;
        let newer = releases.is_update_available().map_err(failed)?;
        let version = releases
            .latest()
            .filter(|_| newer)
            .map(|release| release.version().to_owned());
        info!(current = %self.current_version, latest = ?version, "self update check");
        Ok(version)
    }

    /// Installs release `version`. `Madoka-Browser` is replaced before `Madoka-Launcher`.
    /// Each download is verified against the digest that GitHub publishes for the asset.
    ///
    /// # Errors
    ///
    /// Returns `ProviderError::SelfUpdate` when a download, a verification, or a replacement fails.
    pub fn update(
        &self,
        version: &str,
        progress: &Arc<dyn ProgressSink>,
    ) -> Result<(), ProviderError> {
        let tag = format!("v{version}");
        let browser = std::env::current_exe()
            .map_err(failed)?
            .with_file_name(browser_file_name());
        for (bin, install_path) in [(BROWSER_BIN, Some(browser)), (LAUNCHER_BIN, None)] {
            info!(bin, %tag, "self update install");
            self.configure(bin, install_path, Some(&tag), Some(progress))?
                .update_extended()
                .map_err(failed)?;
        }
        Ok(())
    }

    fn configure(
        &self,
        bin: &str,
        install_path: Option<PathBuf>,
        tag: Option<&str>,
        progress: Option<&Arc<dyn ProgressSink>>,
    ) -> Result<Update, ProviderError> {
        let client = reqwest::blocking::Client::builder()
            .user_agent(&self.user_agent)
            .redirect(allowed_redirects())
            .dns_resolver(Arc::new(self.dns.clone()))
            .connect_timeout(CONNECT_TIMEOUT)
            .build()
            .map_err(failed)?;
        let mut builder = Update::configure();
        builder
            .repo_owner(REPO_OWNER)
            .repo_name(REPO_NAME)
            .target(TARGET)
            .bin_name(bin)
            .bin_path_in_archive(BIN_PATH_IN_ARCHIVE)
            .current_version(self.current_version.as_str())
            .reqwest_client(client)
            .check_install_path_writable(true)
            .show_download_progress(false)
            .unattended();
        if let Some(url) = &self.api_base_url {
            builder.api_base_url(url.as_str());
        }
        if let Some(token) = &self.token {
            builder.auth_token(token.as_str());
        }
        if let Some(path) = install_path {
            builder.bin_install_path(path);
        }
        if let Some(tag) = tag {
            builder.release_tag(tag);
        }
        if let Some(progress) = progress {
            let progress = Arc::clone(progress);
            builder.progress_callback(move |done, total| progress.report(Progress { done, total }));
        }
        builder.build().map_err(failed)
    }
}

const fn browser_file_name() -> &'static str {
    if cfg!(windows) {
        "Madoka-Browser.exe"
    } else {
        BROWSER_BIN
    }
}

fn failed(error: impl Display) -> ProviderError {
    ProviderError::SelfUpdate(error.to_string())
}

use std::sync::LazyLock;

use launcher_core::{
    AppSelection, AppVersion, Artifact, Edition, Host, InstallPlan, Kind, Package, PackageSource,
    Relations,
};
use regex::Regex;
use serde::Deserialize;
use url::Url;

use crate::release::{Release, app_versions_from_json, parse_url};
use crate::{Http, HttpError, Provider, ProviderError};

const REPO: &str = "manju-summoner/YukkuriMovieMaker4";
const PLUGIN_INDEX_URL: &str = "https://manjubox.net/ymm4plugins.yml";
const LITE_SUFFIX: &str = "_Lite.zip";
const PLUGIN_EXTENSION: &str = ".ymme";
const GITHUB_HOST: &str = "github.com";

#[expect(clippy::expect_used, reason = "the pattern is a constant literal")]
static APP_ASSET: LazyLock<Regex> = LazyLock::new(|| {
    Regex::new(r"^YukkuriMovieMaker_v[0-9.]+(_Lite)?\.zip$").expect("static regex")
});

pub struct Ymm4Provider<H> {
    http: H,
}

impl<H: Http> Ymm4Provider<H> {
    pub const fn new(http: H) -> Self {
        Self { http }
    }
}

fn edition_of(asset_name: &str) -> Edition {
    if asset_name.ends_with(LITE_SUFFIX) {
        Edition::Lite
    } else {
        Edition::Normal
    }
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct RawEntry {
    r#type: String,
    date: String,
    name: String,
    url: String,
    author: String,
    description: String,
    #[serde(default = "enabled_by_default")]
    is_enabled: bool,
}

const fn enabled_by_default() -> bool {
    true
}

fn github_repo(url: &Url) -> Option<(String, String)> {
    if url.host_str() != Some(GITHUB_HOST) {
        return None;
    }
    let segments: Vec<&str> = url.path_segments()?.filter(|s| !s.is_empty()).collect();
    match segments.as_slice() {
        [owner, repo] => Some(((*owner).to_owned(), (*repo).to_owned())),
        _ => None,
    }
}

fn shape_changed(message: impl Into<String>) -> ProviderError {
    ProviderError::CatalogShapeChanged(message.into())
}

/// # Errors
///
/// Returns `ProviderError::CatalogShapeChanged` when `bytes` is not the expected YAML,
/// holds no entry, or an entry has an invalid URL.
pub fn parse_ymm4_catalog(bytes: &[u8]) -> Result<Vec<Package>, ProviderError> {
    let entries: Vec<RawEntry> =
        serde_yaml_ng::from_slice(bytes).map_err(|e| shape_changed(e.to_string()))?;
    if entries.is_empty() {
        return Err(shape_changed("no entries"));
    }
    let mut packages = Vec::new();
    for entry in entries.into_iter().filter(|entry| entry.is_enabled) {
        let page_url = Url::parse(&entry.url)
            .map_err(|_| shape_changed(format!("invalid url: {}", entry.url)))?;
        let (id, source) = match github_repo(&page_url) {
            Some((owner, repo)) => (
                format!("github:{owner}/{repo}"),
                PackageSource::GithubRepo { owner, repo },
            ),
            None => (page_url.to_string(), PackageSource::Web(page_url.clone())),
        };
        packages.push(Package {
            id,
            name: entry.name,
            summary: entry.description,
            author: entry.author,
            categories: entry
                .r#type
                .split(',')
                .map(str::trim)
                .filter(|category| !category.is_empty())
                .map(str::to_owned)
                .collect(),
            release_dates: vec![entry.date.clone()],
            updated: Some(entry.date),
            page_url,
            source,
            niconi_commons_id: None,
            tags: Vec::new(),
            deprecated: false,
            deprecation_message: None,
            notice: None,
            dependencies: Vec::new(),
            relations: Relations::default(),
            licenses: Vec::new(),
            changelog: None,
            screenshots: Vec::new(),
        });
    }
    if packages.is_empty() {
        return Err(shape_changed("no enabled entries"));
    }
    Ok(packages)
}

impl<H: Http> Provider for Ymm4Provider<H> {
    fn kind(&self) -> Kind {
        Kind::Ymm4
    }

    async fn app_versions(&self) -> Result<Vec<AppVersion>, ProviderError> {
        let url = parse_url(&format!(
            "https://api.github.com/repos/{REPO}/releases?per_page=30"
        ))?;
        let bytes = self.http.get(&url).await?;
        app_versions_from_json(&bytes, |name| APP_ASSET.is_match(name))
    }

    async fn catalog(&self) -> Result<Vec<Package>, ProviderError> {
        let url = parse_url(PLUGIN_INDEX_URL)?;
        let bytes = self.http.get(&url).await?;
        parse_ymm4_catalog(&bytes)
    }

    fn plan_install_app(
        &self,
        version: &AppVersion,
        selection: AppSelection,
    ) -> Result<Vec<Artifact>, ProviderError> {
        if selection.host != Host::Windows {
            return Err(ProviderError::UnsupportedHost {
                kind: Kind::Ymm4,
                host: selection.host,
            });
        }
        version
            .artifacts
            .iter()
            .find(|artifact| edition_of(&artifact.name) == selection.edition)
            .cloned()
            .map(|artifact| vec![artifact])
            .ok_or_else(|| ProviderError::NoMatchingAsset {
                version: version.version.clone(),
            })
    }

    async fn plan_install_package(&self, package: &Package) -> Result<InstallPlan, ProviderError> {
        let browser = || InstallPlan::OpenInBrowser(package.page_url.clone());
        let PackageSource::GithubRepo { owner, repo } = &package.source else {
            return Ok(browser());
        };
        let url = parse_url(&format!(
            "https://api.github.com/repos/{owner}/{repo}/releases/latest"
        ))?;
        let bytes = match self.http.get(&url).await {
            Ok(bytes) => bytes,
            Err(HttpError::Status { status: 404, .. }) => return Ok(browser()),
            Err(error) => return Err(error.into()),
        };
        let mut plugins: Vec<Artifact> = Release::from_json(&bytes)?
            .into_artifacts()?
            .into_iter()
            .filter(|artifact| {
                artifact
                    .name
                    .to_ascii_lowercase()
                    .ends_with(PLUGIN_EXTENSION)
            })
            .collect();
        Ok(match plugins.len() {
            1 => InstallPlan::Download(std::mem::take(&mut plugins)),
            _ => browser(),
        })
    }
}

